const LEAD_COLS = new Set([
  'phone', 'normalized_phone', 'status', 'source', 'batch_id', 'country', 'region',
  'name', 'photo', 'socials', 'linkedin', 'email', 'company', 'position',
  'line_type', 'carrier', 'sources', 'conflicts', 'dismissed', 'active_tool',
  'org_status', 'org_note', 'theorg_slug', 'icp_fit', 'icp_reasons',
  'company_li_id', 'open_positions', 'positions_checked_at', 'outreach_lang', 'client_id',
  'steps',
  'company_staff_count', 'company_context', 'company_checked_at',
]);

// ── the enrichment chain, as data ────────────────────────────────────────────
// The six steps enrichFullOne runs, in order, each with the predicate that
// decides whether a call that RAN actually found anything. `label` travels with
// the persisted record so a surface renders what the chain reports rather than
// keeping its own copy of the step list.
const ENRICH_STEPS = [
  { key: 'wa',      label: 'WhatsApp', found: (r) => !!(r.name || r.photo || r.about || r.on_whatsapp) },
  { key: 'li',      label: 'LinkedIn', found: (r) => !!r.company },
  { key: 'pdl',     label: 'PDL',      found: (r) => !!(r.matched && (r.name || r.company)) },
  { key: 'twilio',  label: 'Twilio',   found: (r) => !!(r.line_type || r.carrier || r.caller_name) },
  { key: 'serp',    label: 'SerpApi',  found: (r) => (r.added || 0) > 0 || (r.linkedin_verified || 0) > 0 },
  { key: 'confirm', label: 'Confirm',  found: (r) => !!r.company },
];

// Steps outside the enrichment chain (the manual ICP match) live in the SAME
// steps column; every chain writer must carry them forward or a re-enrich
// silently erases the record of a run it knows nothing about.
const ENRICH_KEYS = new Set(ENRICH_STEPS.map((d) => d.key));
const foreignSteps = (prior) => (Array.isArray(prior) ? prior : []).filter((s) => s && !ENRICH_KEYS.has(s.key));

// Turn one step's return value into a persisted verdict. Every step returns
// either data, {skipped:<why>}, or {error:<msg>} — this is the only place that
// mapping lives, so "why is that dot amber" has exactly one answer.
function stepVerdict(def, r, at) {
  const base = { key: def.key, label: def.label, at };
  if (!r || typeof r !== 'object') return { ...base, status: 'empty', reason: null };
  if (r.skipped)         return { ...base, status: 'skipped', reason: String(r.skipped) };
  if (r.error)           return { ...base, status: 'error',   reason: String(r.error) };
  if (r.matched === false) return { ...base, status: 'empty', reason: 'no match for this phone number' };
  const found = def.found(r);
  return { ...base, status: found ? 'found' : 'empty', reason: found ? null : (r.note ? String(r.note) : null) };
}

export async function getLead(api, id) {
  return api.db.prepare('SELECT * FROM plugin_gtm_leads WHERE id = ?').bind(id).first();
}

export async function listLeads(api, { batch_id = null, status = null, q = null, stage = null, limit = 500 } = {}) {
  const where = [];
  const binds = [];
  if (batch_id) { where.push('batch_id = ?'); binds.push(batch_id); }
  if (status)   { where.push('status = ?');   binds.push(status); }
  if (q)        { where.push('(name LIKE ? OR company LIKE ? OR phone LIKE ?)'); binds.push(`%${q}%`, `%${q}%`, `%${q}%`); }
  if (stage === 'green') {
    // SQL prefilter — a strict SUPERSET of leadState's green (two-word name +
    // company + linkedin-ish + position); leadState below stays the authority.
    // Without this, stage:'green' hauled EVERY lead's wide row (big JSON
    // columns) out of D1 just to keep the green few — ~12s reads once the
    // first big import landed.
    where.push(`name LIKE '% %' AND company IS NOT NULL AND position IS NOT NULL AND (linkedin IS NOT NULL OR socials LIKE '%linkedin%')`);
  }
  const sql = `SELECT * FROM plugin_gtm_leads ${where.length ? 'WHERE ' + where.join(' AND ') : ''} ORDER BY created_at DESC LIMIT ?`;
  const r = await api.db.prepare(sql).bind(...binds, Math.min(500, limit)).all();
  let leads = r.results || [];
  if (stage) leads = leads.filter((l) => leadState(l) === stage);
  return leads.map((l) => ({
    ...l,
    state: leadState(l),
    confidence: evaluateConfidence(l),
    truecaller_url: truecallerUrl(l.normalized_phone || l.phone),
    // null on leads enriched before 0056 — the surface falls back to inferring
    // from provenance for those rather than showing them as never-run.
    steps: parseJson(l.steps, null),
  }));
}

export async function updateLead(api, id, fields) {
  const cols = Object.keys(fields || {}).filter((k) => LEAD_COLS.has(k));
  if (!cols.length) return getLead(api, id);
  const sets = cols.map((c) => `${c} = ?`).join(', ');
  const vals = cols.map((c) => fields[c] ?? null);
  await api.db.prepare(`UPDATE plugin_gtm_leads SET ${sets}, updated_at = ? WHERE id = ?`)
    .bind(...vals, now(), id).run();
  return getLead(api, id);
}

export async function findByPhone(api, normalized) {
  return api.db.prepare('SELECT * FROM plugin_gtm_leads WHERE normalized_phone = ? LIMIT 1').bind(normalized).first();
}

// new_count powers the module's auto-resume: on mount it looks for any batch
// still carrying un-enriched leads (the client-side enrich loop died mid-run —
// tab switch, closed browser, network blip) and picks the drain back up
// without the operator having to notice or click anything.
export async function listBatches(api) {
  const r = await api.db.prepare(
    `SELECT b.*, (SELECT COUNT(*) FROM plugin_gtm_leads l WHERE l.batch_id = b.id AND l.status = 'new') AS new_count
     FROM plugin_gtm_batches b ORDER BY b.created_at DESC LIMIT 100`,
  ).all();
  return r.results || [];
}

// A linkedin.com/company/ page is the COMPANY, never the person — and it can
// arrive in either place a person's profile is read from (the `linkedin` column
// or a socials entry typed 'linkedin'). One definition, so completeness, the
// "needs" hint and the rendered profile link can never disagree.
export const isCompanyLinkedin = (u) => /linkedin\.com\/company\//i.test(String(u || ''));
const personLinkedin = (lead, socials) =>
  (lead.linkedin && !isCompanyLinkedin(lead.linkedin) ? lead.linkedin : null)
  || (socials.find((s) => s.type === 'linkedin' && !isCompanyLinkedin(s.url))?.url ?? null);

// Enrichment signal (matches the UI dot): green = first + last name + company +
// linkedin + position; red = none; yellow = partial. Green gates Enrich+Outreach.
export function leadState(lead) {
  let socials = [];
  try { socials = lead.socials ? JSON.parse(lead.socials) : []; } catch { socials = []; }
  const parts = String(lead.name || '').trim().split(/\s+/).filter(Boolean);
  const signals = [
    parts.length >= 1,
    parts.length >= 2,
    !!lead.company,
    // The PERSON's profile. A /company/ page is not one, in EITHER place it can
    // land — counting it made a lead read green while the very same row reported
    // "needs: linkedin", and green gates Qualification + Outreach.
    !!personLinkedin(lead, socials),
    !!lead.position,
  ];
  const n = signals.filter(Boolean).length;
  return n === signals.length ? 'green' : n === 0 ? 'red' : 'yellow';
}

// ── confidence (derived-on-read, like leadState) ─────────────────────────────
// Distinct from leadState, which measures COMPLETENESS (do we have the fields).
// Confidence measures whether the identity HOLDS TOGETHER across sources — the
// "this might be the wrong person" signal. Pure function of the lead's own
// persisted fields (conflicts, sources, linkedin, line_type), so it is always
// fresh: the next read after an enrich or a manual edit recomputes it from the
// new data, no stored column to go stale. Returns { score 0-100, level
// 'green'|'yellow', flags: [{severity, label, detail}] }.
function prettyTool(t) {
  const map = {
    wa_fetch_name: 'WhatsApp', wa_fetch_photo: 'WhatsApp',
    pdl_enrich: 'People Data Labs', twilio_lookup: 'Twilio caller ID',
    serp_search: 'Google', manual: 'your manual edit',
    company_from_linkedin: 'LinkedIn', linkedin_company: 'LinkedIn',
  };
  return map[t] || t || 'a source';
}
function confNameTokens(name) {
  return String(name || '').toLowerCase()
    .replace(/[^a-zÀ-ɏ\s'-]/g, ' ')
    .split(/[\s'-]+/).filter((t) => t.length >= 2);
}
export function linkedinSlug(url) {
  const m = /linkedin\.com\/in\/([^/?#]+)/i.exec(String(url || ''));
  if (!m) return null;
  try { return decodeURIComponent(m[1]).toLowerCase(); } catch { return m[1].toLowerCase(); }
}

// ── linkedin identity verification ──────────────────────────────────────────
// The cardinal rule: a LinkedIn profile is only THIS lead's profile if the
// names are a relative match (a little different is fine — nicknames,
// transliteration; wildly different is a namesake/wrong person). We verify
// against two independent signals: the profile URL slug (usually the
// latinized name) and the search-result title ("Name - Title | LinkedIn").

// Hebrew-name transliteration variants (shachar/shahar, yitzchak/yitzhak…):
// normalize both sides the same way so spelling variance doesn't read as a
// different person.
const translit = (t) => t.replace(/ch/g, 'h').replace(/ph/g, 'f').replace(/ck/g, 'k');
const latinToks = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .split(/[^a-z]+/).filter((t) => t.length >= 2).map(translit);

function lev2(a, b) {
  if (Math.abs(a.length - b.length) > 2) return 3;
  const dp = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) dp[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) {
    dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  }
  return dp[a.length][b.length];
}

const tokStrongMatch = (a, b) =>
  a === b
  || (Math.min(a.length, b.length) >= 3 && (a.startsWith(b) || b.startsWith(a)))
  || (Math.min(a.length, b.length) >= 4 && lev2(a, b) <= 1)
  // squished-name slugs ("orlatovitz", "yorubin") — the name token appears
  // INSIDE the concatenated slug token; require ≥4 chars so tiny tokens don't
  // false-match
  || (Math.min(a.length, b.length) >= 4 && (a.includes(b) || b.includes(a)));

// How many of the lead's name tokens find a counterpart in the candidate tokens.
function nameTokenOverlap(leadName, candidateToks) {
  const nToks = latinToks(leadName);
  if (!nToks.length || !candidateToks.length) return { overlap: 0, verifiable: false, total: nToks.length };
  const overlap = nToks.filter((n) => candidateToks.some((c) => tokStrongMatch(n, c))).length;
  return { overlap, verifiable: true, total: nToks.length };
}

// Slug vs lead name: 'match' | 'mismatch' | 'unverifiable' (Hebrew-only name,
// or an opaque/custom slug that carries no name tokens).
export function slugNameCheck(leadName, url) {
  const slug = linkedinSlug(url);
  if (!slug) return 'unverifiable';
  const slugToks = slug.split(/[-_.]/).filter((t) => t.length >= 3 && !/^\d+$/.test(t) && !/^[0-9a-f]{6,}$/.test(t)).map(translit);
  if (!slugToks.length) return 'unverifiable';
  const { overlap, verifiable, total } = nameTokenOverlap(leadName, slugToks);
  if (!verifiable) return 'unverifiable';
  if (overlap === 0) return 'mismatch';
  // one shared token on a multi-token name (e.g. only the first name) is weak —
  // exactly the namesake trap — unless the slug itself only carries one token.
  if (total >= 2 && overlap < 2 && slugToks.length >= 2) return 'mismatch';
  return 'match';
}

// Does a LinkedIn search result belong to this lead? 'yes' | 'no' | 'unknown'.
// title is the SERP result title, e.g. "Dana Levin - VP Product at X | LinkedIn".
export function linkedinBelongsTo(leadName, { url, title }) {
  const slugVerdict = slugNameCheck(leadName, url);
  const t = String(title || '').replace(/\s*[|–-]\s*LinkedIn.*$/i, '');
  const titleName = t.split(' - ')[0].trim();
  const { overlap, verifiable, total } = nameTokenOverlap(leadName, latinToks(titleName));
  const titleStrong = verifiable && (total >= 2 ? overlap >= 2 : overlap >= 1);
  const titleZero = verifiable && overlap === 0 && latinToks(titleName).length >= 2;
  if (titleStrong || slugVerdict === 'match') {
    // positive evidence wins unless the OTHER signal outright contradicts
    if (slugVerdict === 'mismatch' && !titleStrong) return 'no';
    if (titleZero && slugVerdict !== 'match') return 'no';
    return 'yes';
  }
  if (slugVerdict === 'mismatch' || titleZero) return 'no';
  return 'unknown'; // cross-script name (e.g. Hebrew vs Latin) or opaque slug — cannot verify
}

// Levenshtein-tolerant person-name match (<=2 edits on first AND last token).
// Lives here because reconcileIdentity runs the CEO-mismatch heuristic — one
// definition, so "is this org root the lead" has one answer.
function levName(a, b) {
  const m = a.length, n = b.length;
  if (Math.abs(m - n) > 2) return 3;
  const d = Array.from({ length: m + 1 }, (_, i) => [i, ...Array(n).fill(0)]);
  for (let j = 0; j <= n; j++) d[0][j] = j;
  for (let i = 1; i <= m; i++) for (let j = 1; j <= n; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[m][n];
}

export function namesMatch(a, b) {
  const ta = String(a || '').toLowerCase().trim().split(/\s+/).filter(Boolean);
  const tb = String(b || '').toLowerCase().trim().split(/\s+/).filter(Boolean);
  if (!ta.length || !tb.length) return false;
  const first = levName(ta[0], tb[0]) <= 2 && Math.min(ta[0].length, tb[0].length) >= 3 ? true : ta[0] === tb[0];
  const la = ta[ta.length - 1], lb = tb[tb.length - 1];
  const last = ta.length < 2 || tb.length < 2 ? true : (levName(la, lb) <= 2 && Math.min(la.length, lb.length) >= 3 ? true : la === lb);
  return first && last;
}

export function evaluateConfidence(lead) {
  const flags = [];       // problems, worst-first
  const positives = [];   // reasons to trust it (shown on green)
  const conflicts = parseJson(lead.conflicts, []);
  const sources = parseJson(lead.sources, {});
  const nToks = confNameTokens(lead.name);
  const hasName = nToks.length >= 1;
  const hasFullName = nToks.length >= 2;
  const nameSrc = sources?.name?.tool;

  // ── Evidence: how much identity we actually hold. This is the base — an
  //    empty lead has NOTHING to be confident about, so it starts near zero
  //    (the old model started at 100 and only subtracted for contradictions,
  //    which is why a blank profile read 100%).
  let score = 0;
  if (hasFullName) score += 28;
  else if (hasName) score += 13;
  if (lead.linkedin) score += 20;
  if (lead.company)  score += 12;
  if (lead.position) score += 8;
  if (lead.email)    score += 8;

  // ── Consistency: recorded source conflicts. The enrichers log a name
  //    conflict exactly when e.g. WhatsApp and PDL/Twilio disagree — the case
  //    the operator described. A hard conflict caps the dot at yellow.
  let hardConflict = false;
  for (const c of (Array.isArray(conflicts) ? conflicts : [])) {
    if (!c || !c.value) continue;
    if (c.field === 'name') {
      hardConflict = true; score -= 40;
      flags.push({ severity: 'high', label: 'Name mismatch',
        detail: `On file "${lead.name || '?'}", but ${prettyTool(c.tool)} says "${c.value}".` });
    } else if (c.field === 'company') {
      score -= 16;
      flags.push({ severity: 'medium', label: 'Company mismatch',
        detail: `On file "${lead.company || '?'}", but ${prettyTool(c.tool)} says "${c.value}".` });
    } else {
      score -= 6;
      flags.push({ severity: 'low', label: `${c.field} mismatch`,
        detail: `${prettyTool(c.tool)} says "${c.value}".` });
    }
  }

  // ── LinkedIn slug vs name: corroboration when it matches, contradiction
  //    when it doesn't (the "this profile is someone else" check).
  let liMatchesName = false;
  if (lead.linkedin && hasName) {
    const slug = linkedinSlug(lead.linkedin);
    if (slug) {
      const slugToks = slug.split(/[-_.]/)
        .filter((t) => t.length >= 3 && !/^\d+$/.test(t) && !/^[0-9a-f]{6,}$/.test(t));
      if (slugToks.length >= 1) {
        const overlap = slugToks.filter((t) => nToks.some((n) => n === t || n.startsWith(t) || t.startsWith(n)));
        if (overlap.length) { liMatchesName = true; score += 12; }
        else {
          hardConflict = true; score -= 35;
          flags.push({ severity: 'high', label: 'LinkedIn does not match name',
            detail: `The linked profile /in/${slug} does not match the name "${lead.name}".` });
        }
      }
    }
  }

  // ── Low-evidence notices — the reasons a thin lead is NOT trustworthy yet.
  if (!hasName) {
    flags.push({ severity: 'high', label: 'No identity yet',
      detail: 'Only a phone number so far — nothing to verify. Run enrich to try to identify the person.' });
  } else if (!lead.linkedin && !lead.email && !lead.company) {
    flags.push({ severity: 'medium', label: 'Thin, unconfirmed profile',
      detail: `Name from ${prettyTool(nameSrc)} with no LinkedIn, company, or email to confirm it belongs to this number.` });
  }

  // ── Non-mobile line — a landline/VOIP often carries a business name.
  if (lead.line_type && !/mobile|wireless/i.test(lead.line_type)) {
    score -= 5;
    flags.push({ severity: 'low', label: `${lead.line_type} line`,
      detail: `Twilio reports a ${lead.line_type} line${lead.carrier ? ` (${lead.carrier})` : ''}; the name may be a business, not the person.` });
  }

  // ── Positive corroboration — why a clean lead earns its green.
  if (!hardConflict) {
    if (liMatchesName) positives.push('LinkedIn profile matches the name');
    if (hasFullName && lead.company && lead.position) positives.push('Full name, company, and role on file');
    if (nameSrc === 'pdl_enrich' || nameSrc === 'manual') positives.push(`Name confirmed via ${prettyTool(nameSrc)}`);
  }

  score = Math.max(0, Math.min(100, score));
  // red   = no usable identity to judge (nothing to be confident about)
  // yellow = a flagged inconsistency, or partial/unconfirmed data
  // green  = well-corroborated and consistent
  const level = !hasName ? 'red'
    : hardConflict ? 'yellow'
    : score >= 75 ? 'green'
    : 'yellow';
  return { score, level, flags, positives };
}

// ── provenance helpers ───────────────────────────────────────────────────────

// The merges themselves are pure and return VALUES; the *string* variants below
// are what the column writers want. reconcileIdentity needs the values (it hands
// JSON across the workflow context, where a pre-stringified column is opaque).
export function mergedSources(lead, upd) {
  let s = {};
  try { s = lead.sources ? JSON.parse(lead.sources) : {}; } catch { s = {}; }
  const at = new Date().toISOString();
  for (const [field, tool] of Object.entries(upd || {})) s[field] = { tool, at };
  return s;
}

export function mergedConflicts(lead, adds) {
  let c = [];
  try { c = lead.conflicts ? JSON.parse(lead.conflicts) : []; } catch { c = []; }
  const at = new Date().toISOString();
  // dedupe on field+value — re-running an enricher must not stack the same
  // conflict (the rejected-linkedin path re-fires on every serp pass)
  for (const a of adds) {
    if (c.some((x) => x.field === a.field && x.value === a.value)) continue;
    c.push({ ...a, at });
  }
  return c;
}

function mergeSources(lead, upd) { return JSON.stringify(mergedSources(lead, upd)); }
function mergeConflicts(lead, adds) { return JSON.stringify(mergedConflicts(lead, adds)); }

function parseJson(s, dflt) { try { return s ? JSON.parse(s) : dflt; } catch { return dflt; } }

// ── import: phone list → lead rows ──────────────────────────────────────────

async function toNumbers(api, { text, url }) {
  if (url && String(url).trim()) {
    const r = await api.gateway('web', 'text', { url, max_bytes: 2_000_000 });
    if (!r.ok) throw new Error(`url fetch HTTP ${r.status}`);
    text = r.text;
  }
  return parsePhoneList(text || '');
}

export async function importLeads(api, { text, url, source } = {}) {
  const via = url && String(url).trim() ? 'url' : 'paste';
  const batch_id = gid('gb');
  const numbers = await toNumbers(api, { text, url });
  let valid = 0, invalid = 0, duplicates = 0, created = 0;
  for (const number of numbers) {
    const n = normalizePhone(number);
    if (!n.valid) { invalid++; continue; }
    valid++;
    if (await findByPhone(api, n.normalized)) { duplicates++; continue; }
    const g = locatePhone(n.normalized);
    await api.db.prepare(`
      INSERT INTO plugin_gtm_leads (id, phone, normalized_phone, status, source, batch_id, country, region, created_at, updated_at)
      VALUES (?, ?, ?, 'new', ?, ?, ?, ?, ?, ?)
    `).bind(gid('gl'), number, n.normalized, source || null, batch_id, g.country, g.region, now(), now()).run();
    created++;
  }
  const summary = { total: numbers.length, valid, invalid, duplicates, created, batch_id: created > 0 ? batch_id : null, via, source: source || null };
  if (created > 0) {
    await api.db.prepare('INSERT INTO plugin_gtm_batches (id, source, via, total, created, duplicates, invalid, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
      .bind(batch_id, source || null, via, numbers.length, created, duplicates, invalid, now()).run();
  }
  await api.log('leads_imported', summary);
  return summary;
}

// ── SaaS lookups (via the host gateways; each degrades to {skipped} without
//    its key, exactly as before — the gateway carries the secret + the usage
//    meter, the plugin never sees a credential) ────────────────────────────────

export async function pdlEnrich(api, { phone, name, region, country } = {}) {
  return api.gateway('pdl', 'person', { phone, name, region, country });
}

export async function twilioLookup(api, number) {
  return api.gateway('twilio', 'lookup', { phone: number });
}

export async function serpSearch(api, { q, engine = 'google', num = 10, url } = {}) {
  return api.gateway('serp', 'search', { q, engine, num, url });
}

// ── small shared LLM helper ─────────────────────────────────────────────────

export async function gtmLLM(api, { system, prompt, model = null, maxTokens = 4000, heavy = false } = {}) {
  // Delegates to the single LLM boundary (the llm gateway): provider switch,
  // circuit breaker (light calls fall back local; heavy:true throws LlmDownError
  // so outreach drafting pauses rather than running on a 3B), and retry all
  // live there. Signature kept so GTM call sites stay untouched.
  return api.gateway('llm', 'text', { system, prompt, model, max_tokens: maxTokens, heavy });
}

export function extractJson(txt) {
  const s = String(txt || '');
  return JSON.parse(s.slice(s.indexOf('{'), s.lastIndexOf('}') + 1));
}

// ── socials extraction (regex over known hosts; optional website fetch) ─────

const SOCIAL = [
  ['linkedin', /(?:[\w.-]*\.)?linkedin\.com\/[^\s"'<>)]+/ig],
  ['twitter', /(?:[\w.-]*\.)?(?:twitter\.com|x\.com)\/[^\s"'<>)]+/ig],
  ['instagram', /(?:[\w.-]*\.)?instagram\.com\/[^\s"'<>)]+/ig],
  ['facebook', /(?:[\w.-]*\.)?(?:facebook\.com|fb\.com)\/[^\s"'<>)]+/ig],
  ['github', /(?:[\w.-]*\.)?github\.com\/[^\s"'<>)]+/ig],
  ['youtube', /(?:[\w.-]*\.)?(?:youtube\.com|youtu\.be)\/[^\s"'<>)]+/ig],
  ['tiktok', /(?:[\w.-]*\.)?tiktok\.com\/[^\s"'<>)]+/ig],
  ['telegram', /t\.me\/[^\s"'<>)]+/ig],
];
const SOCIAL_HOST = /(linkedin|twitter|x|instagram|facebook|fb|github|youtube|youtu|tiktok)\.|t\.me/i;

export async function extractSocials(api, { text, website } = {}) {
  let corpus = String(text || '');
  const urls = corpus.match(/https?:\/\/[^\s"'<>)]+/gi) || [];
  const site = website || urls.find((u) => !SOCIAL_HOST.test(u)) || null;
  if (site) {
    try {
      const r = await api.gateway('web', 'text', { url: site, max_bytes: 200000 });
      if (r.ok) corpus += ' ' + r.text;
    } catch { /* site down — fine */ }
  }
  const found = new Map();
  for (const [type, re] of SOCIAL) {
    let m;
    re.lastIndex = 0;
    while ((m = re.exec(corpus))) {
      let u = m[0].replace(/[).,'"]+$/, '');
      if (!/^https?:/i.test(u)) u = 'https://' + u;
      if (!found.has(u)) found.set(u, { type, url: u });
    }
  }
  return { socials: [...found.values()], website: site };
}

// ── photo storage: copy an expiring URL into R2 via the assets gateway ──────

export async function storeLeadPhoto(api, url, key) {
  try {
    const r = await api.gateway('web', 'bytes', { url });
    if (!r.ok) return null;
    const stored = await api.gateway('assets', 'store', { key, bytes: r.bytes, metadata: {} });
    return stored || null;
  } catch { return null; }
}

// ── enrichment passes (each re-reads the lead; conflict-aware writes) ────────

// WhatsApp pass: pushname / photo / about via the shared whatsapp gateway;
// socials from the about text. Photo copied to R2 so it survives URL expiry.
export async function waEnrichOne(api, lead) {
  await updateLead(api, lead.id, { active_tool: 'whatsapp' });
  try {
    const number = lead.normalized_phone || lead.phone;
    const info = await api.gateway('whatsapp', 'contact', { number });
    const soc = info.about ? await extractSocials(api, { text: info.about }) : { socials: [] };
    const existing = parseJson(lead.socials, []);
    const dismissed = new Set(parseJson(lead.dismissed, []));
    const seen = new Set(existing.map((s) => s.url));
    const at = new Date().toISOString();
    const socials = [...existing];
    for (const s of soc.socials) {
      if (!s.url || seen.has(s.url) || dismissed.has(s.url)) continue;
      socials.push({ ...s, src: 'extract_socials', at });
      seen.add(s.url);
    }
    const srcUpd = {};
    const conflicts = [];
    let photo = lead.photo || null;
    if (info.photo) {
      const stored = await storeLeadPhoto(api, info.photo, `gtm/leads/${lead.id}.jpg`);
      if (stored) { photo = stored; srcUpd.photo = 'wa_fetch_photo'; }
    }
    const fields = { status: 'enriched', photo, socials: JSON.stringify(socials), active_tool: null };
    if (info.name) {
      if (!lead.name) { fields.name = info.name; srcUpd.name = 'wa_fetch_name'; }
      else if (!eqCI(info.name, lead.name)) conflicts.push({ field: 'name', value: info.name, tool: 'wa_fetch_name' });
    }
    fields.sources = mergeSources(lead, srcUpd);
    if (conflicts.length) fields.conflicts = mergeConflicts(lead, conflicts);
    await updateLead(api, lead.id, fields);
    return { on_whatsapp: !!info.on_whatsapp, name: fields.name ?? lead.name, photo, about: info.about || null, is_business: !!info.is_business };
  } catch (e) {
    await updateLead(api, lead.id, { active_tool: null });
    return { error: String(e.message || e) };
  }
}

// PDL pass: phone-anchored identity. PAID — hard-skipped when name+company are
// already present (the cheaper sources already did the job).
export async function pdlEnrichOne(api, l) {
  if (l.name && l.company) return { skipped: 'name + company already present, PDL is paid' };
  await updateLead(api, l.id, { active_tool: 'pdl' });
  try {
    const res = await pdlEnrich(api, { phone: l.normalized_phone || l.phone, name: l.name || undefined, region: l.region || undefined, country: l.country || undefined });
    if (res.skipped || res.error || res.matched === false) { await updateLead(api, l.id, { active_tool: null }); return res; }
    const socials = parseJson(l.socials, []);
    const dismissed = new Set(parseJson(l.dismissed, []));
    const seen = new Set(socials.map((s) => s.url));
    const at = new Date().toISOString();
    for (const p of res.profiles || []) if (p.url && !seen.has(p.url) && !dismissed.has(p.url)) { socials.push({ ...p, src: 'pdl_enrich', at }); seen.add(p.url); }
    const srcUpd = {}, conflicts = [];
    const fields = { status: 'enriched', socials: JSON.stringify(socials), active_tool: null };
    if (res.name) { if (!l.name) { fields.name = res.name; srcUpd.name = 'pdl_enrich'; } else if (!eqCI(res.name, l.name)) conflicts.push({ field: 'name', value: res.name, tool: 'pdl_enrich' }); }
    if (res.company) { if (!l.company) { fields.company = res.company; srcUpd.company = 'pdl_enrich'; } else if (!eqCI(res.company, l.company)) conflicts.push({ field: 'company', value: res.company, tool: 'pdl_enrich' }); }
    if (res.job_title && !l.position) { fields.position = res.job_title; srcUpd.position = 'pdl_enrich'; }
    if (res.email && !l.email) { fields.email = res.email; srcUpd.email = 'pdl_enrich'; }
    if (res.region && !l.region) { fields.region = res.region; srcUpd.region = 'pdl_enrich'; }
    if (res.country && !l.country) { fields.country = res.country; srcUpd.country = 'pdl_enrich'; }
    fields.sources = mergeSources(l, srcUpd);
    if (conflicts.length) fields.conflicts = mergeConflicts(l, conflicts);
    await updateLead(api, l.id, fields);
    return { matched: res.matched, likelihood: res.likelihood, name: res.name, company: res.company };
  } catch (e) {
    await updateLead(api, l.id, { active_tool: null });
    return { error: String(e.message || e) };
  }
}

// Twilio pass: line type + carrier always; CNAM name only if still nameless.
export async function twilioEnrichOne(api, l) {
  await updateLead(api, l.id, { active_tool: 'twilio' });
  try {
    const r = await twilioLookup(api, l.normalized_phone || l.phone);
    if (r.skipped || r.error) { await updateLead(api, l.id, { active_tool: null }); return r; }
    const srcUpd = {}, conflicts = [];
    const fields = { line_type: r.line_type || null, carrier: r.carrier || null, active_tool: null };
    if (r.line_type) srcUpd.line_type = 'twilio_lookup';
    if (r.carrier)   srcUpd.carrier = 'twilio_lookup';
    if (r.caller_name) {
      if (!l.name) { fields.name = r.caller_name; srcUpd.name = 'twilio_lookup'; }
      else if (!eqCI(r.caller_name, l.name)) conflicts.push({ field: 'name', value: r.caller_name, tool: 'twilio_lookup' });
    }
    fields.sources = mergeSources(l, srcUpd);
    if (conflicts.length) fields.conflicts = mergeConflicts(l, conflicts);
    await updateLead(api, l.id, fields);
    return { valid: r.valid, line_type: r.line_type, carrier: r.carrier, caller_name: r.caller_name };
  } catch (e) {
    await updateLead(api, l.id, { active_tool: null });
    return { error: String(e.message || e) };
  }
}

// Google (SerpApi) pass. HARD-GATED: requires an already-sourced name — never
// search an invented name into a false identity.
export async function serpEnrichOne(api, l) {
  if (!l.name || !String(l.name).trim()) return { skipped: 'no sourced name yet — get a name from WhatsApp/PDL first' };
  await updateLead(api, l.id, { active_tool: 'google' });
  try {
    const where = [l.region, l.country].filter(Boolean).join(' ');
    const q = `"${l.name}"${where ? ' ' + where : ''} linkedin OR twitter OR instagram`;
    const res = await serpSearch(api, { q, num: 10 });
    if (res.skipped || res.error) { await updateLead(api, l.id, { active_tool: null }); return res; }
    const results = res.results || [];
    const corpus = results.map((r) => `${r.link} ${r.title} ${r.snippet || ''}`).join('\n');
    const soc = await extractSocials(api, { text: corpus });
    const socials = parseJson(l.socials, []);
    const dismissed = new Set(parseJson(l.dismissed, []));
    const seen = new Set(socials.map((s) => s.url));
    const at = new Date().toISOString();
    let added = 0;
    // LinkedIn URLs are handled separately below with identity verification —
    // never let the raw corpus scrape attach someone else's profile.
    for (const s of soc.socials) {
      if (!s.url || seen.has(s.url) || dismissed.has(s.url)) continue;
      if (s.type === 'linkedin') continue;
      socials.push({ ...s, src: 'serp_search', at }); seen.add(s.url); added++;
    }

    // ── LinkedIn: verified-only. Each /in/ RESULT is checked against the
    // lead's name (result title + URL slug). A profile whose name is wildly
    // different is a namesake or a stray link in the search page — attaching
    // it was the old behavior's cardinal sin (and the wrong company/title got
    // derived from it next). Now: 'yes' → attach; 'no'/'unknown' → NEVER
    // auto-attach; the best rejected candidate is recorded as a CONFLICT so
    // the operator sees it and can approve by hand (a manual edit clears the
    // conflict). Cross-script names (Hebrew name vs Latin profile) land in
    // 'unknown' — unverifiable is not verification.
    const liResults = results.filter((r) => /linkedin\.com\/in\//i.test(r.link || ''));
    const verdicts = liResults.map((r) => ({ url: r.link, title: r.title, verdict: linkedinBelongsTo(l.name, { url: r.link, title: r.title }) }));
    const verified = verdicts.filter((v) => v.verdict === 'yes' && !dismissed.has(v.url));
    const rejected = verdicts.filter((v) => v.verdict !== 'yes' && !dismissed.has(v.url));
    for (const v of verified) {
      if (seen.has(v.url)) continue;
      socials.push({ type: 'linkedin', url: v.url, src: 'serp_search', at }); seen.add(v.url); added++;
    }

    const fields = { socials: JSON.stringify(socials), active_tool: null };
    // Promote to the lead's linkedin field only from a verified or trusted
    // origin: serp entries above are pre-verified; wa/pdl entries came from the
    // person's own WhatsApp about or a phone-anchored PDL match. Even then, a
    // hard slug-vs-name mismatch blocks promotion.
    if (!l.linkedin) {
      const cand = socials.find((s) => s.type === 'linkedin' && /linkedin\.com\/in\//i.test(s.url)
        && ['serp_search', 'extract_socials', 'pdl_enrich'].includes(s.src)
        && slugNameCheck(l.name, s.url) !== 'mismatch');
      if (cand) fields.linkedin = cand.url;
      else if (rejected.length) {
        // surface the candidate we REFUSED to auto-attach — visible, reviewable
        fields.conflicts = mergeConflicts(l, [{ field: 'linkedin', value: rejected[0].url, tool: 'serp_search' }]);
        await api.log('linkedin_rejected', { id: l.id, name: l.name, url: rejected[0].url, verdict: rejected[0].verdict });
      }
    }
    await updateLead(api, l.id, fields);
    return { query: q, found: soc.socials.length, added, linkedin_verified: verified.length, linkedin_rejected: rejected.length };
  } catch (e) {
    await updateLead(api, l.id, { active_tool: null });
    return { error: String(e.message || e) };
  }
}

// ── retroactive identity audit ──────────────────────────────────────────────
// Find every lead whose assigned linkedin does NOT match their name (the bad
// assignments made before the verification gate existed). fix:true cleans them:
// clears the linkedin, tombstones the URL (dismissed — can never be re-added),
// records a visible conflict, and ALSO clears company/position when they were
// derived FROM that wrong profile (sources.{field}.tool === company_from_linkedin
// — the poison spreads, so the cleanup must follow it).
export async function auditLinkedinIdentity(api, { fix = false } = {}) {
  const r = await api.db.prepare(
    `SELECT * FROM plugin_gtm_leads WHERE linkedin IS NOT NULL AND name IS NOT NULL`,
  ).all();
  const leads = r.results || [];
  const report = { checked: leads.length, match: 0, unverifiable: 0, mismatch: [], fixed: 0 };
  for (const l of leads) {
    const verdict = slugNameCheck(l.name, l.linkedin);
    if (verdict === 'match') { report.match++; continue; }
    if (verdict === 'unverifiable') { report.unverifiable++; continue; }
    report.mismatch.push({ id: l.id, name: l.name, linkedin: l.linkedin, company: l.company });
    if (!fix) continue;
    const sources = parseJson(l.sources, {});
    const dismissed = [...new Set([...parseJson(l.dismissed, []), l.linkedin])];
    const fields = { linkedin: null, dismissed: JSON.stringify(dismissed) };
    for (const f of ['company', 'position']) {
      if (sources?.[f]?.tool === 'company_from_linkedin') { fields[f] = null; delete sources[f]; }
    }
    delete sources.linkedin;
    fields.sources = JSON.stringify(sources);
    fields.conflicts = mergeConflicts(l, [{ field: 'linkedin', value: l.linkedin, tool: 'identity_audit' }]);
    await updateLead(api, l.id, fields);
    await api.log('linkedin_cleared', { id: l.id, name: l.name, url: l.linkedin });
    report.fixed++;
  }
  return report;
}

// Company (and title) off the person's LinkedIn search result — cheap,
// authoritative, kills confabulated companies. Regex first, LLM fallback.
//
// The guard covers BOTH fields it can fill. It used to bail on `l.company`
// alone, which meant a lead whose company arrived from PDL / WhatsApp / a manual
// edit could never have its TITLE read off LinkedIn — the function returned
// before fetching the profile, so the `job_title` branch below was unreachable
// and the title stayed empty however plainly it was on the page. That also made
// the operator's rerun button a no-op for exactly that case.
export async function companyFromLinkedinOne(api, l) {
  if (!l.linkedin) return { skipped: 'no linkedin' };
  if (l.company && l.position) return { skipped: 'company + title already on file' };
  await updateLead(api, l.id, { active_tool: 'linkedin' });
  try {
    const slug = (String(l.linkedin).match(/\/in\/([^/?#]+)/) || [])[1] || '';
    const q = l.name ? `${l.name} site:linkedin.com/in` : `site:linkedin.com/in/${slug}`;
    const res = await serpSearch(api, { q, num: 8 });
    if (res.skipped || res.error) { await updateLead(api, l.id, { active_tool: null }); return res; }
    const results = res.results || [];
    // Exact-slug hit = the lead's own (already verified) profile. The fallback
    // must ALSO pass identity verification — the old `any /in/ result` fallback
    // happily read the company/title off a total stranger's profile whenever the
    // slug didn't appear, poisoning company AND position in one shot.
    const hit = (slug && results.find((o) => (o.link || '').toLowerCase().includes('/in/' + slug.toLowerCase())))
      || results.find((o) => /linkedin\.com\/in\//i.test(o.link || '') && linkedinBelongsTo(l.name, { url: o.link, title: o.title }) === 'yes');
    if (!hit) { await updateLead(api, l.id, { active_tool: null }); return { company: null, note: 'no name-verified linkedin result found' }; }
    // "Name - Title at Company" parses with a regex; messy headlines fall to the LLM.
    const t = String(hit.title || '').replace(/\s*[|–-]\s*LinkedIn.*$/i, '').replace(/[.…]+\s*$/, '').trim();
    let company = null, job_title = null;
    const dash = t.indexOf(' - ');
    if (dash !== -1) {
      const rest = t.slice(dash + 3);
      const m = rest.match(/^(.*?)\s+(?:at|@)\s+(.+)$/i);
      if (m) { job_title = m[1].trim() || null; company = m[2].replace(/\s*\(.*?\)\s*$/, '').trim() || null; }
      else job_title = rest || null;
    }
    if (!company) {
      try {
        const txt = await gtmLLM(api, {
          system: 'Extract the person\'s CURRENT company and job title from a LinkedIn search result. Headlines are messy: "EIR @Notable, GTM Nerd!" means title "EIR", company "Notable". Return ONLY strict JSON {"company": string|null, "job_title": string|null}.',
          prompt: `Title: ${hit.title}\nSnippet: ${hit.snippet || ''}`,
          model: null, // llm gateway resolves the configured default (was NYO_MODEL_MID)
          maxTokens: 300,
        });
        const o = extractJson(txt);
        company = o.company || company;
        job_title = o.job_title || job_title;
      } catch { /* keep regex result */ }
    }
    const srcUpd = {}, conflicts = [], fields = { active_tool: null };
    // Now that this can run with a company already on file, it must follow the
    // module's provenance rule like every other source does: fill an empty
    // field, but record a disagreement instead of overwriting one.
    if (company) {
      if (!l.company) { fields.company = company; srcUpd.company = 'company_from_linkedin'; }
      else if (!eqCI(company, l.company)) conflicts.push({ field: 'company', value: company, tool: 'company_from_linkedin' });
    }
    if (job_title && !l.position) { fields.position = job_title; srcUpd.position = 'company_from_linkedin'; }
    if (Object.keys(srcUpd).length) fields.sources = mergeSources(l, srcUpd);
    if (conflicts.length) fields.conflicts = mergeConflicts(l, conflicts);
    await updateLead(api, l.id, fields);
    return { company: company || null, position: job_title || null, from: hit.link };
  } catch (e) {
    await updateLead(api, l.id, { active_tool: null });
    return { error: String(e.message || e) };
  }
}

// The full chain for one lead, accuracy order. Each step re-reads the lead so a
// later step sees what an earlier one wrote (SERP needs the name; PDL skips
// itself once name+company exist).
export async function enrichFullOne(api, id) {
  const at = now();
  const wa = await waEnrichOne(api, await getLead(api, id));
  let l = await getLead(api, id);
  // If WhatsApp (or a previous pass) surfaced a linkedin, resolve the company
  // off it before paying for PDL.
  const liBefore = l.linkedin || null;
  const cfl = await companyFromLinkedinOne(api, l);
  const pdl = await pdlEnrichOne(api, await getLead(api, id));
  const twilio = await twilioEnrichOne(api, await getLead(api, id));
  const serp = await serpEnrichOne(api, await getLead(api, id));
  // Deterministic finalize: with a linkedin on file, the company read off it is
  // authoritative (kills "Elon University"-style confabulation). It exists to
  // catch the profile SERP just attached, which the earlier pass never saw.
  //
  // Skipped when the earlier pass already FETCHED this exact profile: that pass
  // reads company and title off the same result, so re-reading an unchanged URL
  // is the identical SerpApi query twice in one chain. (A step-2 that merely
  // self-skipped costs nothing to repeat — it returns before any search.)
  l = await getLead(api, id);
  const alreadyRead = !!liBefore && l.linkedin === liBefore && !cfl?.skipped;
  const confirm = alreadyRead
    ? { skipped: 'same LinkedIn profile already read earlier this run' }
    : await companyFromLinkedinOne(api, l);

  // Mark the chain as RUN unconditionally — even when every source failed or
  // was skipped. status means "attempted", the red/yellow/green state carries
  // quality. Without this, a lead whose sources all skip stays 'new' and
  // enrichBatchStep re-selects it forever (the UI loop never terminates).
  const cur = await updateLead(api, id, { status: 'enriched' });

  // Persist what each step DID, so "skipped on purpose" survives as a distinct
  // fact from "ran and found nothing". Wrapped: the `steps` column arrives by a
  // MANUAL migration, so if a deploy ever lands ahead of it, a missing column
  // must not take the whole enrichment chain down with it.
  // Non-chain verdicts (the manual ICP match) are carried forward, not wiped —
  // this pass replaces only what it actually re-ran.
  const results = { wa, li: cfl, pdl, twilio, serp, confirm };
  const steps = [...ENRICH_STEPS.map((d) => stepVerdict(d, results[d.key], at)), ...foreignSteps(parseJson(cur?.steps, null))];
  try {
    await updateLead(api, id, { steps: JSON.stringify(steps) });
  } catch (e) {
    console.error('gtm: step verdicts not persisted (is the steps column migrated?)', e?.message || e);
  }

  const done = await getLead(api, id);
  await api.log('lead_enriched', { id, state: leadState(done), steps: steps.map((s) => `${s.key}:${s.status}`) });
  return { id, state: leadState(done), steps, wa, company_from_linkedin: cfl, pdl, twilio, serp, confirm };
}

// Resume the TAIL of the chain after the operator has typed something in by
// hand. Two steps gate themselves on fields a human most often supplies:
//   * SerpApi — hard-gated on already having a sourced NAME
//   * Confirm — the finalize LinkedIn pass, needs a linkedin and no company yet
// Typing a name or pasting a profile URL unblocks exactly those two, so this
// re-runs only them.
//
// It deliberately does NOT re-run WhatsApp / PDL / Twilio: Twilio bills per
// lookup and PDL is paid, and nothing the operator typed changes what either
// would return for the same phone number. Re-running the full chain to pick up
// one manual edit is how a "just refresh it" button quietly becomes expensive.
//
// Verdicts are MERGED over whatever is already recorded, so the steps this pass
// didn't touch keep their previous result instead of being reset to unknown.
export async function enrichResumeOne(api, id) {
  const at = now();
  const serp = await serpEnrichOne(api, await getLead(api, id));
  const confirm = await companyFromLinkedinOne(api, await getLead(api, id));

  const results = { serp, confirm };
  const current = await getLead(api, id);
  const prior = parseJson(current?.steps, null);
  const byKey = new Map((Array.isArray(prior) ? prior : []).map((s) => [s.key, s]));
  for (const d of ENRICH_STEPS) {
    if (!(d.key in results)) continue;
    byKey.set(d.key, stepVerdict(d, results[d.key], at));
  }
  // Only the keys we actually know about — a step with no record at all is left
  // OUT rather than written as 'idle', so a resume on a lead enriched before
  // the steps column doesn't claim its earlier steps never ran. The page infers
  // those. Non-chain verdicts (the manual ICP match) ride along untouched.
  const steps = [...ENRICH_STEPS.map((d) => byKey.get(d.key)).filter(Boolean), ...foreignSteps(prior)];
  try {
    await updateLead(api, id, { steps: JSON.stringify(steps) });
  } catch (e) {
    console.error('gtm: resume verdicts not persisted (is the steps column migrated?)', e?.message || e);
  }

  const done = await getLead(api, id);
  await api.log('lead_enriched', { id, mode: 'resume', state: leadState(done), steps: steps.map((s) => `${s.key}:${s.status}`) });
  return { id, mode: 'resume', state: leadState(done), steps, serp, confirm };
}

// Batch stepper: enrich the next `limit` un-enriched leads of a batch. The UI /
// Nyo calls this in a loop while remaining > 0 — keeps each Worker invocation
// well inside its budget instead of one long background chain.
export async function enrichBatchStep(api, { batch_id, limit = 2 } = {}) {
  const r = await api.db.prepare("SELECT id FROM plugin_gtm_leads WHERE batch_id = ? AND status = 'new' ORDER BY created_at LIMIT ?")
    .bind(batch_id, Math.min(5, Math.max(1, limit))).all();
  const ids = (r.results || []).map((x) => x.id);
  const results = [];
  for (const id of ids) results.push(await enrichFullOne(api, id));
  const rem = await api.db.prepare("SELECT COUNT(*) AS n FROM plugin_gtm_leads WHERE batch_id = ? AND status = 'new'").bind(batch_id).first();
  return { enriched: results.length, remaining: rem?.n ?? 0, results };
}

// Manual field edit: '' clears a field; removed social URLs are tombstoned into
// dismissed; a manual edit resolves (clears) matching conflicts.
export async function manualEditLead(api, id, body = {}) {
  const l = await getLead(api, id);
  if (!l) throw new Error('no such lead');
  const fields = {};
  const srcUpd = {};   // provenance to stamp
  const srcDrop = [];  // provenance to remove, for values we cleared
  for (const k of ['name', 'linkedin', 'email', 'company', 'position']) {
    if (body[k] !== undefined) {
      fields[k] = String(body[k] || '').trim() || null;
      if (fields[k]) srcUpd[k] = 'manual';
    }
  }
  if (body.socials !== undefined) {
    const next = Array.isArray(body.socials) ? body.socials : [];
    const prev = parseJson(l.socials, []);
    const nextUrls = new Set(next.map((s) => s.url));
    const dismissed = parseJson(l.dismissed, []);
    for (const s of prev) if (s.url && !nextUrls.has(s.url)) dismissed.push(s.url);
    fields.socials = JSON.stringify(next);
    fields.dismissed = JSON.stringify([...new Set(dismissed)]);
  }
  // Correcting the COMPANY's LinkedIn is a targeted key, never a whole-socials
  // rewrite: the browser holds a stale copy of that array, and replacing the
  // column with it would tombstone whatever an enrichment pass added in between.
  // The read-modify-write therefore happens here, against the current row.
  if (body.company_linkedin !== undefined) {
    const url = String(body.company_linkedin || '').trim();
    // Seeded from whatever the socials branch already staged, not straight from
    // the row: a request carrying BOTH keys must not have one silently dropped.
    const prev = fields.socials !== undefined ? parseJson(fields.socials, []) : parseJson(l.socials, []);
    const kept = prev.filter((s) => !isCompanyLinkedin(s.url));
    fields.socials = JSON.stringify(url ? [...kept, { type: 'linkedin_company', url, src: 'manual' }] : kept);
    // Blacklist only the company links we actually replaced, so enrichment can
    // never re-attach the wrong company. Other socials keep their state.
    const dismissed = fields.dismissed !== undefined ? parseJson(fields.dismissed, []) : parseJson(l.dismissed, []);
    for (const s of prev) if (isCompanyLinkedin(s.url) && s.url !== url) dismissed.push(s.url);
    fields.dismissed = JSON.stringify([...new Set(dismissed)]);
    // EVERYTHING the old link produced is now about the wrong company: the
    // resolve snapshot, the company id the jobs API is keyed on, the open roles
    // fetched with that id, and the recorded Company step describing them.
    // Leaving any of it means a surface confidently reporting another company's
    // facts — and resolveLiCompany skipping the re-resolve for a month, because
    // company_checked_at is still fresh.
    fields.company_context = null;
    fields.company_li_id = null;
    fields.company_checked_at = null;
    fields.open_positions = null;
    fields.positions_checked_at = null;
    // The headcount belonged to the wrong company too, and the resolve COALESCES
    // rather than clobbers, so leaving it would carry a wrong number forward
    // forever. A figure the operator typed by hand is theirs, and survives.
    const srcs = parseJson(l.sources, {});
    if (srcs?.company_staff_count?.tool !== 'manual') fields.company_staff_count = null;
    // Absent on a lead predating the steps column — parseJson yields null, so
    // the column is simply left out rather than written blind.
    const steps = parseJson(l.steps, null);
    if (Array.isArray(steps)) fields.steps = JSON.stringify(steps.filter((s) => s && s.key !== 'company'));
  }
  // Headcount is fetched, but correctable — LinkedIn matches the wrong company
  // often enough, and the ICP leans on this number harder than on any other
  // single fact. Stored as an integer so the ICP prompt and the Size column read
  // it the same way the resolve writes it; null clears it back to "not checked".
  if (body.company_staff_count !== undefined) {
    const raw = body.company_staff_count;
    const blank = raw === null || (typeof raw === 'string' && raw.trim() === '');
    if (blank) {
      fields.company_staff_count = null;
      // Drop the provenance WITH the value it described, or the stamp outlives
      // it and mislabels whatever lands next.
      srcDrop.push('company_staff_count');
    } else {
      // Rejected, not coerced. Number([]) and Number(false) are both 0, which
      // would store a real "0 employees" — and the ICP prompt is told a number
      // is a fact while "not checked" is not. So only a number or a numeric
      // string is even considered; String(x) on anything else is not evidence.
      if (typeof raw !== 'number' && typeof raw !== 'string') throw new Error('company_staff_count must be a number');
      const n = typeof raw === 'number' ? raw : Number(raw.trim());
      if (!Number.isFinite(n) || n < 0) throw new Error('company_staff_count must be a non-negative number');
      fields.company_staff_count = Math.round(n);
      srcUpd.company_staff_count = 'manual';
    }
  }
  // Manual edit resolves conflicts on the fields it touched.
  const conflicts = parseJson(l.conflicts, []).filter((c) => !(c.field in fields));
  fields.conflicts = JSON.stringify(conflicts);
  if (Object.keys(srcUpd).length) fields.sources = mergeSources(l, srcUpd);
  // Applied AFTER the merge, which rebuilds from the stored row and would
  // otherwise resurrect a stamp we just dropped.
  if (srcDrop.length) {
    const s = parseJson(fields.sources !== undefined ? fields.sources : l.sources, {});
    for (const k of srcDrop) delete s[k];
    fields.sources = JSON.stringify(s);
  }
  await updateLead(api, id, fields);
  await api.log('lead_updated', { id, changed: Object.keys(fields).filter((k) => !['conflicts', 'sources', 'dismissed'].includes(k)) });
  return getLead(api, id);
}

// ─────────────────────────────────────────────────────────────────────────────
// GRANULAR ENRICHMENT (v2): the chain above becomes a WORKFLOW.
//
// enrichFullOne is one function doing eight things — fetch five sources, merge
// them in accuracy order, verify identity, score steps, persist, log. The v2
// split is: each source is a PURE LOOKUP that returns what it found and writes
// nothing; reconcileIdentity does every merge decision; saveLeadPatch is the
// only writer. The order that made the old chain correct now lives in the
// workflow's step list, where it is visible and re-runnable.
//
// The lookups deliberately re-derive nothing from the DB: they take what they
// need as arguments so the workflow context is the only state, and a re-run of
// one step can't silently depend on a write another step made.
// ─────────────────────────────────────────────────────────────────────────────

// A source result is DATA only when it neither self-skipped nor failed. Every
// branch of reconcileIdentity checks this before believing a field.
const usableSource = (r) => !!r && typeof r === 'object' && !r.skipped && !r.error;

// WhatsApp identity. The photo is copied into R2 HERE, not at save time: the
// gateway's URL expires, and a workflow that pauses (or fails) between this step
// and the save must never persist a link that has already died.
export async function lookupWaIdentity(api, { phone, lead_id = null } = {}) {
  if (!phone) return { error: 'no phone number' };
  const info = await api.gateway('whatsapp', 'contact', { number: phone });
  let photo = info.photo || null;
  if (photo && lead_id) photo = await storeLeadPhoto(api, photo, `gtm/leads/${lead_id}.jpg`);
  const about = info.about || null;
  const soc = about ? await extractSocials(api, { text: about }) : { socials: [] };
  return {
    on_whatsapp: !!info.on_whatsapp,
    wa_name: info.name || null,
    wa_photo_url: photo || null,
    wa_about: about,
    is_business: !!info.is_business,
    wa_socials: soc.socials,
  };
}

// Company + title read off the person's own (name-verified) LinkedIn result.
// Self-skips exactly where the old pass did: no profile to read, or both fields
// already on file — a SerpApi query is billed either way.
export async function lookupCompanyFromLinkedin(api, { name = null, linkedin = null, company = null, position = null } = {}) {
  if (!linkedin) return { skipped: 'no linkedin' };
  if (company && position) return { skipped: 'company + title already on file' };
  const slug = (String(linkedin).match(/\/in\/([^/?#]+)/) || [])[1] || '';
  const q = name ? `${name} site:linkedin.com/in` : `site:linkedin.com/in/${slug}`;
  const res = await serpSearch(api, { q, num: 8 });
  if (res.skipped || res.error) return res;
  const results = res.results || [];
  // Exact-slug hit = the lead's own already-verified profile. The fallback must
  // ALSO pass identity verification, or company AND title get read off a total
  // stranger's page.
  const hit = (slug && results.find((o) => (o.link || '').toLowerCase().includes('/in/' + slug.toLowerCase())))
    || results.find((o) => /linkedin\.com\/in\//i.test(o.link || '') && linkedinBelongsTo(name, { url: o.link, title: o.title }) === 'yes');
  const rejected = results
    .filter((o) => /linkedin\.com\/in\//i.test(o.link || '') && o.link !== hit?.link)
    .map((o) => ({ url: o.link, verdict: linkedinBelongsTo(name, { url: o.link, title: o.title }) }));
  if (!hit) return { li_company: null, li_position: null, li_profile_url: null, li_rejected: rejected, note: 'no name-verified linkedin result found' };
  // "Name - Title at Company" parses with a regex; messy headlines fall to the LLM.
  const t = String(hit.title || '').replace(/\s*[|–-]\s*LinkedIn.*$/i, '').replace(/[.…]+\s*$/, '').trim();
  let liCompany = null, jobTitle = null;
  const dash = t.indexOf(' - ');
  if (dash !== -1) {
    const rest = t.slice(dash + 3);
    const m = rest.match(/^(.*?)\s+(?:at|@)\s+(.+)$/i);
    if (m) { jobTitle = m[1].trim() || null; liCompany = m[2].replace(/\s*\(.*?\)\s*$/, '').trim() || null; }
    else jobTitle = rest || null;
  }
  if (!liCompany) {
    try {
      const txt = await gtmLLM(api, {
        system: 'Extract the person\'s CURRENT company and job title from a LinkedIn search result. Headlines are messy: "EIR @Notable, GTM Nerd!" means title "EIR", company "Notable". Return ONLY strict JSON {"company": string|null, "job_title": string|null}.',
        prompt: `Title: ${hit.title}\nSnippet: ${hit.snippet || ''}`,
        model: null, // llm gateway resolves the configured default (was NYO_MODEL_MID)
        maxTokens: 300,
      });
      const o = extractJson(txt);
      liCompany = o.company || liCompany;
      jobTitle = o.job_title || jobTitle;
    } catch { /* keep the regex result */ }
  }
  return { li_company: liCompany || null, li_position: jobTitle || null, li_profile_url: hit.link, li_rejected: rejected };
}

// PDL is PAID: it self-skips the moment the cheaper sources have already
// answered the question it would answer.
export async function enrichPersonPdl(api, { phone, name = null, company = null, region = null, country = null } = {}) {
  if (name && company) return { skipped: 'name + company already present, PDL is paid' };
  const res = await pdlEnrich(api, { phone, name: name || undefined, region: region || undefined, country: country || undefined });
  if (res.skipped || res.error || res.matched === false) return res;
  return {
    matched: res.matched,
    likelihood: res.likelihood,
    pdl_name: res.name || null,
    pdl_company: res.company || null,
    pdl_title: res.job_title || null,
    pdl_email: res.email || null,
    pdl_region: res.region || null,
    pdl_country: res.country || null,
    pdl_profiles: res.profiles || [],
  };
}

export async function lookupLineTwilio(api, { phone } = {}) {
  if (!phone) return { error: 'no phone number' };
  const r = await twilioLookup(api, phone);
  if (r.skipped || r.error) return r;
  return { valid: r.valid, line_type: r.line_type, carrier: r.carrier, caller_name: r.caller_name };
}

// HARD-GATED on an already-sourced name: searching an invented name is how a
// lead acquires a stranger's identity. LinkedIn hits come back as unattached
// CANDIDATES — verification is reconcileIdentity's job, not the searcher's.
export async function searchSocialsSerp(api, { name, region = null, country = null } = {}) {
  if (!name || !String(name).trim()) return { skipped: 'no sourced name yet — get a name from WhatsApp/PDL first' };
  const where = [region, country].filter(Boolean).join(' ');
  const q = `"${name}"${where ? ' ' + where : ''} linkedin OR twitter OR instagram`;
  const res = await serpSearch(api, { q, num: 10 });
  if (res.skipped || res.error) return res;
  const results = res.results || [];
  const corpus = results.map((r) => `${r.link} ${r.title} ${r.snippet || ''}`).join('\n');
  const soc = await extractSocials(api, { text: corpus });
  const linkedin_candidates = results
    .filter((r) => /linkedin\.com\/in\//i.test(r.link || ''))
    .map((r) => ({ url: r.link, title: r.title }));
  return { socials: soc.socials, linkedin_candidates, query: q };
}

// Every merge decision the old chain spread across five write-passes, in one
// pure function: fill-don't-overwrite precedence, LinkedIn identity
// verification with namesake rejection, tombstone respect, the conflict list,
// the CEO-mismatch org warn, and the per-step verdicts.
//
// Pure on purpose — no api, no I/O. It reads the raw source results off the
// workflow context and returns a PATCH; saveLeadPatch is the only thing that
// touches D1. Absent sources contribute nothing, so the same function serves
// enrich-lead (five sources), company-context (company facts only) and
// clean-identity (a deliberate teardown).
export function reconcileIdentity(ctx = {}) {
  const lead = ctx.lead || {};
  const at = now();
  const stamp = new Date().toISOString();
  const patch = {};
  const srcUpd = {};
  const srcDrop = [];
  const conflicts = [];
  const results = {};                                   // step key → raw result, for stepVerdict
  const dismissed = new Set(parseJson(lead.dismissed, []));
  const socials = parseJson(lead.socials, []);
  const seen = new Set(socials.map((s) => s.url));
  let addedSocials = 0;
  let socialsTouched = false;

  const addSocial = (s, src) => {
    if (!s?.url || seen.has(s.url) || dismissed.has(s.url)) return;
    socials.push({ ...s, src, at: stamp });
    seen.add(s.url);
    addedSocials++;
    socialsTouched = true;
  };
  // Later sources see what earlier ones staged — the old chain got this by
  // re-reading the row between passes; here the patch IS the running truth.
  const current = (field) => (patch[field] !== undefined ? patch[field] : lead[field]);
  const fillOrConflict = (field, value, tool) => {
    if (!value) return;
    const held = current(field);
    if (!held) { patch[field] = value; srcUpd[field] = tool; }
    else if (!eqCI(value, held)) conflicts.push({ field, value, tool });
  };
  const fillIfEmpty = (field, value, tool) => {
    if (!value || current(field)) return;
    patch[field] = value;
    srcUpd[field] = tool;
  };

  // ── clean-identity: a REPORTED mismatch, torn down deliberately ────────────
  // Not an enrichment path: the operator (via audit_identities) says this
  // LinkedIn is the wrong person. Clear it, tombstone the URL so no future
  // search can re-attach it, leave a visible conflict, and follow the poison —
  // company/position derived FROM that profile go too.
  if (ctx.clean_identity && lead.linkedin) {
    const priorSources = parseJson(lead.sources, {});
    patch.linkedin = null;
    dismissed.add(lead.linkedin);
    srcDrop.push('linkedin');
    for (const f of ['company', 'position']) {
      if (priorSources?.[f]?.tool === 'company_from_linkedin') { patch[f] = null; srcDrop.push(f); }
    }
    conflicts.push({ field: 'linkedin', value: lead.linkedin, tool: 'identity_audit' });
    return {
      lead_patch: patch,
      sources: applySourceDrops(mergedSources(lead, srcUpd), srcDrop),
      conflicts: mergedConflicts(lead, conflicts),
      dismissed: [...dismissed],
      steps: parseJson(lead.steps, null) || [],
      cleaned_linkedin: lead.linkedin,
    };
  }

  // ── WhatsApp ───────────────────────────────────────────────────────────────
  if (ctx.wa) {
    results.wa = { name: ctx.wa.wa_name, photo: ctx.wa.wa_photo_url, about: ctx.wa.wa_about, on_whatsapp: ctx.wa.on_whatsapp, error: ctx.wa.error, skipped: ctx.wa.skipped };
    if (usableSource(ctx.wa)) {
      for (const s of ctx.wa.wa_socials || []) addSocial(s, 'extract_socials');
      if (ctx.wa.wa_photo_url) { patch.photo = ctx.wa.wa_photo_url; srcUpd.photo = 'wa_fetch_photo'; }
      fillOrConflict('name', ctx.wa.wa_name, 'wa_fetch_name');
    }
  }

  // ── company off the person's LinkedIn ──────────────────────────────────────
  if (ctx.li) {
    results.li = { company: ctx.li.li_company, note: ctx.li.note, error: ctx.li.error, skipped: ctx.li.skipped };
    if (usableSource(ctx.li)) {
      fillOrConflict('company', ctx.li.li_company, 'company_from_linkedin');
      fillIfEmpty('position', ctx.li.li_position, 'company_from_linkedin');
    }
  }

  // ── PDL ────────────────────────────────────────────────────────────────────
  if (ctx.pdl) {
    results.pdl = { matched: ctx.pdl.matched, name: ctx.pdl.pdl_name, company: ctx.pdl.pdl_company, error: ctx.pdl.error, skipped: ctx.pdl.skipped };
    if (usableSource(ctx.pdl) && ctx.pdl.matched !== false) {
      for (const p of ctx.pdl.pdl_profiles || []) addSocial(p, 'pdl_enrich');
      fillOrConflict('name', ctx.pdl.pdl_name, 'pdl_enrich');
      fillOrConflict('company', ctx.pdl.pdl_company, 'pdl_enrich');
      fillIfEmpty('position', ctx.pdl.pdl_title, 'pdl_enrich');
      fillIfEmpty('email', ctx.pdl.pdl_email, 'pdl_enrich');
      fillIfEmpty('region', ctx.pdl.pdl_region, 'pdl_enrich');
      fillIfEmpty('country', ctx.pdl.pdl_country, 'pdl_enrich');
    }
  }

  // ── Twilio ─────────────────────────────────────────────────────────────────
  if (ctx.twilio) {
    results.twilio = { line_type: ctx.twilio.line_type, carrier: ctx.twilio.carrier, caller_name: ctx.twilio.caller_name, error: ctx.twilio.error, skipped: ctx.twilio.skipped };
    if (usableSource(ctx.twilio)) {
      // Twilio IS the authority on these two, so it writes them outright.
      patch.line_type = ctx.twilio.line_type || null;
      patch.carrier = ctx.twilio.carrier || null;
      if (ctx.twilio.line_type) srcUpd.line_type = 'twilio_lookup';
      if (ctx.twilio.carrier) srcUpd.carrier = 'twilio_lookup';
      fillOrConflict('name', ctx.twilio.caller_name, 'twilio_lookup');
    }
  }

  // ── Google (SerpApi) — verified LinkedIn only ──────────────────────────────
  let rejectedLinkedin = null;
  if (ctx.serp) {
    const before = addedSocials;
    let verified = [], rejected = [];
    if (usableSource(ctx.serp)) {
      // The raw corpus scrape must never attach a LinkedIn profile: those go
      // through identity verification below, one candidate at a time.
      for (const s of ctx.serp.socials || []) if (s.type !== 'linkedin') addSocial(s, 'serp_search');
      const name = current('name');
      const verdicts = (ctx.serp.linkedin_candidates || [])
        .map((c) => ({ url: c.url, title: c.title, verdict: linkedinBelongsTo(name, { url: c.url, title: c.title }) }));
      verified = verdicts.filter((v) => v.verdict === 'yes' && !dismissed.has(v.url));
      rejected = verdicts.filter((v) => v.verdict !== 'yes' && !dismissed.has(v.url));
      for (const v of verified) addSocial({ type: 'linkedin', url: v.url }, 'serp_search');
      // Promote to the lead's linkedin field only from a verified or trusted
      // origin, and even then a hard slug-vs-name mismatch blocks it.
      if (!current('linkedin')) {
        const cand = socials.find((s) => s.type === 'linkedin' && /linkedin\.com\/in\//i.test(s.url)
          && ['serp_search', 'extract_socials', 'pdl_enrich'].includes(s.src)
          && slugNameCheck(name, s.url) !== 'mismatch');
        if (cand) patch.linkedin = cand.url;
        else if (rejected.length) {
          // Surface the candidate we REFUSED to auto-attach — visible, reviewable.
          conflicts.push({ field: 'linkedin', value: rejected[0].url, tool: 'serp_search' });
          rejectedLinkedin = rejected[0];
        }
      }
    }
    results.serp = {
      added: addedSocials - before,
      linkedin_verified: verified.length,
      linkedin_rejected: rejected.length,
      query: ctx.serp.query,
      error: ctx.serp.error,
      skipped: ctx.serp.skipped,
    };
  }

  if (socialsTouched) patch.socials = JSON.stringify(socials);

  // ── org chart: CEO-mismatch heuristic ──────────────────────────────────────
  // Only when the org step actually RAN this pass — otherwise the context still
  // carries the lead's stored people and we would re-judge stale data. A leg
  // that ran and failed still records its verdict ('none' + why), which is what
  // keeps "we looked and found nothing" distinct from "we never looked".
  let org_status, org_note;
  if (ctx.org_fetched || ctx.org_error) {
    if (ctx.org_error) { org_status = 'none'; org_note = String(ctx.org_error); }
    else {
      const people = Array.isArray(ctx.org_people) ? ctx.org_people : [];
      const topTitle = /\b(ceo|founder|co-?founder|president|owner)\b/i.test(String(current('position') || ''));
      const roots = people.filter((p) => !p.parentId);
      const leadIsRoot = roots.some((p) => namesMatch(p.name, current('name')));
      org_status = 'saved';
      org_note = null;
      if (topTitle && roots.length && !leadIsRoot) {
        org_status = 'warn';
        org_note = `${current('name')} reads as a top exec but theorg's chart for "${ctx.org_company || current('company')}" is headed by ${roots[0]?.name}. Possible namesake company — confirm the theorg slug.`;
      }
    }
    patch.org_status = org_status;
    patch.org_note = org_note ?? null;
    if (ctx.theorg_slug) patch.theorg_slug = ctx.theorg_slug;
  }

  // ── company facts (company-context workflow) ───────────────────────────────
  let companyVerdict = null;
  if (ctx.company_profile || ctx.positions) {
    const cp = ctx.company_profile || {};
    if (cp.company_id) patch.company_li_id = cp.company_id;
    // COALESCE, never clobber: LinkedIn can answer 200 with no headcount, and
    // overwriting a known number with null makes a checked row read "unknown".
    if (cp.staff_count !== undefined && cp.staff_count !== null) patch.company_staff_count = cp.staff_count;
    if (cp.staff_count_fresh) srcUpd.company_staff_count = 'linkedin_company';
    if (cp.company_context) patch.company_context = JSON.stringify(cp.company_context);
    if (cp.checked_at) patch.company_checked_at = cp.checked_at;
    if (Array.isArray(ctx.positions)) {
      patch.open_positions = JSON.stringify(ctx.positions);
      patch.positions_checked_at = at;
    }
    const orgCount = ctx.org_fetched && Array.isArray(ctx.org_people) ? ctx.org_people.length : 0;
    const staff = patch.company_staff_count ?? lead.company_staff_count ?? null;
    const roles = Array.isArray(ctx.positions) ? ctx.positions.length : 0;
    const found = orgCount > 0 || staff !== null || roles > 0;
    const summary = [
      staff !== null ? `${staff} employees` : null,
      orgCount ? `${orgCount} org people` : null,
      roles ? `${roles} open roles` : null,
    ].filter(Boolean).join(' · ');
    const errors = [...new Set([ctx.org_error, cp.error, ctx.positions_error].filter(Boolean))];
    companyVerdict = { key: 'company', label: 'Company', status: found ? 'found' : 'empty', reason: found ? summary : (errors[0] || 'nothing found'), at };
  }

  // ── step verdicts: merged per key over whatever is already recorded ────────
  // A step this run did not touch keeps its previous verdict rather than being
  // reset to unknown, and non-chain verdicts (ICP, Company) ride along.
  const prior = parseJson(lead.steps, null);
  const byKey = new Map((Array.isArray(prior) ? prior : []).map((s) => [s.key, s]));
  for (const d of ENRICH_STEPS) if (d.key in results) byKey.set(d.key, stepVerdict(d, results[d.key], at));
  if (companyVerdict) byKey.set('company', companyVerdict);
  const steps = [
    ...ENRICH_STEPS.map((d) => byKey.get(d.key)).filter(Boolean),
    ...[...byKey.values()].filter((s) => s && !ENRICH_KEYS.has(s.key)),
  ];

  // status means ATTEMPTED, not successful — the red/yellow/green state carries
  // quality. Without this a lead whose every source skipped stays 'new' and the
  // batch drain re-selects it forever.
  const ranIdentityChain = ENRICH_STEPS.some((d) => d.key in results);
  if (ranIdentityChain) patch.status = 'enriched';

  return {
    lead_patch: patch,
    sources: applySourceDrops(mergedSources(lead, srcUpd), srcDrop),
    conflicts: conflicts.length ? mergedConflicts(lead, conflicts) : parseJson(lead.conflicts, []),
    dismissed: [...dismissed],
    steps,
    org_status: org_status ?? lead.org_status ?? null,
    org_note: org_note ?? null,
    rejected_linkedin: rejectedLinkedin,
  };
}

// A cleared value's provenance stamp must die with it, or it outlives the fact
// it described and mislabels whatever lands next.
function applySourceDrops(sources, drop) {
  if (!drop?.length) return sources;
  const s = { ...sources };
  for (const k of drop) delete s[k];
  return s;
}

const asColumnJson = (v) => (v == null ? null : (typeof v === 'string' ? v : JSON.stringify(v)));

// The ONLY writer for a reconciled lead. Coalesce-never-clobber lives upstream:
// reconcileIdentity emits a key only when it means to write it, so an absent key
// leaves the column alone and an explicit null is a deliberate clear.
export async function saveLeadPatch(api, {
  id, lead_patch = {}, sources = null, conflicts = null, dismissed = null, steps = null,
  icp_fit = null, icp_reasons = null, icp_gaps = null, rejected_linkedin = null, actor = 'operator',
} = {}) {
  if (!id) throw new Error('save_lead: id required');
  const fields = { ...lead_patch };
  // Whatever ran, nothing is in flight once we have persisted — a stale
  // active_tool leaves the surface spinning on a run that ended.
  fields.active_tool = null;
  if (sources) fields.sources = asColumnJson(sources);
  if (conflicts) fields.conflicts = asColumnJson(conflicts);
  if (dismissed) fields.dismissed = asColumnJson(dismissed);
  if (icp_fit) {
    fields.icp_fit = icp_fit;
    fields.icp_reasons = JSON.stringify({ reasons: icp_reasons || [], gaps: icp_gaps || [] });
  }
  delete fields.steps; // written separately below — see the migration note
  await updateLead(api, id, fields);

  // The `steps` column arrives by a MANUAL migration. If a deploy ever lands
  // ahead of it, a missing column must not take the whole save with it.
  let nextSteps = Array.isArray(steps) ? [...steps] : null;
  if (icp_fit) {
    const base = nextSteps ?? parseJson((await getLead(api, id))?.steps, null) ?? [];
    nextSteps = [...base.filter((s) => s && s.key !== 'icp'), { key: 'icp', label: 'ICP match', status: 'found', reason: icp_fit, at: now() }];
  }
  if (nextSteps) {
    try {
      await updateLead(api, id, { steps: JSON.stringify(nextSteps) });
    } catch (e) {
      console.error('gtm: step verdicts not persisted (is the steps column migrated?)', e?.message || e);
    }
  }

  const lead = await getLead(api, id);
  if (rejected_linkedin) {
    await api.log('linkedin_rejected', { id, name: lead?.name, url: rejected_linkedin.url, verdict: rejected_linkedin.verdict, actor });
  }
  if (lead_patch.linkedin === null) {
    await api.log('linkedin_cleared', { id, name: lead?.name, actor });
  }
  await api.log('lead_enriched', { id, state: leadState(lead), steps: (nextSteps || []).map((s) => `${s.key}:${s.status}`), icp_fit: icp_fit || undefined, actor });
  return { lead: { ...lead, state: leadState(lead), confidence: evaluateConfidence(lead) } };
}

// ═════════════════════════════════════════════════════════════════════════════
// GTM · Context Enrich (ported from lib/gtm-context.js) — org chart (theorg
// gateway), ICP fit (LLM vs the brand-baseline `brand-icp` doc — single
// source), open roles (linkedin gateway: one throttled company resolve, cached
// on the lead, then the guest-jobs API), and warm-path detection (fuzzy-match
// the operator's connections from `plugin-gtm-you` against org people).
// ═════════════════════════════════════════════════════════════════════════════

// ── knowledge doc helpers (the control surfaces live in knowledge docs) ─────

export async function gtmDoc(api, slug, fallback = '') {
  try {
    const d = await api.knowledge(slug);
    return d?.body || fallback;
  } catch { return fallback; }
}

// ── gtm policy (editable, seeded on first read) ─────────────────────────────
// How stale a cached company fact may get before the bulk action re-fetches it.
// Operator-facing: the Qualification tab's button copy promises this window, so
// it must be tunable by editing a note rather than by a deploy.
const GTM_POLICY_DEFAULTS = Object.freeze({
  company_context_max_age_days: 30,   // a good headcount is re-checked this rarely
  company_retry_after_hours: 2,       // a FAILED resolve retries this soon — a dead
                                      // LinkedIn session is usually fixed in minutes,
                                      // so failures must not be cached for 30 days
});
function polNum(v, fallback) {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}
async function loadGtmPolicy(api) {
  try {
    const row = await api.knowledge('plugin-gtm-policy');
    if (!row?.body) {
      await api.saveKnowledge('plugin-gtm-policy', {
        title: 'GTM policy — company-context cache windows',
        body: JSON.stringify(GTM_POLICY_DEFAULTS, null, 2),
      }).catch(() => {});
      return { ...GTM_POLICY_DEFAULTS };
    }
    const m = String(row.body).match(/\{[\s\S]*\}/);
    const src = m ? JSON.parse(m[0]) : {};
    const out = {};
    for (const [k, dflt] of Object.entries(GTM_POLICY_DEFAULTS)) out[k] = polNum(src[k], dflt);
    return out;
  } catch {
    return { ...GTM_POLICY_DEFAULTS };
  }
}

export async function readYou(api) {
  try { return JSON.parse(await gtmDoc(api, 'plugin-gtm-you', '{}')); } catch { return {}; }
}

export async function writeYou(api, patch = {}) {
  const cur = await readYou(api);
  const ALLOW = ['name', 'role', 'business', 'phone', 'email', 'linkedin', 'location', 'about', 'groups', 'connections'];
  const next = { ...cur };
  for (const k of ALLOW) if (patch[k] !== undefined) next[k] = patch[k];
  await api.saveKnowledge('plugin-gtm-you', { title: 'GTM · You — operator profile', body: JSON.stringify(next, null, 0) });
  return next;
}

// ── theorg org chart (via the theorg gateway — GraphQL lives in the host) ────

export async function fetchTheorg(api, { company, slug } = {}) {
  return api.gateway('theorg', 'org_chart', { company, slug });
}

// Health probe — delegated to the theorg gateway (empty POST answers 400,
// which still proves theorg is up, and no real query means health probes
// never hit quota).
export async function probeTheorg(api) {
  return api.gateway('theorg', 'probe', {});
}

export async function listOrgPeople(api, leadId) {
  const r = await api.db.prepare('SELECT * FROM plugin_gtm_org_people WHERE lead_id = ? ORDER BY created_at').bind(leadId).all();
  return r.results || [];
}

async function replaceOrgPeople(api, leadId, company, people) {
  await api.db.prepare('DELETE FROM plugin_gtm_org_people WHERE lead_id = ?').bind(leadId).run();
  for (const p of people) {
    await api.db.prepare(`
      INSERT INTO plugin_gtm_org_people (id, lead_id, company, node_id, parent_node_id, name, role, photo_url, report_count, source, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'theorg', ?)
    `).bind(gid('gp'), leadId, company || null, p.nodeId || null, p.parentId || null, p.name || null, p.role || null, p.photo || null, p.reportCount ?? null, now()).run();
  }
}

// Fetch (or serve the persisted) org chart for a lead. theorg is hit only on
// first check or explicit refresh/slug override — the outcome is cached on the
// lead as org_status (saved | warn | none) + org_note. A CEO-mismatch heuristic
// (the lead claims a top title but theorg's root is someone else) sets 'warn',
// which BLOCKS outreach generation until the operator confirms the slug.
export async function orgChartForLead(api, { id, refresh = false, slug = null } = {}) {
  const lead = await getLead(api, id);
  if (!lead) return { error: 'no lead' };
  if (!refresh && !slug && lead.org_status) {
    const people = await listOrgPeople(api, id);
    if (people.length || lead.org_status === 'none') {
      return { company: lead.company, people, status: lead.org_status, note: lead.org_note, fromDb: true };
    }
  }
  if (!lead.company && !slug && !lead.theorg_slug) {
    await updateLead(api, id, { org_status: 'none', org_note: 'no company on the lead yet' });
    return { error: 'no company on the lead yet', people: [], status: 'none' };
  }
  const useSlug = (slug && String(slug).trim()) || lead.theorg_slug || null;
  // Accept a pasted theorg URL as the slug override.
  const cleanSlug = useSlug ? (useSlug.match(/theorg\.com\/org\/([^/?#]+)/) || [null, useSlug])[1] : null;
  const r = await fetchTheorg(api, { company: lead.company, slug: cleanSlug });
  if (r.error) {
    await updateLead(api, id, { org_status: 'none', org_note: r.error, theorg_slug: cleanSlug || lead.theorg_slug });
    return { ...r, status: 'none' };
  }
  // Localize photos into R2 (theorg URLs expire / hotlink-block).
  const localized = [];
  for (const p of r.people) {
    let photo = p.photo;
    if (photo && /^https?:/i.test(photo)) {
      const stored = await storeLeadPhoto(api, photo, `gtm/org/${id}/${p.nodeId}.jpg`);
      if (stored) photo = stored;
    }
    localized.push({ ...p, photo });
  }
  await replaceOrgPeople(api, id, r.company, localized);
  // CEO-mismatch heuristic: lead has a top title but the org root is someone else.
  const topTitle = /\b(ceo|founder|co-?founder|president|owner)\b/i.test(String(lead.position || ''));
  const roots = localized.filter((p) => !p.parentId);
  const leadIsRoot = roots.some((p) => namesMatch(p.name, lead.name));
  let status = 'saved', note = null;
  if (topTitle && roots.length && !leadIsRoot) {
    status = 'warn';
    note = `${lead.name} reads as a top exec but theorg's chart for "${r.company}" is headed by ${roots[0]?.name}. Possible namesake company — confirm the theorg slug.`;
  }
  await updateLead(api, id, { org_status: status, org_note: note, theorg_slug: cleanSlug || lead.theorg_slug });
  // Copy the prospect's theorg photo onto the lead if it has none.
  if (!(await getLead(api, id)).photo) {
    const self = localized.find((p) => namesMatch(p.name, lead.name));
    if (self?.photo) await updateLead(api, id, { photo: self.photo });
  }
  await api.log('org_chart', { id, company: r.company, people: localized.length, status });
  const people = await listOrgPeople(api, id);
  return { company: r.company, people, status, note };
}

// ── warm-path detection: You.connections × org people ───────────────────────

// Which of a lead's org people match the operator's warm connections.
export async function contactsInOrg(api, leadId) {
  const you = await readYou(api);
  const conns = you.connections || [];
  if (!conns.length) return [];
  const people = await listOrgPeople(api, leadId);
  return people.filter((p) => conns.some((c) => namesMatch(c, p.name))).map((p) => ({ name: p.name, role: p.role }));
}

// Green leads for the Enrich/Outreach tabs, with has_contact flags.
// BATCHED on purpose: the old shape called contactsInOrg per lead (a knowledge
// read + an org query each — ~2 subrequests/lead). At ~10 greens that was fine;
// the first big import pushed it past the Worker's 50-subrequest budget, the
// invocation died with error 1102, and the Enrich tab rendered blank. Now it is
// one knowledge read + one IN() query regardless of lead count.
export async function greenLeads(api) {
  const leads = await listLeads(api, { stage: 'green' });
  if (!leads.length) return [];
  const you = await readYou(api);
  const conns = you.connections || [];

  // all org people for all green leads, chunked to stay under D1's bind limit
  const byLead = new Map();
  const ids = leads.map((l) => l.id);
  for (let i = 0; i < ids.length; i += 80) {
    const chunk = ids.slice(i, i + 80);
    const r = await api.db.prepare(
      `SELECT lead_id, name, role FROM plugin_gtm_org_people WHERE lead_id IN (${chunk.map(() => '?').join(',')}) ORDER BY created_at`,
    ).bind(...chunk).all();
    for (const p of r.results || []) {
      if (!byLead.has(p.lead_id)) byLead.set(p.lead_id, []);
      byLead.get(p.lead_id).push(p);
    }
  }

  return leads.map((l) => {
    const people = byLead.get(l.id) || [];
    const contacts = conns.length
      ? people.filter((p) => conns.some((c) => namesMatch(c, p.name))).map((p) => ({ name: p.name, role: p.role }))
      : [];
    return { ...l, has_contact: contacts.length > 0, contacts };
  });
}

// ── ICP fit ──────────────────────────────────────────────────────────────────

export async function scoreIcpFit(api, leadId) {
  const lead = await getLead(api, leadId);
  if (!lead) return { error: 'no lead' };
  // The scorer judges name + title + company; without them the verdict is
  // noise. Enforced here — not just in a surface — so every caller (GTM
  // Enrich, Prospecting Qualification, the Nyo tool) shares one definition
  // and no LLM call is spent on a meaningless prospect.
  if (!String(lead.name || '').trim() || !lead.company || !lead.position) {
    return { error: 'needs a name, company and title before ICP match' };
  }
  const people = await listOrgPeople(api, leadId);
  // Single source of truth: the brand-baseline ICP (brand-icp, a HOST doc
  // declared in requires.knowledge). No gtm-specific ICP copy — the ICP is the
  // ICP, defined once in the brand tree.
  const icp = await gtmDoc(api, 'brand-icp', 'ICP not written yet — judge loosely by seniority + reachability.');
  const org = people.map((p) => `${p.name} - ${p.role}`).join('\n') || '(no org on file)';
  // Company facts gathered by companyContextForLead. The ICP is mostly a
  // statement about COMPANIES (size band, geography, technology-dependence), so
  // without these the model was inferring headcount from a brand name it may
  // never have heard of.
  const size = Number.isFinite(Number(lead.company_staff_count)) ? Number(lead.company_staff_count) : null;
  let openRoles = [];
  try { openRoles = JSON.parse(lead.open_positions || '[]') || []; } catch { openRoles = []; }
  const rolesLine = openRoles.length
    ? openRoles.slice(0, 12).map((p) => p.title).filter(Boolean).join(' · ')
    : (lead.positions_checked_at ? '(checked — none open)' : '(not checked)');
  const system = `Score how well a prospect fits this Ideal Customer Profile.

ICP:
${icp}

Return STRICT JSON only:
{"fit":"strong|medium|weak","reasons":["1-2 word tag"],"gaps":["1-2 word tag"]}
Each reason and gap is a 1 to 2 word tag, ultra glanceable, NOT a sentence and NOT a phrase (e.g. "Israeli founder", "reachable exec", "enterprise", "wrong stage", "no build need"). At most 3 of each. Judge only against the ICP. If a disqualifier applies, fit is weak.
Company facts come from LinkedIn and theorg. "unknown" or "not checked" means we have not looked it up — treat it as missing evidence, NEVER as a zero and never as a disqualifier on its own.`;
  const prompt = `PROSPECT: ${lead.name} - ${lead.position || '?'} at ${lead.company || '?'} (${[lead.region, lead.country].filter(Boolean).join(', ') || 'location unknown'})
COMPANY: ${lead.company || '?'} — ${size !== null ? `${size} employees (LinkedIn)` : 'headcount unknown'}
OPEN ROLES: ${rolesLine}
ORG CHART:
${org}

Produce the JSON.`;
  try {
    const out = extractJson(await gtmLLM(api, { system, prompt, model: null }));
    const fit = ['strong', 'medium', 'weak'].includes(out.fit) ? out.fit : 'weak';
    const fresh = await updateLead(api, leadId, { icp_fit: fit, icp_reasons: JSON.stringify({ reasons: out.reasons || [], gaps: out.gaps || [] }) });
    // Record the run in the lead's step history so a surface can show WHEN the
    // ICP match ran, not just its result. Merged over the row updateLead just
    // returned — NOT the pre-LLM read — so an enrich that finished during the
    // multi-second LLM call keeps its verdicts. A separate write on purpose:
    // the `steps` column arrives by a MANUAL migration, and a missing column
    // must not take the scoring — already persisted above — down with it.
    try {
      let prior = [];
      try { prior = JSON.parse(fresh?.steps) || []; } catch { prior = []; }
      const steps = (Array.isArray(prior) ? prior : []).filter((s) => s && s.key !== 'icp');
      steps.push({ key: 'icp', label: 'ICP match', status: 'found', reason: fit, at: now() });
      await updateLead(api, leadId, { steps: JSON.stringify(steps) });
    } catch (e) {
      console.error('gtm: icp step verdict not persisted (is the steps column migrated?)', e?.message || e);
    }
    await api.log('icp_scored', { id: leadId, fit });
    return { fit, reasons: out.reasons || [], gaps: out.gaps || [] };
  } catch (e) {
    return { error: String(e.message || e) };
  }
}

// ── the company behind the lead (LinkedIn) ───────────────────────────────────

// Resolve the lead's company on LinkedIn once and KEEP what comes back.
// The linkedin gateway's company mode answers { company_id, name,
// universal_name, staff_count, url }: company_id is what the jobs API needs,
// and staff_count is the size band the ICP is largely written in.
//
// Cached on the lead behind company_checked_at: a bulk pass over a list re-pays
// the throttled resolve only for leads never checked (or gone stale), which
// is what makes "fetch company context" safe to run on 50 rows.
//
// FAILURES are cached too, on a much shorter clock. Stamping only successes
// meant a lead whose resolve failed — an expired session, a private page, a bad
// name-slug — was re-attempted in full on every pass, so the exact rows that
// cost the most were the ones the cache never covered. The short retry window
// keeps a transient outage from being remembered for a month.
async function resolveLiCompany(api, lead, { refresh = false } = {}) {
  const pol = await loadGtmPolicy(api);
  let prevCtx = null;
  try { prevCtx = JSON.parse(lead.company_context || 'null'); } catch { prevCtx = null; }
  const lastFailed = !!prevCtx?.error;
  const ttl = lastFailed
    ? pol.company_retry_after_hours * 60 * 60 * 1000
    : pol.company_context_max_age_days * 24 * 60 * 60 * 1000;
  const checkedRecently = lead.company_checked_at && (now() - lead.company_checked_at) < ttl;
  if (!refresh && checkedRecently && (lead.company_li_id || lastFailed)) {
    return lastFailed
      ? { error: `${prevCtx.error} (cached — retried at most every ${pol.company_retry_after_hours}h)`, cached: true }
      : { company_id: lead.company_li_id, staff_count: lead.company_staff_count ?? null, cached: true };
  }
  // Find the company slug: a /company/ url among the socials, else the company
  // name slugified (no DDG here — datacenter IPs get blocked; the operator or
  // Nyo can paste the company page url).
  let liUrl = null;
  try { liUrl = (JSON.parse(lead.socials || '[]').find((x) => /linkedin\.com\/company\//i.test(x.url || '')) || {}).url; } catch { /* none */ }
  let slug = liUrl ? (liUrl.match(/\/company\/([^/?#]+)/) || [])[1] : null;
  if (!slug && lead.company) slug = String(lead.company).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  if (!slug) return { error: 'no company name or LinkedIn /company/ url on the lead' };

  let c;
  try {
    c = await api.gateway('linkedin', 'company', { universal_name: slug });
  } catch (e) {
    const error = `LinkedIn company resolve failed for slug "${slug}": ${String(e.message || e)}. Paste the company's linkedin.com/company/ URL into the lead's socials and retry.`;
    // Remember the FAILURE (not the values) so the retry window applies. The
    // value columns are deliberately untouched: a dead session must never cost
    // a headcount we already hold.
    try {
      await updateLead(api, lead.id, { company_context: JSON.stringify({ error, at: now() }), company_checked_at: now() });
      await api.log('company_resolved', { id: lead.id, ok: false, error: error.slice(0, 200) });
    } catch { /* the column may predate its migration — the error still returns */ }
    return { error };
  }
  // COALESCE, never clobber: the resolve can answer 200 with no staff_count
  // (private page, incomplete profile), and overwriting a good headcount with
  // null would make a checked row render as "not checked" — a lie about data we
  // already had. Same reasoning as the company id just below.
  const fresh = Number.isFinite(Number(c?.staff_count)) ? Number(c.staff_count) : null;
  const staff = fresh ?? (lead.company_staff_count ?? null);
  const cid = c?.company_id || lead.company_li_id || null;
  const answered = !!(c?.name || fresh !== null);
  const snapshot = answered
    ? { name: c?.name ?? null, universal_name: c?.universal_name ?? null, url: c?.url ?? null, staff_count: staff, at: now() }
    : { ...(prevCtx && !prevCtx.error ? prevCtx : {}), staff_count: staff, at: now() };
  // The company_* columns arrive by a MANUAL migration. If a deploy ever lands
  // ahead of it, still persist the company id — the jobs fetch depends on it —
  // and lose only the size snapshot.
  // Stamp provenance whenever LinkedIn actually answered with a figure. The
  // 'manual' marker is load-bearing — manualEditLead preserves a hand-entered
  // headcount across a company correction — so a fetched number must overwrite
  // the marker too, or it inherits protection it did not earn. A coalesced
  // value (LinkedIn had none) leaves the existing stamp alone, because the
  // number it describes has not changed.
  let srcs = {};
  try { srcs = JSON.parse(lead.sources || '{}') || {}; } catch { srcs = {}; }
  if (fresh !== null) srcs.company_staff_count = { tool: 'linkedin_company', at: new Date().toISOString() };
  try {
    await updateLead(api, lead.id, {
      company_li_id: cid,
      company_staff_count: staff,
      company_context: JSON.stringify(snapshot),
      company_checked_at: now(),
      ...(fresh !== null ? { sources: JSON.stringify(srcs) } : {}),
    });
    await api.log('company_resolved', { id: lead.id, ok: true, company_id: cid, staff_count: staff });
  } catch (e) {
    console.error('gtm: company context not persisted (are the company_* columns migrated?)', e?.message || e);
    try { await updateLead(api, lead.id, { company_li_id: cid }); } catch { /* id is best-effort too */ }
  }
  return { company_id: cid, staff_count: staff, name: c?.name || null, url: c?.url || null };
}

export async function openRolesForLead(api, leadId) {
  const lead = await getLead(api, leadId);
  if (!lead) return { error: 'no lead' };
  const c = await resolveLiCompany(api, lead);
  if (c.error) return { error: c.error };
  if (!c.company_id) return { error: 'could not resolve a LinkedIn company id' };
  try {
    const r = await api.gateway('linkedin', 'company_jobs', { company_id: c.company_id });
    const positions = r.positions || [];
    await updateLead(api, leadId, { open_positions: JSON.stringify(positions), positions_checked_at: now() });
    await api.log('open_roles', { id: leadId, count: positions.length });
    return { positions, company_id: c.company_id, count: positions.length, staff_count: c.staff_count ?? null };
  } catch (e) {
    return { error: `jobs fetch: ${String(e.message || e)}`, company_id: c.company_id };
  }
}

// Everything we can learn about the COMPANY behind a lead, in one pass: theorg's
// org chart, LinkedIn's headcount, LinkedIn's open roles. Exists so qualification
// can be run in bulk against real company facts instead of the model's guess
// about a brand name — see scoreIcpFit, which reads all three back.
//
// PARTIAL BY DESIGN: theorg and LinkedIn fail independently (a namesake company,
// an expired LI session, a private page). A lead that ends up with an org chart
// but no headcount is strictly better off than one with neither, so a failed leg
// is collected and reported, never fatal.
export async function companyContextForLead(api, leadId, { refresh = false } = {}) {
  const at = now();
  const lead = await getLead(api, leadId);
  if (!lead) return { error: 'no lead' };
  if (!lead.company) return { error: 'no company on the lead yet' };

  const org = await orgChartForLead(api, { id: leadId, refresh });
  // Re-read: orgChartForLead may have written to the lead (photo, org_status).
  const company = await resolveLiCompany(api, await getLead(api, leadId), { refresh });
  // Cheap after the resolve above — openRolesForLead's own resolve is a cache hit.
  // Skipped without an id: the jobs API is keyed on it, and re-reporting the
  // resolve failure here would surface one root cause as two separate problems.
  const roles = company.company_id ? await openRolesForLead(api, leadId) : { skipped: true };

  // Report the lead's ACTUAL state, not just what this run resolved. A failed
  // leg leaves the previously-stored facts in place on purpose, so reporting the
  // run's own (empty) result would tell every caller — including the sheet that
  // paints the Size column — that a known headcount is unknown.
  const after = await getLead(api, leadId);
  let storedRoles = [];
  try { storedRoles = JSON.parse(after?.open_positions || '[]') || []; } catch { storedRoles = []; }

  const out = {
    company: org.company || lead.company,
    org_people: (org.people || []).length,
    org_status: org.status ?? null,
    org_note: org.note ?? null,
    staff_count: after?.company_staff_count ?? null,
    open_roles: storedRoles.length,
    // Deduped: the legs share failure modes (one dead LinkedIn session breaks
    // both the resolve and the jobs fetch) and the operator needs the distinct
    // causes, not a tally.
    errors: [...new Set([org.error, company.error, roles.error].filter(Boolean))],
  };

  const found = out.org_people > 0 || out.staff_count !== null || out.open_roles > 0;
  const summary = [
    out.staff_count !== null ? `${out.staff_count} employees` : null,
    out.org_people ? `${out.org_people} org people` : null,
    out.open_roles ? `${out.open_roles} open roles` : null,
  ].filter(Boolean).join(' · ');
  // Same tolerant, merged-per-key step write the ICP match uses.
  try {
    let prior = [];
    try { prior = JSON.parse(after?.steps) || []; } catch { prior = []; }
    const steps = (Array.isArray(prior) ? prior : []).filter((s) => s && s.key !== 'company');
    steps.push({ key: 'company', label: 'Company', status: found ? 'found' : 'empty', reason: found ? summary : (out.errors[0] || 'nothing found'), at });
    await updateLead(api, leadId, { steps: JSON.stringify(steps) });
  } catch (e) {
    console.error('gtm: company step verdict not persisted (is the steps column migrated?)', e?.message || e);
  }

  await api.log('company_context', { id: leadId, staff_count: out.staff_count, org_people: out.org_people, open_roles: out.open_roles, errors: out.errors.length });
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// GRANULAR CONTEXT (v2): orgChartForLead / companyContextForLead / scoreIcpFit
// each fetch AND persist. Split so a workflow can order the fetches itself:
// pure fetchers here, one saver, and a scorer that reasons over facts it is
// handed instead of re-reading the row it is about to be scored against.
// ─────────────────────────────────────────────────────────────────────────────

// The org chart in theorg's own shape, no DB. `org_fetched` is the load-bearing
// flag: save_org_chart refuses to replace stored rows unless THIS run actually
// fetched, so a failed leg can never wipe a chart we already had.
export async function fetchOrgChartFor(api, { company = null, slug = null } = {}) {
  // Accept a pasted theorg URL as the slug override.
  const cleanSlug = slug ? (String(slug).match(/theorg\.com\/org\/([^/?#]+)/) || [null, slug])[1] : null;
  if (!company && !cleanSlug) return { org_fetched: false, org_error: 'no company on the lead yet', org_people: [] };
  const r = await fetchTheorg(api, { company, slug: cleanSlug });
  if (r.error) return { org_fetched: false, org_error: r.error, org_people: [], theorg_slug: cleanSlug };
  return { org_fetched: true, org_company: r.company, org_people: r.people || [], theorg_slug: cleanSlug };
}

// Stored org people in the SAME shape fetchOrgChartFor returns, so every
// downstream consumer (the CEO heuristic, angle drafting) reads one shape
// whether the chart came from theorg just now or from D1 last week.
export async function listOrgChart(api, leadId) {
  const rows = await listOrgPeople(api, leadId);
  return rows.map((p) => ({
    nodeId: p.node_id, parentId: p.parent_node_id, name: p.name, role: p.role,
    photo: p.photo_url, reportCount: p.report_count,
  }));
}

// Persist a fetched chart: photos localized into R2 (theorg URLs expire and
// hotlink-block), rows replaced, org verdict stamped on the lead.
export async function saveOrgChart(api, { id, org_company = null, org_people = [], org_status = null, org_note = null, theorg_slug = null, org_fetched = false } = {}) {
  if (!org_fetched) return { saved: false, skipped: 'no chart fetched this run — stored rows kept', people_count: 0, status: org_status };
  const lead = await getLead(api, id);
  if (!lead) return { error: 'no lead' };
  const localized = [];
  for (const p of org_people) {
    let photo = p.photo;
    if (photo && /^https?:/i.test(photo)) {
      const stored = await storeLeadPhoto(api, photo, `gtm/org/${id}/${p.nodeId}.jpg`);
      if (stored) photo = stored;
    }
    localized.push({ ...p, photo });
  }
  await replaceOrgPeople(api, id, org_company, localized);
  await updateLead(api, id, { org_status: org_status || 'saved', org_note: org_note ?? null, theorg_slug: theorg_slug || lead.theorg_slug });
  // Give the prospect their own theorg photo when the lead has none.
  if (!lead.photo) {
    const self = localized.find((p) => namesMatch(p.name, lead.name));
    if (self?.photo) await updateLead(api, id, { photo: self.photo });
  }
  await api.log('org_chart', { id, company: org_company, people: localized.length, status: org_status || 'saved' });
  return { saved: true, people_count: localized.length, status: org_status || 'saved' };
}

// Resolve the company on LinkedIn — the id the jobs API needs and the headcount
// the ICP is written in. Reads the cache windows from the plugin-gtm-policy doc
// but WRITES NOTHING: the snapshot (success or failure) rides back in
// company_profile for save_lead to persist, which is what keeps the retry
// window honest without giving a fetcher a second job.
export async function fetchCompanyProfile(api, { lead = null, company = null, company_linkedin_url = null, refresh = false } = {}) {
  const l = lead || {};
  const pol = await loadGtmPolicy(api);
  let prevCtx = null;
  try { prevCtx = JSON.parse(l.company_context || 'null'); } catch { prevCtx = null; }
  const lastFailed = !!prevCtx?.error;
  const ttl = lastFailed
    ? pol.company_retry_after_hours * 60 * 60 * 1000
    : pol.company_context_max_age_days * 24 * 60 * 60 * 1000;
  const checkedRecently = l.company_checked_at && (now() - l.company_checked_at) < ttl;
  if (!refresh && checkedRecently && (l.company_li_id || lastFailed)) {
    const cached = lastFailed
      ? { error: `${prevCtx.error} (cached — retried at most every ${pol.company_retry_after_hours}h)`, cached: true }
      : { company_id: l.company_li_id, staff_count: l.company_staff_count ?? null, cached: true };
    return { company_profile: cached, company_id: cached.company_id ?? null, staff_count: cached.staff_count ?? null, company_name: null, company_url: null };
  }
  // A /company/ url beats a slugified name (no search here — datacenter IPs get
  // blocked; the operator or Nyo pastes the company page url instead).
  let liUrl = company_linkedin_url;
  if (!liUrl) { try { liUrl = (JSON.parse(l.socials || '[]').find((x) => /linkedin\.com\/company\//i.test(x.url || '')) || {}).url; } catch { /* none */ } }
  const named = company || l.company;
  let slug = liUrl ? (liUrl.match(/\/company\/([^/?#]+)/) || [])[1] : null;
  if (!slug && named) slug = String(named).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  if (!slug) return { company_profile: { error: 'no company name or LinkedIn /company/ url on the lead' }, company_id: null, staff_count: null };

  let c;
  try {
    c = await api.gateway('linkedin', 'company', { universal_name: slug });
  } catch (e) {
    const error = `LinkedIn company resolve failed for slug "${slug}": ${String(e.message || e)}. Paste the company's linkedin.com/company/ URL into the lead's socials and retry.`;
    // Remember the FAILURE, never the values: a dead session must not cost a
    // headcount we already hold.
    return { company_profile: { error, company_context: { error, at: now() }, checked_at: now() }, company_id: null, staff_count: null };
  }
  const fresh = Number.isFinite(Number(c?.staff_count)) ? Number(c.staff_count) : null;
  const staff = fresh ?? (l.company_staff_count ?? null);
  const cid = c?.company_id || l.company_li_id || null;
  const answered = !!(c?.name || fresh !== null);
  const snapshot = answered
    ? { name: c?.name ?? null, universal_name: c?.universal_name ?? null, url: c?.url ?? null, staff_count: staff, at: now() }
    : { ...(prevCtx && !prevCtx.error ? prevCtx : {}), staff_count: staff, at: now() };
  await api.log('company_resolved', { id: l.id, ok: true, company_id: cid, staff_count: staff });
  return {
    // staff_count_fresh is what tells save_lead to re-stamp provenance: a
    // coalesced number has not changed, so its existing stamp still describes it.
    company_profile: { company_id: cid, staff_count: staff, staff_count_fresh: fresh !== null, company_context: snapshot, checked_at: now() },
    company_id: cid,
    staff_count: staff,
    company_name: c?.name || null,
    company_url: c?.url || null,
  };
}

// Open roles from LinkedIn's guest jobs API. Pure — save_lead persists them.
export async function fetchOpenRoles(api, { company_id } = {}) {
  if (!company_id) return { skipped: 'no LinkedIn company id — resolve the company first', positions: [], count: 0 };
  try {
    const r = await api.gateway('linkedin', 'company_jobs', { company_id });
    const positions = r.positions || [];
    return { positions, count: positions.length };
  } catch (e) {
    return { positions_error: `jobs fetch: ${String(e.message || e)}`, positions: [], count: 0 };
  }
}

// Score a prospect against the editable brand-icp doc using the company facts it
// is HANDED (org chart, headcount, open roles) rather than facts it re-reads —
// in a workflow the reconciled identity is newer than the stored row.
export async function scoreIcpFromFacts(api, { lead, org_people = [], staff_count = null, positions = null } = {}) {
  const l = lead || {};
  // The scorer judges name + title + company; without them the verdict is noise.
  // One definition for every caller, and no LLM call spent on a meaningless row.
  if (!String(l.name || '').trim() || !l.company || !l.position) {
    return { error: 'needs a name, company and title before ICP match' };
  }
  // Single source of truth: the brand-baseline ICP. The ICP is the ICP.
  const icp = await gtmDoc(api, 'brand-icp', 'ICP not written yet — judge loosely by seniority + reachability.');
  const org = (org_people || []).map((p) => `${p.name} - ${p.role}`).join('\n') || '(no org on file)';
  const size = Number.isFinite(Number(staff_count ?? l.company_staff_count)) ? Number(staff_count ?? l.company_staff_count) : null;
  let openRoles = positions;
  if (!Array.isArray(openRoles)) { try { openRoles = JSON.parse(l.open_positions || '[]') || []; } catch { openRoles = []; } }
  const rolesLine = openRoles.length
    ? openRoles.slice(0, 12).map((p) => p.title).filter(Boolean).join(' · ')
    : (l.positions_checked_at ? '(checked — none open)' : '(not checked)');
  const system = `Score how well a prospect fits this Ideal Customer Profile.

ICP:
${icp}

Return STRICT JSON only:
{"fit":"strong|medium|weak","reasons":["1-2 word tag"],"gaps":["1-2 word tag"]}
Each reason and gap is a 1 to 2 word tag, ultra glanceable, NOT a sentence and NOT a phrase (e.g. "Israeli founder", "reachable exec", "enterprise", "wrong stage", "no build need"). At most 3 of each. Judge only against the ICP. If a disqualifier applies, fit is weak.
Company facts come from LinkedIn and theorg. "unknown" or "not checked" means we have not looked it up — treat it as missing evidence, NEVER as a zero and never as a disqualifier on its own.`;
  const prompt = `PROSPECT: ${l.name} - ${l.position || '?'} at ${l.company || '?'} (${[l.region, l.country].filter(Boolean).join(', ') || 'location unknown'})
COMPANY: ${l.company || '?'} — ${size !== null ? `${size} employees (LinkedIn)` : 'headcount unknown'}
OPEN ROLES: ${rolesLine}
ORG CHART:
${org}

Produce the JSON.`;
  try {
    const out = extractJson(await gtmLLM(api, { system, prompt, model: null }));
    const fit = ['strong', 'medium', 'weak'].includes(out.fit) ? out.fit : 'weak';
    await api.log('icp_scored', { id: l.id, fit });
    return { icp_fit: fit, icp_reasons: out.reasons || [], icp_gaps: out.gaps || [] };
  } catch (e) {
    return { error: String(e.message || e) };
  }
}

// GTM plugin lib — outreach cadence. Ported from workers/api/src/lib/
// outreach-cadence.js: the editable rules for the automated queue, and for
// when a conversation counts as dead. Reads/writes ONE knowledge doc (the
// plugin's own, re-slugged) and hands back plain numbers.
//
// Only the two doc entry points live here (read_cadence / save_cadence tools).
// The window math (zonedParts, withinWindow, …) is duplicated inside
// outreach-cohorts.mjs — pack libs import nothing, not even each other.

const SLUG = 'plugin-gtm-outreach-cohort-cadence';

// Defaults are deliberately conservative: follow-ups spread over two weeks,
// a small daily ceiling, and business hours only. The doc overrides all of it.
export const CADENCE_DEFAULTS = {
  // hours to wait before each FOLLOW-UP (step 0 is the first touch and goes as
  // soon as it is due). Fewer entries than bubbles → the last value repeats.
  step_delays_hours: [72, 96, 168],
  max_sends_per_day: 20,
  min_gap_minutes: 8,
  quiet_start_hour: 9,   // sends allowed from this hour…
  quiet_end_hour: 19,    // …until this one, operator local time
  weekdays_only: true,
  timezone: 'Asia/Jerusalem',
  dead_after_days: 21,
  // Every individual message waits for the operator to approve it, rather than
  // go-live approving a person's whole ladder in one press. Defaults ON: the
  // safe direction for a mistake here is "nothing sent", never "sent unread".
  require_approval: true,
  // Ceiling on a message the operator writes by hand in the cohort sheet.
  max_message_chars: 4000,
};

const NUMERIC = ['max_sends_per_day', 'min_gap_minutes', 'quiet_start_hour', 'quiet_end_hour', 'dead_after_days', 'max_message_chars'];

function coerce(src) {
  const out = { ...CADENCE_DEFAULTS };
  if (!src || typeof src !== 'object') return out;
  for (const k of NUMERIC) {
    const v = Number(src[k]);
    if (Number.isFinite(v) && v >= 0) out[k] = Math.floor(v);
  }
  if (Array.isArray(src.step_delays_hours)) {
    const arr = src.step_delays_hours.map(Number).filter((n) => Number.isFinite(n) && n >= 0);
    if (arr.length) out.step_delays_hours = arr;
  }
  if (typeof src.weekdays_only === 'boolean') out.weekdays_only = src.weekdays_only;
  if (typeof src.require_approval === 'boolean') out.require_approval = src.require_approval;
  if (typeof src.timezone === 'string' && src.timezone.trim()) out.timezone = src.timezone.trim();
  // A window that cannot open would silently freeze the queue forever — treat
  // it as unset rather than letting it look like "nothing is due".
  if (out.quiet_end_hour <= out.quiet_start_hour) {
    out.quiet_start_hour = CADENCE_DEFAULTS.quiet_start_hour;
    out.quiet_end_hour = CADENCE_DEFAULTS.quiet_end_hour;
  }
  return out;
}

// Read the cadence. Never throws. (The host version seeded the doc on first
// read via its knowledge helper; here loading falls back to defaults when the
// doc is absent, and the save path creates it.)
export async function loadCohortCadence(api) {
  try {
    const doc = await api.knowledge(SLUG);
    if (!doc) return { cadence: { ...CADENCE_DEFAULTS }, source: 'defaults', notes: '' };
    const body = String(doc.body || '');
    const m = body.match(/```json\s*([\s\S]*?)```/);
    let parsed = null;
    if (m) { try { parsed = JSON.parse(m[1]); } catch { parsed = null; } }
    const idx = body.indexOf('\n---\n');
    return {
      cadence: coerce(parsed),
      source: parsed ? 'doc' : 'defaults',
      notes: (idx >= 0 ? body.slice(idx + 5) : '').trim(),
    };
  } catch {
    return { cadence: { ...CADENCE_DEFAULTS }, source: 'defaults', notes: '' };
  }
}

// Merge a patch into the doc's json block, leaving the prose untouched.
export async function saveCohortCadence(api, patch = {}) {
  const cur = await loadCohortCadence(api);
  const next = coerce({ ...cur.cadence, ...patch });
  const doc = await api.knowledge(SLUG).catch(() => null);
  const body = String(doc?.body || '');
  const json = JSON.stringify(next, null, 2);
  const nextBody = body.match(/```json\s*([\s\S]*?)```/)
    ? body.replace(/```json\s*[\s\S]*?```/, '```json\n' + json + '\n```')
    : `Outreach · Queue cadence.\n\n\`\`\`json\n${json}\n\`\`\`\n\n---\n${cur.notes}`;
  await api.saveKnowledge(SLUG, { title: 'Outreach · Queue cadence', body: nextBody });
  await api.log('outreach_cadence_updated', next);
  return { cadence: next, source: 'doc' };
}

// GTM plugin lib — outreach content classifier. Ported from
// workers/api/src/lib/outreach-classify.js: reads each outbound WhatsApp
// message and decides whether it's a GENUINE outreach pitch (aligned with our
// outreach content) or just a follow-up / reply / personal message. This is
// what lets the KPI count real outreach instead of every message you happened
// to send.
//
// Plugin placement: a reasoning helper behind the KPI. It reaches the model
// ONLY through the `llm` gateway (api.gateway('llm','text',…) — the single
// sanctioned LLM boundary), on the knowledge-backed `writer_small` model tier
// (host `llm-models` doc, declared read), reads its rubric from an editable
// plugin knowledge note (plugin-gtm-outreach-signature) grounded in the real
// plugin-gtm-outreach guide, and caches every verdict in
// plugin_gtm_wa_outreach_class so a message is classified once. Light call →
// falls back to the local model if the main model is down (low-stakes).
//
// Lib contract: no imports; every exported function takes `api` first.

const SIG_SLUG = 'plugin-gtm-outreach-signature';

const SIGNATURE_DEFAULT = `What a GENUINE outreach message looks like (counts toward the KPI):
- A first-touch / cold message opening a conversation with a prospect.
- Introduces who we are (Lev / Nyyon — a forward-deployed AI consultancy) or leads with a personalized hook, then makes a soft ask (connect, a quick call, sharing something relevant).
- Reads like a deliberate business pitch, even when personalized and casual.

What is NOT outreach (does NOT count):
- Follow-up nudges on an existing thread ("did you see my message?", "just bumping this").
- Replies continuing an ongoing conversation (answering a question, logistics, scheduling).
- Personal / social messages to friends or acquaintances ("yo, how are you", catching up).
- Operational chatter (invoices, expenses, files, internal coordination).

Rule of thumb: if this message is the kind of thing we'd send a brand-new prospect to START a business relationship, it's outreach. If it only makes sense as part of an existing relationship or thread, it's not.`;

function sigSeedBody(sig) {
  return `Outreach signature — the rubric the KPI uses to tell a genuine outreach message from a follow-up or personal chat.

The classifier reads each outbound WhatsApp message and, using this rubric plus the real \`plugin-gtm-outreach\` guide, decides is_outreach true/false. Edit this note to tune what counts — e.g. add phrases your outreach always uses, or examples of messages that should NOT count. Changes apply to newly-classified messages with no deploy.

---
${sig}
`;
}

// writer_small tier from the host `llm-models` doc (a declared host knowledge
// read). Plugins see no env vars, so the doc value falls straight back to the
// coded default (the host's own default) instead of ANTHROPIC_SMALL_MODEL.
const WRITER_SMALL_DEFAULT = 'claude-haiku-4-5-20251001';
function cleanModelId(v) {
  const s = String(v ?? '').trim();
  // model ids are short tokens — refuse anything that looks like prose/injection
  return s && s.length <= 120 && !/\s{2,}|\n/.test(s) ? s : null;
}
async function writerSmallModel(api) {
  try {
    const doc = await api.knowledge('llm-models');
    const m = String(doc?.body || '').match(/```json\s*([\s\S]*?)```/);
    const src = m ? JSON.parse(m[1]) : {};
    return cleanModelId(src.writer_small) || WRITER_SMALL_DEFAULT;
  } catch {
    return WRITER_SMALL_DEFAULT;
  }
}

export async function loadSignature(api) {
  try {
    const doc = await api.knowledge(SIG_SLUG);
    if (!doc) {
      await api.saveKnowledge(SIG_SLUG, {
        title: 'Outreach · signature (KPI classifier rubric)',
        body: sigSeedBody(SIGNATURE_DEFAULT),
      }).catch(() => {});
      return { rubric: SIGNATURE_DEFAULT, source: 'defaults' };
    }
    // the rubric is everything after the '---' separator, else the whole body
    const body = String(doc.body || '');
    const idx = body.indexOf('\n---\n');
    return { rubric: (idx >= 0 ? body.slice(idx + 5) : body).trim() || SIGNATURE_DEFAULT, source: 'doc' };
  } catch {
    return { rubric: SIGNATURE_DEFAULT, source: 'defaults' };
  }
}

export async function saveSignature(api, rubric) {
  const clean = String(rubric || '').trim() || SIGNATURE_DEFAULT;
  await api.saveKnowledge(SIG_SLUG, {
    title: 'Outreach · signature (KPI classifier rubric)',
    body: sigSeedBody(clean),
  });
  await api.log('outreach_signature_updated', { chars: clean.length });
  return { rubric: clean, source: 'doc' };
}

// Classify a batch of messages in ONE LLM call. Returns Map<msg_id, {is,reason}>.
// Channel-agnostic: items are { id, body } — reused for LinkedIn sent messages.
export async function classifyBatch(api, items) {
  const { rubric } = await loadSignature(api);
  let guide = '';
  try { guide = String((await api.knowledge('plugin-gtm-outreach'))?.body || ''); } catch { guide = ''; }
  const system = `You label WhatsApp messages as genuine business OUTREACH or not, for a sales KPI.

${rubric}

${guide ? `Our actual outreach guide (source of truth for what our outreach content sounds like):\n${String(guide)}\n` : ''}
You will get a numbered list of outbound messages (messages WE sent). For each, decide if it is a genuine outreach pitch (true) or not (false). Judge by CONTENT and language, not length. Messages may be in Hebrew or English.
Return STRICT JSON only: {"verdicts":[{"i":<number>,"outreach":true|false,"why":"<=6 words"}]}`;
  const prompt = items.map((it, n) => `[${n}] ${String(it.body || '').replace(/\s+/g, ' ').slice(0, 300)}`).join('\n');
  const maxTokens = Math.min(4000, 300 + items.length * 60);
  // Classification is a cheap utility call → the knowledge-backed `writer_small`
  // tier (llm-models doc; default Haiku). Runs through the ONLY sanctioned LLM
  // boundary (the `llm` gateway → circuit breaker → local fallback), never a
  // direct model call. heavy:false so it degrades to the local model if the
  // main model is down instead of pausing.
  const model = await writerSmallModel(api);
  const raw = await api.gateway('llm', 'text', { system, prompt, model, max_tokens: maxTokens, heavy: false });
  // Parse tolerantly: pull each {"i":N,...,"outreach":true|false,...,"why":"..."}
  // with a regex instead of JSON.parse-ing the whole reply — survives code
  // fences and a truncated final object (we keep every verdict that completed).
  const map = new Map();
  const s = String(raw || '');
  const re = /"i"\s*:\s*(\d+)[\s\S]{0,80}?"outreach"\s*:\s*(true|false)(?:[\s\S]{0,20}?"why"\s*:\s*"([^"]{0,120})")?/g;
  let m;
  while ((m = re.exec(s)) !== null) {
    const it = items[Number(m[1])];
    if (it) map.set(it.id, { is: m[2] === 'true' ? 1 : 0, reason: (m[3] || '').slice(0, 120) });
  }
  if (map.size === 0) { const e = new Error(`classify parse failed: ${s.slice(0, 200)}`); e.raw = s.slice(0, 4000); throw e; }
  // anything the model skipped → default not-outreach (conservative)
  for (const it of items) if (!map.has(it.id)) map.set(it.id, { is: 0, reason: 'unclassified' });
  return map;
}

// Ensure every outbound 1:1 WhatsApp message since `sinceMs` has a cached
// verdict. Bounded per call; safe to call on read paths (returns fast when
// everything's already classified). Returns count newly classified.
// Returns a diagnostic object: { classified, pending, error?, raw? }. Never
// throws — read paths call it fire-and-forget.
export async function ensureClassified(api, sinceMs, { limit = 80 } = {}) {
  let pending;
  try {
    pending = (await api.db.prepare(
      `SELECT m.id, m.chat_id, m.body FROM wa_messages m
       LEFT JOIN plugin_gtm_wa_outreach_class c ON c.msg_id = m.id
       WHERE m.from_me = 1 AND m.chat_id NOT LIKE '%@g.us' AND m.timestamp >= ?
         AND c.msg_id IS NULL AND m.body IS NOT NULL AND length(trim(m.body)) > 1
       ORDER BY m.timestamp DESC LIMIT ?`,
    ).bind(sinceMs, limit).all()).results || [];
  } catch (e) { return { classified: 0, pending: 0, error: `select: ${String(e?.message || e)}` }; }
  if (!pending.length) return { classified: 0, pending: 0 };

  const t = Date.now();
  let wrote = 0; let firstErr = null;
  // Classify in small chunks — one LLM call each — so a long day can't produce a
  // truncated (unparseable) response, and one bad chunk doesn't lose the rest.
  for (let i = 0; i < pending.length; i += 25) {
    const chunk = pending.slice(i, i + 25);
    let verdicts;
    try { verdicts = await classifyBatch(api, chunk); }
    catch (e) { if (!firstErr) firstErr = { error: String(e?.message || e), raw: e?.raw }; continue; }
    for (const it of chunk) {
      const v = verdicts.get(it.id) || { is: 0, reason: 'unclassified' };
      try {
        await api.db.prepare(
          `INSERT OR REPLACE INTO plugin_gtm_wa_outreach_class (msg_id, chat_id, is_outreach, reason, classified_at)
           VALUES (?, ?, ?, ?, ?)`,
        ).bind(it.id, it.chat_id, v.is, v.reason, t).run();
        wrote++;
      } catch { /* skip a bad row, keep going */ }
    }
  }
  if (wrote) await api.log('outreach_classified', { n: wrote });
  return { classified: wrote, pending: pending.length, ...(firstErr || {}) };
}

// GTM plugin · outreach-cohorts — the cohort engine, ported verbatim from
// workers/api/src/lib/outreach-cohorts.js.
//
// Contract v2.1 lib file: imports NOTHING. Every helper this engine used to
// import (sequence rendering, cadence windows, WA thread facts, model config)
// is duplicated below, per the pack contract. Every exported function takes
// `api` as its first argument in place of env.
//
// Tables: plugin_gtm_leads, plugin_gtm_outreach_cohorts,
// plugin_gtm_outreach_cohort_members, plugin_gtm_outreach_conversation_state
// (own, read-write) — wa_messages, wa_lid_map, feature_flags (host, SELECT-only).
//
// The copy is NOT written here and is never written unattended: it is the
// COHORT's own sequence, authored once for the group and personalised per
// recipient by variables and language variant. Step 0 is the first touch, step
// 1 the first follow-up, and so on. When the steps run out the prospect leaves
// the cohort. So every automated message is one the operator already approved.
//
// THE RULE THIS FILE EXISTS TO ENFORCE: a prospect who has said anything back
// is out of the automation, permanently — and that is re-checked in the moment
// before each send, not merely when the send was scheduled. A follow-up scheduled
// three days ago must not land on someone who replied yesterday.
//
// Sending is gated on the `outreach.live` feature flag. Until it is true the
// tick does everything except send, recording what it WOULD have sent.

const now = () => Date.now();
const safeJSON = (s) => { if (!s) return null; try { return JSON.parse(s); } catch { return s; } };

const CHUNK = 80;
const LIVE_FLAG = 'outreach.live';
// Members predating named cohorts, and anything created without one, live here.
const DEFAULT_COHORT = 'oq_default';

const qid = () => `oq_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;

// ════════════════════════════════════════════════════════════════════════════
// Duplicated: the sequence engine (from lib/outreach-sequence.js). Pure —
// parse, resolve a language, substitute, and report what is missing.
// ════════════════════════════════════════════════════════════════════════════

const VARIABLES = {
  first_name: (l) => String(l?.name || '').trim().split(/\s+/)[0] || '',
  name: (l) => String(l?.name || '').trim(),
  company: (l) => String(l?.company || '').trim(),
  position: (l) => String(l?.position || '').trim(),
  country: (l) => String(l?.country || '').trim(),
};
const VARIABLE_NAMES = Object.keys(VARIABLES);

const TOKEN = /\{([a-z_]+)\}/g;

// Which surface a step goes out on. Only WhatsApp is actually wired to a
// sender; the engine refuses the others out loud rather than pretending.
const CHANNELS = ['whatsapp', 'linkedin', 'email'];
const WIRED_CHANNELS = ['whatsapp'];
const TRIGGERS = ['no_reply', 'always'];

function parseSequence(raw) {
  let src = raw;
  if (typeof raw === 'string') { try { src = JSON.parse(raw); } catch { src = null; } }
  const steps = Array.isArray(src?.steps) ? src.steps : [];
  return {
    default_language: String(src?.default_language || 'en').toLowerCase(),
    steps: steps.map((s, i) => ({
      // Step 0 goes as soon as it is approved; later steps wait from the
      // previous send. A missing delay must not collapse a follow-up onto the
      // opener, so anything after the first defaults to a real gap.
      delay_hours: Number.isFinite(Number(s?.delay_hours)) ? Math.max(0, Number(s.delay_hours)) : (i === 0 ? 0 : 72),
      channel: CHANNELS.includes(s?.channel) ? s.channel : 'whatsapp',
      trigger: TRIGGERS.includes(s?.trigger) ? s.trigger : 'no_reply',
      bodies: (s?.bodies && typeof s.bodies === 'object') ? s.bodies : {},
    })).filter((s) => Object.values(s.bodies).some((b) => String(b || '').trim())),
  };
}

function serializeSequence(seq) {
  return JSON.stringify(parseSequence(seq));
}

// Which language a given prospect should receive. An explicit per-lead override
// wins; otherwise Israel gets Hebrew and everyone else the sequence default.
function languageFor(lead, seq) {
  const parsed = parseSequence(seq);
  const explicit = String(lead?.outreach_lang || '').trim().toLowerCase();
  const guessed = /israel/i.test(String(lead?.country || '')) ? 'he' : parsed.default_language;
  return { preferred: explicit || guessed, fallback: parsed.default_language };
}

function pickBody(step, lead, seq) {
  const { preferred, fallback } = languageFor(lead, seq);
  const has = (k) => String(step.bodies?.[k] || '').trim();
  return has(preferred) ? { body: step.bodies[preferred], lang: preferred }
    : has(fallback) ? { body: step.bodies[fallback], lang: fallback }
    : (() => {
        const first = Object.keys(step.bodies).find((k) => has(k));
        return first ? { body: step.bodies[first], lang: first } : { body: '', lang: null };
      })();
}

function renderStep(step, lead, seq) {
  const { body, lang } = pickBody(step, lead, seq);
  return { ...renderBody(body, lead), lang };
}

// Substitute one piece of copy for one prospect. A per-person edit goes through
// the SAME substitution and the same "missing" reporting as the cohort's own
// copy — an override rendered by different rules could ship a raw {company}.
function renderBody(body, lead) {
  const missing = new Set();
  const unknown = new Set();
  const text = String(body || '').replace(TOKEN, (whole, key) => {
    const get = VARIABLES[key];
    if (!get) { unknown.add(key); return whole; }
    const v = get(lead);
    if (!v) { missing.add(key); return whole; }
    return v;
  });
  return { text, missing: [...missing], unknown: [...unknown] };
}

// Render the whole sequence for one prospect. `blocked` is the single question
// the go-live check asks: is there any step this person cannot receive cleanly?
function renderSequence(seq, lead) {
  const parsed = parseSequence(seq);
  const steps = parsed.steps.map((s, i) => ({
    index: i, delay_hours: s.delay_hours, channel: s.channel, trigger: s.trigger,
    ...renderStep(s, lead, parsed),
  }));
  const missing = [...new Set(steps.flatMap((s) => s.missing))];
  const unknown = [...new Set(steps.flatMap((s) => s.unknown))];
  return {
    steps,
    length: steps.length,
    missing,
    unknown,
    blocked: !parsed.steps.length
      ? 'this cohort has no message sequence yet'
      : missing.length
        ? `missing ${missing.map((m) => m.replace(/_/g, ' ')).join(', ')}`
        : unknown.length
          ? `unknown variable${unknown.length > 1 ? 's' : ''}: ${unknown.join(', ')}`
          : null,
  };
}

// Static check of the template itself, independent of any recipient.
function validateSequence(seq) {
  const parsed = parseSequence(seq);
  const unknown = new Set();
  const used = new Set();
  for (const s of parsed.steps) {
    for (const body of Object.values(s.bodies)) {
      let m;
      TOKEN.lastIndex = 0;
      while ((m = TOKEN.exec(String(body || ''))) !== null) {
        if (VARIABLES[m[1]]) used.add(m[1]); else unknown.add(m[1]);
      }
    }
  }
  const languages = [...new Set(parsed.steps.flatMap((s) => Object.keys(s.bodies)))];
  const unwired = [...new Set(parsed.steps.map((s) => s.channel).filter((c) => !WIRED_CHANNELS.includes(c)))];
  return {
    steps: parsed.steps.length,
    languages,
    unwired_channels: unwired,
    variables_used: [...used],
    unknown_variables: [...unknown],
    ok: parsed.steps.length > 0 && unknown.size === 0,
  };
}

// ════════════════════════════════════════════════════════════════════════════
// Duplicated: the cadence engine (from lib/outreach-cadence.js). Reads ONE
// knowledge doc (the plugin's own, re-slugged) and hands back plain numbers.
// ════════════════════════════════════════════════════════════════════════════

const CADENCE_SLUG = 'plugin-gtm-outreach-cohort-cadence';

// Defaults are deliberately conservative: follow-ups spread over two weeks,
// a small daily ceiling, and business hours only. The doc overrides all of it.
const CADENCE_DEFAULTS = {
  step_delays_hours: [72, 96, 168],
  max_sends_per_day: 20,
  min_gap_minutes: 8,
  quiet_start_hour: 9,
  quiet_end_hour: 19,
  weekdays_only: true,
  timezone: 'Asia/Jerusalem',
  dead_after_days: 21,
  // Every individual message waits for the operator to approve it. Defaults ON:
  // the safe direction for a mistake here is "nothing sent", never "sent unread".
  require_approval: true,
  max_message_chars: 4000,
};

const CADENCE_NUMERIC = ['max_sends_per_day', 'min_gap_minutes', 'quiet_start_hour', 'quiet_end_hour', 'dead_after_days', 'max_message_chars'];

function coerceCadence(src) {
  const out = { ...CADENCE_DEFAULTS };
  if (!src || typeof src !== 'object') return out;
  for (const k of CADENCE_NUMERIC) {
    const v = Number(src[k]);
    if (Number.isFinite(v) && v >= 0) out[k] = Math.floor(v);
  }
  if (Array.isArray(src.step_delays_hours)) {
    const arr = src.step_delays_hours.map(Number).filter((n) => Number.isFinite(n) && n >= 0);
    if (arr.length) out.step_delays_hours = arr;
  }
  if (typeof src.weekdays_only === 'boolean') out.weekdays_only = src.weekdays_only;
  if (typeof src.require_approval === 'boolean') out.require_approval = src.require_approval;
  if (typeof src.timezone === 'string' && src.timezone.trim()) out.timezone = src.timezone.trim();
  // A window that cannot open would silently freeze the queue forever — treat
  // it as unset rather than letting it look like "nothing is due".
  if (out.quiet_end_hour <= out.quiet_start_hour) {
    out.quiet_start_hour = CADENCE_DEFAULTS.quiet_start_hour;
    out.quiet_end_hour = CADENCE_DEFAULTS.quiet_end_hour;
  }
  return out;
}

// Read the cadence. Never throws. (The host version seeded the doc on write via
// its save path; loading falls back to defaults when the doc is absent.)
async function loadCohortCadence(api) {
  try {
    const doc = await api.knowledge(CADENCE_SLUG);
    if (!doc) return { cadence: { ...CADENCE_DEFAULTS }, source: 'defaults', notes: '' };
    const body = String(doc.body || '');
    const m = body.match(/```json\s*([\s\S]*?)```/);
    let parsed = null;
    if (m) { try { parsed = JSON.parse(m[1]); } catch { parsed = null; } }
    const idx = body.indexOf('\n---\n');
    return {
      cadence: coerceCadence(parsed),
      source: parsed ? 'doc' : 'defaults',
      notes: (idx >= 0 ? body.slice(idx + 5) : '').trim(),
    };
  } catch {
    return { cadence: { ...CADENCE_DEFAULTS }, source: 'defaults', notes: '' };
  }
}

// Hour-of-day + weekday in the configured zone. Intl does the DST work; a bad
// zone string falls back to UTC rather than throwing inside the cron.
function zonedParts(at, timezone) {
  try {
    const p = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone, hour: 'numeric', hour12: false, weekday: 'short',
    }).formatToParts(new Date(at));
    const hour = Number(p.find((x) => x.type === 'hour')?.value ?? 0);
    const wd = p.find((x) => x.type === 'weekday')?.value || '';
    return { hour: hour === 24 ? 0 : hour, weekday: wd, weekend: wd === 'Sat' || wd === 'Sun' };
  } catch {
    const d = new Date(at);
    return { hour: d.getUTCHours(), weekday: '', weekend: [0, 6].includes(d.getUTCDay()) };
  }
}

// Naming a moment in the zone it will actually happen in: the server names the
// moment — including the short zone tag and which calendar day it lands on —
// so the browser never re-derives it and the two can never disagree.
function zonedLabel(at, timezone) {
  if (!at) return null;
  try {
    const p = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone, weekday: 'short', hour: '2-digit', minute: '2-digit',
      hour12: false, timeZoneName: 'short', day: '2-digit', month: 'short',
    }).formatToParts(new Date(at));
    const get = (t) => p.find((x) => x.type === t)?.value || '';
    return {
      label: `${get('weekday')} ${get('day')} ${get('month')} ${get('hour')}:${get('minute')}`,
      zone: get('timeZoneName'),
      ymd: zonedYmd(at, timezone),
    };
  } catch {
    return { label: new Date(at).toISOString().slice(0, 16).replace('T', ' '), zone: 'UTC', ymd: new Date(at).toISOString().slice(0, 10) };
  }
}

// The calendar day `at` falls on in `timezone`.
function zonedYmd(at, timezone) {
  try {
    const p = new Intl.DateTimeFormat('en-CA', {
      timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit',
    }).formatToParts(new Date(at));
    const get = (t) => p.find((x) => x.type === t)?.value || '';
    return `${get('year')}-${get('month')}-${get('day')}`;
  } catch {
    return new Date(at).toISOString().slice(0, 10);
  }
}

// Per-weekday sending windows: `{"1":{"start":"09:00","end":"17:30"}}`, 0 =
// Sunday. An absent day sends nothing. Wall-clock in the cohort's zone.
function parseWindows(raw) {
  let src = raw;
  if (typeof raw === 'string') { try { src = JSON.parse(raw); } catch { return null; } }
  if (!src || typeof src !== 'object') return null;
  const hm = (v) => {
    const m = String(v || '').match(/^(\d{1,2}):(\d{2})$/);
    if (!m) return null;
    const h = Number(m[1]); const mi = Number(m[2]);
    if (h < 0 || h > 24 || mi < 0 || mi > 59) return null;
    return h * 60 + mi;
  };
  const out = {};
  for (let d = 0; d <= 6; d++) {
    const w = src[d] ?? src[String(d)];
    if (!w) continue;
    const s = hm(w.start); const e = hm(w.end);
    // A window that cannot open is worse than no window: it looks configured
    // and sends nothing. Drop the day instead of storing an impossible one.
    if (s === null || e === null || e <= s) continue;
    out[d] = { start: w.start, end: w.end, s, e };
  }
  return Object.keys(out).length ? out : null;
}

// Epoch for a wall-clock moment in `timezone`. Fixed-point iteration so DST
// changeovers land on the real instant rather than an hour out.
function epochForWall(timezone, y, mo, d, hh, mi) {
  let guess = Date.UTC(y, mo - 1, d, hh, mi);
  for (let i = 0; i < 4; i++) {
    let p;
    try {
      p = new Intl.DateTimeFormat('en-US', {
        timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit',
        hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
      }).formatToParts(new Date(guess));
    } catch { return guess; }
    const g = (t) => Number(p.find((x) => x.type === t)?.value ?? 0);
    const diff = Date.UTC(y, mo - 1, d, hh, mi) - Date.UTC(g('year'), g('month') - 1, g('day'), g('hour') % 24, g('minute'));
    if (!diff) break;
    guess += diff;
  }
  return guess;
}

const WEEKDAY_INDEX = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };

// Calendar date + weekday of `at` in `timezone`.
function zonedDate(at, timezone) {
  try {
    const p = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short',
    }).formatToParts(new Date(at));
    const g = (t) => p.find((x) => x.type === t)?.value || '';
    return { y: Number(g('year')), mo: Number(g('month')), d: Number(g('day')), wd: WEEKDAY_INDEX[g('weekday')] ?? 0 };
  } catch {
    const dt = new Date(at);
    return { y: dt.getUTCFullYear(), mo: dt.getUTCMonth() + 1, d: dt.getUTCDate(), wd: dt.getUTCDay() };
  }
}

// A cohort's own window layered over the account default. Anything the cohort
// leaves unset simply inherits.
function effectiveCadence(cadence, cohort) {
  if (!cohort) return cadence;
  const out = { ...cadence };
  if (cohort.timezone) out.timezone = cohort.timezone;
  const s = Number(cohort.start_hour);
  const e = Number(cohort.end_hour);
  if (Number.isFinite(s) && Number.isFinite(e) && e > s) {
    out.quiet_start_hour = Math.floor(s);
    out.quiet_end_hour = Math.floor(e);
  }
  let days = null;
  try { days = cohort.send_days ? JSON.parse(cohort.send_days) : null; } catch { days = null; }
  // An explicit day list beats the coarse weekdays_only flag. An EMPTY list
  // would mean "never" — treat it as unset rather than freezing the cohort.
  if (Array.isArray(days) && days.length) {
    out.send_days = days.map(Number).filter((d) => d >= 0 && d <= 6);
  }
  // Per-weekday windows, if the cohort has them, OVERRIDE both the single
  // start/end pair and the day list.
  const win = parseWindows(cohort.send_windows);
  if (win) out.send_windows = win;
  return out;
}

// Hour AND minute in the zone.
function zonedClock(at, timezone) {
  try {
    const p = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone, hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
    }).formatToParts(new Date(at));
    const g = (t) => Number(p.find((x) => x.type === t)?.value ?? 0);
    return { hour: g('hour') % 24, minute: g('minute') };
  } catch {
    const d = new Date(at);
    return { hour: d.getUTCHours(), minute: d.getUTCMinutes() };
  }
}

// Is `at` inside the allowed sending window?
function withinWindow(at, cadence) {
  if (cadence.send_windows) {
    const { wd } = zonedDate(at, cadence.timezone);
    const w = cadence.send_windows[wd];
    if (!w) return false;
    const { hour, minute } = zonedClock(at, cadence.timezone);
    const mins = hour * 60 + minute;
    return mins >= w.s && mins < w.e;
  }
  const { hour, weekend, weekday } = zonedParts(at, cadence.timezone);
  if (Array.isArray(cadence.send_days) && cadence.send_days.length) {
    const idx = WEEKDAY_INDEX[weekday];
    if (idx === undefined || !cadence.send_days.includes(idx)) return false;
  } else if (cadence.weekdays_only && weekend) {
    return false;
  }
  return hour >= cadence.quiet_start_hour && hour < cadence.quiet_end_hour;
}

// The next moment sending is allowed at or after `at`. With per-day windows
// this COMPUTES the opening rather than walking forward in whole hours, which
// would stride straight over a 09:30 start.
function nextWindowOpening(at, cadence) {
  if (cadence.send_windows) {
    const tz = cadence.timezone;
    for (let i = 0; i < 14; i++) {
      const probe = at + i * 86400000;
      const { y, mo, d, wd } = zonedDate(probe, tz);
      const w = cadence.send_windows[wd];
      if (!w) continue;
      const open = epochForWall(tz, y, mo, d, Math.floor(w.s / 60), w.s % 60);
      const shut = epochForWall(tz, y, mo, d, Math.floor(w.e / 60), w.e % 60);
      if (at <= open) return open;      // window still to come today
      if (at < shut) return at;         // already inside it
    }
    return at;                          // nothing open in a fortnight — say so by not moving
  }
  let t = at;
  for (let i = 0; i < 24 * 14; i++) {
    if (withinWindow(t, cadence)) return t;
    t += 3600000;
  }
  return at;
}

// ════════════════════════════════════════════════════════════════════════════
// Duplicated: WA thread facts (from lib/outreach-wa.js + lib/whatsapp.js).
// SELECT-only over the host's wa_messages / wa_lid_map cache. The host keeps
// that cache fresh (webhook + cron); the incremental gateway pull the host
// version ran before reading writes host tables and therefore cannot run here.
// ════════════════════════════════════════════════════════════════════════════

// WhatsApp timestamps arrive as seconds from some gateway builds and ms from
// others; normalise so ordering never silently inverts.
const waMs = (t) => (t == null ? null : (Number(t) < 1e12 ? Number(t) * 1000 : Number(t)));
const digitsOf = (s) => String(s || '').replace(/\D/g, '');

// The DM id for a phone. Group chats are never prospects — this is 1:1 only.
function chatIdForPhone(phone) {
  const s = String(phone || '').trim();
  if (!s) return null;
  if (s.endsWith('@c.us') || s.endsWith('@g.us') || s.endsWith('@lid')) return s;
  const digits = s.replace(/\D/g, '');
  return digits ? `${digits}@c.us` : null;
}

// Newest-first messages of one chat, raw_json parsed (host read).
async function recentMessages(api, { chat_id, limit = 200 } = {}) {
  const r = await api.db.prepare(
    'SELECT * FROM wa_messages WHERE chat_id = ? ORDER BY timestamp DESC LIMIT ?',
  ).bind(chat_id, limit).all();
  return (r.results || []).map((m) => ({ ...m, raw_json: safeJSON(m.raw_json) }));
}

// A row we wrote ourselves at send time (the host stamps raw_json.source), as
// opposed to one the gateway's webhook delivered.
function isPreInsert(m) {
  const raw = m?.raw_json;
  if (raw && typeof raw === 'object') return raw.source === 'outbound';
  return String(raw || '').includes('outbound');
}

// Every chat id that belongs to one person: the `@c.us` id and any `@lid`
// privacy twin WhatsApp issued for the same number (either direction).
async function siblingChatIds(api, chatId, lead) {
  const ids = new Set([chatId]);
  const phoneChat = lead ? chatIdForPhone(lead.normalized_phone || lead.phone) : null;
  if (phoneChat) ids.add(phoneChat);
  try {
    if (String(chatId).endsWith('@lid')) {
      const r = await api.db.prepare('SELECT phone, pn FROM wa_lid_map WHERE lid = ?').bind(chatId).first();
      const d = digitsOf(r?.phone || String(r?.pn || '').split('@')[0]);
      if (d) ids.add(`${d}@c.us`);
    }
    for (const pn of [...ids].filter((i) => String(i).endsWith('@c.us'))) {
      const r = await api.db.prepare('SELECT lid FROM wa_lid_map WHERE pn = ?').bind(pn).all();
      for (const row of r.results || []) if (row.lid) ids.add(row.lid);
    }
  } catch { /* map unavailable — the id we were given still works */ }
  return [...ids];
}

// Collapse the SAME outgoing message written twice: once at send time
// (pre-insert) and once when WhatsApp echoed it back through the webhook.
const DUP_WINDOW_MS = 3 * 60 * 1000;
function dedupeOutbound(messages) {
  const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim();
  const out = [];
  for (const m of messages) {
    if (!m.from_me) { out.push(m); continue; }
    const text = norm(m.body);
    const twin = text && out.find((k) => k.from_me && norm(k.body) === text
      && Math.abs((k.at || 0) - (m.at || 0)) < DUP_WINDOW_MS);
    if (!twin) { out.push(m); continue; }
    twin.preinsert = twin.preinsert && m.preinsert;
    twin.at = Math.min(twin.at || m.at || 0, m.at || twin.at || 0) || twin.at;
  }
  return out;
}

// The one place "what happened in this conversation" is decided. Every reader
// goes through this, so they cannot disagree about whether a prospect replied.
async function threadFacts(api, { chat_id, lead = null, limit = 300 } = {}) {
  const chatIds = await siblingChatIds(api, chat_id, lead);
  const rows = (await Promise.all(
    chatIds.map((cid) => recentMessages(api, { chat_id: cid, limit }).catch(() => [])),
  )).flat();

  const ordered = rows
    .map((m) => ({
      id: m.id,
      from_me: Number(m.from_me) === 1,
      body: m.body || '',
      sender_name: m.sender_name || null,
      at: waMs(m.timestamp),
      preinsert: isPreInsert(m),
    }))
    .filter((m) => String(m.body).trim())
    .sort((a, b) => (a.at || 0) - (b.at || 0));

  const messages = dedupeOutbound(ordered);
  const inbound = messages.filter((m) => !m.from_me);
  const outbound = messages.filter((m) => m.from_me);
  const last = messages[messages.length - 1] || null;

  return {
    chat_ids: chatIds,
    messages,
    // ANSWERED is the automation kill-switch: they said something back, ever.
    answered: inbound.length > 0,
    msgs_in: inbound.length,
    msgs_out: outbound.length,
    first_out_at: outbound[0]?.at ?? null,
    last_in_at: inbound[inbound.length - 1]?.at ?? null,
    last_out_at: outbound[outbound.length - 1]?.at ?? null,
    last_at: last?.at ?? null,
    last_text: last?.body ?? null,
    last_from_me: last ? last.from_me : null,
    uncaught: !!last && !last.from_me,
  };
}

// Per chat: the latest REAL message plus the inbound/outbound tallies
// (empty bodies are receipts, not text). Aggregated in SQL, chunked.
async function lastMessages(api, chatIds = []) {
  const out = new Map();
  for (let i = 0; i < chatIds.length; i += CHUNK) {
    const c = chatIds.slice(i, i + CHUNK);
    const ph = c.map(() => '?').join(',');
    const REAL = 'body IS NOT NULL AND length(trim(body)) > 0';
    const r = (await api.db.prepare(
      `SELECT m.chat_id, m.body, m.from_me, m.timestamp
         FROM wa_messages m
         JOIN (SELECT chat_id, MAX(timestamp) AS t
                 FROM wa_messages
                WHERE chat_id IN (${ph}) AND ${REAL}
                GROUP BY chat_id) x
           ON x.chat_id = m.chat_id AND x.t = m.timestamp`,
    ).bind(...c).all().catch(() => ({ results: [] }))).results || [];
    for (const row of r) if (!out.has(row.chat_id)) out.set(row.chat_id, row);

    const agg = (await api.db.prepare(
      `SELECT chat_id,
              SUM(CASE WHEN from_me = 0 THEN 1 ELSE 0 END) AS in_n,
              SUM(CASE WHEN from_me = 1 THEN 1 ELSE 0 END) AS out_n
         FROM wa_messages WHERE chat_id IN (${ph}) AND ${REAL}
        GROUP BY chat_id`,
    ).bind(...c).all().catch(() => ({ results: [] }))).results || [];
    for (const row of agg) {
      const ex = out.get(row.chat_id);
      if (ex) { ex.in_n = row.in_n || 0; ex.out_n = row.out_n || 0; }
    }
  }
  return out;
}

// Operator "this is dead" markings, keyed by lead (own plugin table).
async function deadMarks(api, leadIds = []) {
  const out = new Map();
  for (let i = 0; i < leadIds.length; i += CHUNK) {
    const c = leadIds.slice(i, i + CHUNK);
    const r = (await api.db.prepare(
      `SELECT lead_id, dead_at, dead_reason FROM plugin_gtm_outreach_conversation_state
        WHERE lead_id IN (${c.map(() => '?').join(',')}) AND dead_at IS NOT NULL`,
    ).bind(...c).all().catch(() => ({ results: [] }))).results || [];
    for (const row of r) out.set(row.lead_id, row);
  }
  return out;
}

// Where each prospect's conversation stands, in bulk. Vocabulary IDENTICAL to
// the Conversations tab's buckets, derived from the same messages:
//   untouched — nothing has ever been sent to them
//   touched   — we have sent, they have not replied
//   active    — they have replied; the automation is off them permanently
//   dead      — marked dead by hand, or nothing happened for dead_after_days
// Dead wins over active, exactly as it does in the inbox.
async function conversationStatesFor(api, leads = []) {
  const out = new Map();
  if (!leads.length) return out;
  const deadAfterDays = (await loadCohortCadence(api)).cadence.dead_after_days;

  // Every id a person might hold: the phone-derived `@c.us`, whatever id we
  // stored at enrol time, and any `@lid` twin WhatsApp mapped to either.
  const idsOf = new Map();
  const allPn = new Set();
  for (const lead of leads) {
    const ids = new Set();
    const phoneChat = chatIdForPhone(lead.normalized_phone || lead.phone);
    if (phoneChat) ids.add(phoneChat);
    if (lead.chat_id) ids.add(lead.chat_id);
    idsOf.set(lead.id, ids);
    for (const i of ids) if (String(i).endsWith('@c.us')) allPn.add(i);
  }

  // One pass over the lid map for every phone id, rather than one per person.
  const lidByPn = new Map();
  const pnList = [...allPn];
  for (let i = 0; i < pnList.length; i += CHUNK) {
    const c = pnList.slice(i, i + CHUNK);
    const r = (await api.db.prepare(
      `SELECT pn, lid FROM wa_lid_map WHERE pn IN (${c.map(() => '?').join(',')})`,
    ).bind(...c).all().catch(() => ({ results: [] }))).results || [];
    for (const row of r) {
      if (!row.lid) continue;
      if (!lidByPn.has(row.pn)) lidByPn.set(row.pn, []);
      lidByPn.get(row.pn).push(row.lid);
    }
  }
  for (const ids of idsOf.values()) {
    for (const pn of [...ids].filter((i) => String(i).endsWith('@c.us'))) {
      for (const lid of lidByPn.get(pn) || []) ids.add(lid);
    }
  }

  const everyId = [...new Set([...idsOf.values()].flatMap((s) => [...s]))];
  const [lasts, marks] = await Promise.all([
    lastMessages(api, everyId).catch(() => new Map()),
    deadMarks(api, leads.map((l) => l.id)).catch(() => new Map()),
  ]);

  const deadBefore = now() - deadAfterDays * 86400000;
  for (const lead of leads) {
    const ids = [...(idsOf.get(lead.id) || [])];
    // Merge every id the person holds. A reply that landed on the privacy twin
    // still means answered even when the newest message sits on the other id.
    let msgsIn = 0, msgsOut = 0, lastAt = null, lastText = null, lastFromMe = null;
    for (const id of ids) {
      const m = lasts.get(id);
      if (!m) continue;
      msgsIn += m.in_n || 0;
      msgsOut += m.out_n || 0;
      const at = waMs(m.timestamp);
      if (at && (!lastAt || at > lastAt)) { lastAt = at; lastText = m.body || null; lastFromMe = Number(m.from_me) === 1; }
    }
    const answered = msgsIn > 0;
    const neverMessaged = msgsIn === 0 && msgsOut === 0;
    const deadMarked = marks.has(lead.id);
    const status = (deadMarked || (lastAt && lastAt < deadBefore)) ? 'dead'
      : answered ? 'active'
      : neverMessaged ? 'untouched'
      : 'touched';
    out.set(lead.id, {
      chat_ids: ids,
      status,
      answered,
      never_messaged: neverMessaged,
      last_at: lastAt,
      last_text: lastText,
      last_from_me: lastFromMe,
      msgs_in: msgsIn,
      msgs_out: msgsOut,
      dead_marked: deadMarked,
      dead_reason: marks.get(lead.id)?.dead_reason || null,
      dead_by: deadMarked ? 'marked' : (status === 'dead' ? 'stale' : null),
    });
  }
  return out;
}

// ════════════════════════════════════════════════════════════════════════════
// Duplicated: drafting rules + writer model (from lib/outreach-wa.js and
// lib/model-config.js) — only the reads generateStepCopy needs.
// ════════════════════════════════════════════════════════════════════════════

const DRAFT_RULES_SLUG = 'plugin-gtm-outreach-reply-drafting';
const DRAFT_RULES_DEFAULT = `How to write the suggested reply to a prospect on WhatsApp:

- One message, not a sequence. Short — two or three sentences, the length a
  busy person actually reads on a phone.
- Answer what they actually said FIRST. Never restate the pitch at someone who
  has already replied to it.
- Keep the angle's positioning, drop the angle's phrasing. The saved angle is
  what we believe about them; it is not a script to paste at them.
- Plain human words. No em dashes, no "I hope this finds you well", no
  "circling back", no exclamation marks, no emoji unless they used one first.
- Match their language. If they wrote in Hebrew, reply in Hebrew.
- Never invent a fact — no names, numbers, dates, mutual contacts, or claims
  about their company that are not in the context you were given.
- If they declined, do not push. Acknowledge it, leave the door open in one
  short line, and stop.
- End with at most one question, and only when a question actually moves it
  forward.`;

// Read the rules. Never throws. (Seeding the doc on first read belongs to the
// WA lib, which owns the doc; here an absent doc simply means the defaults.)
async function loadDraftingRules(api) {
  try {
    const doc = await api.knowledge(DRAFT_RULES_SLUG);
    if (!doc) return { rules: DRAFT_RULES_DEFAULT, source: 'defaults' };
    const body = String(doc.body || '');
    const idx = body.indexOf('\n---\n');
    const rules = (idx >= 0 ? body.slice(idx + 5) : body).trim() || DRAFT_RULES_DEFAULT;
    return { rules, source: 'doc' };
  } catch {
    return { rules: DRAFT_RULES_DEFAULT, source: 'defaults' };
  }
}

// The heavy-writer model id from the host's `llm-models` doc (declared host
// knowledge read). Doc value > coded default; never throws.
const WRITER_MODEL_DEFAULT = 'claude-opus-4-8';
async function writerModel(api) {
  try {
    const doc = await api.knowledge('llm-models');
    const m = String(doc?.body || '').match(/```json\s*([\s\S]*?)```/);
    const src = m ? JSON.parse(m[1]) : {};
    const s = String(src?.writer ?? '').trim();
    // model ids are short tokens — refuse anything that looks like prose
    return (s && s.length <= 120 && !/\s{2,}|\n/.test(s)) ? s : WRITER_MODEL_DEFAULT;
  } catch { return WRITER_MODEL_DEFAULT; }
}

// ════════════════════════════════════════════════════════════════════════════
// The cohort engine itself (the file's real exports).
// ════════════════════════════════════════════════════════════════════════════

// ── named cohorts ──────────────────────────────────────────────────────────
// A cohort owns three things: who is in it, the copy they all receive, and its
// own run state + sending window. Status gates the sender, so pausing one stops
// every message inside it without disturbing anyone's place in the sequence.
export async function listCohorts(api) {
  const rows = ((await api.db.prepare(
    'SELECT * FROM plugin_gtm_outreach_cohorts ORDER BY created_at ASC',
  ).all().catch(() => ({ results: [] }))).results) || [];
  const counts = ((await api.db.prepare(
    `SELECT COALESCE(cohort_id, ?) AS cohort_id,
            COUNT(*) AS total,
            SUM(CASE WHEN status = 'active' THEN 1 ELSE 0 END) AS active,
            SUM(CASE WHEN answered_at IS NOT NULL THEN 1 ELSE 0 END) AS answered
       FROM plugin_gtm_outreach_cohort_members GROUP BY COALESCE(cohort_id, ?)`,
  ).bind(DEFAULT_COHORT, DEFAULT_COHORT).all().catch(() => ({ results: [] }))).results) || [];
  const byId = new Map(counts.map((c) => [c.cohort_id, c]));
  return {
    cohorts: rows.map((r) => ({
      id: r.id, name: r.name, note: r.note || null, created_at: r.created_at,
      status: r.status || 'active',
      timezone: r.timezone || null,
      start_hour: r.start_hour ?? null,
      end_hour: r.end_hour ?? null,
      send_days: (() => { try { return r.send_days ? JSON.parse(r.send_days) : null; } catch { return null; } })(),
      // Per-weekday eligible sending times, {weekday: {start,end}}. NULL means
      // the cohort inherits the account default window.
      send_windows: (() => { const w = parseWindows(r.send_windows); return w ? Object.fromEntries(Object.entries(w).map(([d, x]) => [d, { start: x.start, end: x.end }])) : null; })(),
      languages: (() => { try { return r.languages ? JSON.parse(r.languages) : null; } catch { return null; } })(),
      has_sequence: !!String(r.sequence || '').trim() && parseSequence(r.sequence).steps.length > 0,
      total: byId.get(r.id)?.total || 0,
      active: byId.get(r.id)?.active || 0,
      answered: byId.get(r.id)?.answered || 0,
    })),
  };
}

export async function createCohort(api, { name, note = null } = {}) {
  const clean = String(name || '').trim();
  if (!clean) return { error: 'a cohort name is required' };
  if (clean.length > 80) return { error: 'cohort name is too long (80 characters max)' };
  const existing = await api.db.prepare('SELECT * FROM plugin_gtm_outreach_cohorts WHERE name = ?').bind(clean).first().catch(() => null);
  // Idempotent by name: re-creating an existing cohort hands back that one
  // rather than failing the caller or minting a confusing duplicate.
  if (existing) return { cohort: { id: existing.id, name: existing.name }, created: false };
  const id = qid();
  const t = now();
  await api.db.prepare(
    'INSERT INTO plugin_gtm_outreach_cohorts (id, name, note, created_at, updated_at) VALUES (?, ?, ?, ?, ?)',
  ).bind(id, clean, note || null, t, t).run();
  await api.log('outreach_cohort_created', { id, name: clean });
  return { cohort: { id, name: clean }, created: true };
}

// A cohort's run state and its own sending window. Status is not decoration:
// the sender skips any cohort that is not `active`.
export const COHORT_STATUSES = ['active', 'paused', 'finished', 'canceled'];

export async function updateCohort(api, patch = {}) {
  const { cohort_id } = patch;
  if (!cohort_id) return { error: 'cohort_id required' };
  const row = await api.db.prepare('SELECT * FROM plugin_gtm_outreach_cohorts WHERE id = ?').bind(cohort_id).first().catch(() => null);
  if (!row) return { error: 'no such cohort' };

  const set = {};
  if (patch.name !== undefined) {
    const clean = String(patch.name || '').trim();
    if (!clean) return { error: 'a cohort name is required' };
    set.name = clean;
  }
  if (patch.status !== undefined) {
    if (!COHORT_STATUSES.includes(patch.status)) return { error: `status must be one of ${COHORT_STATUSES.join(', ')}` };
    set.status = patch.status;
  }
  if (patch.timezone !== undefined) {
    const tz = String(patch.timezone || '').trim();
    // A zone the runtime cannot resolve would silently push every send to a
    // wrong hour, so refuse it here rather than at 3am in someone's morning.
    if (tz) { try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); } catch { return { error: `unknown timezone "${tz}"` }; } }
    set.timezone = tz || null;
  }
  if (patch.send_days !== undefined) {
    const days = Array.isArray(patch.send_days)
      ? [...new Set(patch.send_days.map(Number).filter((d) => Number.isInteger(d) && d >= 0 && d <= 6))].sort()
      : [];
    // An empty list means "never" — store NULL (inherit) instead of freezing
    // the cohort in a state whose only symptom is nothing ever sending.
    set.send_days = days.length ? JSON.stringify(days) : null;
  }
  if (patch.languages !== undefined) {
    const langs = Array.isArray(patch.languages)
      ? [...new Set(patch.languages.map((l) => String(l || '').trim().toLowerCase()).filter(Boolean))]
      : [];
    set.languages = langs.length ? JSON.stringify(langs) : null;
  }
  if (patch.send_windows !== undefined) {
    // Validate through the same parser the engine reads with, so anything the
    // engine would silently ignore is refused here where it can be seen.
    const win = parseWindows(patch.send_windows);
    if (patch.send_windows && !win && Object.keys(patch.send_windows || {}).length) {
      return { error: 'sending times must be HH:MM with the end after the start' };
    }
    set.send_windows = win
      ? JSON.stringify(Object.fromEntries(Object.entries(win).map(([d, w]) => [d, { start: w.start, end: w.end }])))
      : null;
  }
  if (patch.start_hour !== undefined || patch.end_hour !== undefined) {
    const s = patch.start_hour === undefined ? row.start_hour : Number(patch.start_hour);
    const e = patch.end_hour === undefined ? row.end_hour : Number(patch.end_hour);
    if (s != null && e != null) {
      if (!Number.isFinite(s) || !Number.isFinite(e) || s < 0 || e > 24 || e <= s) {
        return { error: 'sending hours must be 0–24 with the end after the start' };
      }
      set.start_hour = Math.floor(s);
      set.end_hour = Math.floor(e);
    }
  }
  if (!Object.keys(set).length) return { error: 'nothing to change' };

  const keys = Object.keys(set);
  await api.db.prepare(
    `UPDATE plugin_gtm_outreach_cohorts SET ${keys.map((k) => `${k}=?`).join(', ')}, updated_at=? WHERE id=?`,
  ).bind(...keys.map((k) => set[k]), now(), cohort_id).run();
  await api.log('outreach_cohort_updated', { cohort_id, ...set });
  return { ok: true, cohort_id, ...set };
}

export async function deleteCohort(api, { cohort_id } = {}) {
  if (!cohort_id) return { error: 'cohort_id required' };
  if (cohort_id === DEFAULT_COHORT) return { error: 'the default cohort cannot be deleted' };
  const n = Number((await api.db.prepare(
    'SELECT COUNT(*) AS n FROM plugin_gtm_outreach_cohort_members WHERE cohort_id = ?',
  ).bind(cohort_id).first().catch(() => null))?.n || 0);
  if (n) return { error: `${n} prospect${n === 1 ? ' is' : 's are'} still in this cohort — remove them first` };
  await api.db.prepare('DELETE FROM plugin_gtm_outreach_cohorts WHERE id = ?').bind(cohort_id).run().catch(() => {});
  await api.log('outreach_cohort_deleted', { cohort_id });
  return { deleted: true, cohort_id };
}

async function cohortName(api, id) {
  if (!id) return null;
  const r = await api.db.prepare('SELECT name FROM plugin_gtm_outreach_cohorts WHERE id = ?').bind(id).first().catch(() => null);
  return r?.name || null;
}

// LIVE by default: an approved, scheduled message is an instruction to send.
// The flag stays as an explicit pause (set outreach.live false to hold the
// queue). Per-message approval, pacing and the no-duplicate claim are what
// actually prevent a mistake, and they are untouched.
// (feature_flags is a HOST table, SELECT-only, declared in requires.host_reads.)
async function isLive(api) {
  try {
    const r = await api.db.prepare('SELECT value FROM feature_flags WHERE key = ?').bind(LIVE_FLAG).first();
    // Same truth table as the host's flagsAsObject: a flag is true only when
    // value === 1; an absent row means "live" (the flag is an explicit pause).
    return !(r && Number(r.value) !== 1);
  } catch { return false; }
}

const chatIdOf = (lead) => {
  const digits = String(lead?.normalized_phone || lead?.phone || '').replace(/\D/g, '');
  return digits ? `${digits}@c.us` : null;
};

// One lead row (own plugin_gtm_leads table — was lib/gtm.js getLead).
async function getLead(api, id) {
  return api.db.prepare('SELECT * FROM plugin_gtm_leads WHERE id = ?').bind(id).first();
}

// The cohort's own message sequence, and what it renders to for one prospect.
export async function cohortRow(api, cohortId) {
  return api.db.prepare('SELECT * FROM plugin_gtm_outreach_cohorts WHERE id = ?')
    .bind(cohortId || DEFAULT_COHORT).first().catch(() => null);
}

async function sequenceOf(api, cohortId) {
  const r = await api.db.prepare('SELECT sequence FROM plugin_gtm_outreach_cohorts WHERE id = ?')
    .bind(cohortId || DEFAULT_COHORT).first().catch(() => null);
  return parseSequence(r?.sequence);
}

// `scope` decides what a bulk edit does to the people ALREADY in the cohort:
//
//   'new_only' (default) — anyone who was hand-edited keeps their own message.
//   'everyone'           — the cohort's copy replaces the hand-written ones too.
//
// APPROVALS ARE WITHDRAWN EITHER WAY, for every member whose next message this
// changes. Approval means "I have read this text"; leaving one standing after
// the text underneath it changed would send words nobody signed off.
export const SEQUENCE_SCOPES = ['new_only', 'everyone'];

export async function saveSequence(api, { cohort_id, sequence, scope = 'new_only' } = {}) {
  if (!cohort_id) return { error: 'cohort_id required' };
  if (!SEQUENCE_SCOPES.includes(scope)) return { error: `scope must be one of ${SEQUENCE_SCOPES.join(', ')}` };
  const exists = await api.db.prepare('SELECT 1 FROM plugin_gtm_outreach_cohorts WHERE id = ?').bind(cohort_id).first().catch(() => null);
  if (!exists) return { error: 'no such cohort' };
  const check = validateSequence(sequence);
  if (check.unknown_variables.length) {
    return { error: `unknown variable${check.unknown_variables.length > 1 ? 's' : ''}: ${check.unknown_variables.map((v) => `{${v}}`).join(', ')}` };
  }
  const t = now();
  await api.db.prepare('UPDATE plugin_gtm_outreach_cohorts SET sequence = ?, updated_at = ? WHERE id = ?')
    .bind(serializeSequence(sequence), t, cohort_id).run();

  // Whose hand-written message just got overwritten — counted BEFORE the write,
  // so the caller can tell the operator what it cost rather than guessing.
  const editedCount = Number((await api.db.prepare(
    `SELECT COUNT(*) AS n FROM plugin_gtm_outreach_cohort_members
      WHERE COALESCE(cohort_id, ?) = ? AND override_text IS NOT NULL`,
  ).bind(DEFAULT_COHORT, cohort_id).first().catch(() => null))?.n || 0);

  let replaced = 0;
  if (scope === 'everyone' && editedCount) {
    await api.db.prepare(
      `UPDATE plugin_gtm_outreach_cohort_members
          SET override_text = NULL, override_step = NULL, updated_at = ?
        WHERE COALESCE(cohort_id, ?) = ? AND override_text IS NOT NULL`,
    ).bind(t, DEFAULT_COHORT, cohort_id).run();
    replaced = editedCount;
  }

  // Re-arm the gate. On 'new_only' the hand-edited members keep their approval,
  // because the text THEY are getting has not changed.
  const keepEdited = scope === 'new_only' ? ' AND override_text IS NULL' : '';
  const unapproved = Number((await api.db.prepare(
    `SELECT COUNT(*) AS n FROM plugin_gtm_outreach_cohort_members
      WHERE COALESCE(cohort_id, ?) = ? AND approved_step IS NOT NULL${keepEdited}`,
  ).bind(DEFAULT_COHORT, cohort_id).first().catch(() => null))?.n || 0);
  await api.db.prepare(
    `UPDATE plugin_gtm_outreach_cohort_members
        SET approved_step = NULL, approved_step_at = NULL, updated_at = ?
      WHERE COALESCE(cohort_id, ?) = ? AND approved_step IS NOT NULL${keepEdited}`,
  ).bind(t, DEFAULT_COHORT, cohort_id).run();

  await api.log('outreach_sequence_saved', { cohort_id, scope, edits_replaced: replaced, approvals_withdrawn: unapproved, ...check });
  return { ok: true, cohort_id, scope, edits_replaced: replaced, approvals_withdrawn: unapproved, edits_kept: scope === 'new_only' ? editedCount : 0, ...check };
}

// ── draft one step's copy ───────────────────────────────────────────────────
// The editor's "generate" button. It never saves and never sends — the copy
// only becomes real when the operator presses save, which is what keeps "every
// automated message was approved" true even when a model helped write it.
export async function generateStepCopy(api, { cohort_id, step_index = 0, language = 'en', instruction = '' } = {}) {
  if (!cohort_id) return { error: 'cohort_id required' };
  const coh = await cohortRow(api, cohort_id);
  if (!coh) return { error: 'no such cohort' };

  // The brief is the cohort itself: its name, and a sample of who is in it.
  const sample = ((await api.db.prepare(
    `SELECT l.name, l.company, l.position, l.country
       FROM plugin_gtm_outreach_cohort_members m JOIN plugin_gtm_leads l ON l.id = m.lead_id
      WHERE COALESCE(m.cohort_id, ?) = ? LIMIT 8`,
  ).bind(DEFAULT_COHORT, cohort_id).all().catch(() => ({ results: [] }))).results) || [];

  const seq = await sequenceOf(api, cohort_id);
  const earlier = seq.steps.slice(0, step_index)
    .map((s, i) => `${i + 1}. ${Object.values(s.bodies)[0] || ''}`).filter(Boolean).join('\n');

  const { rules } = await loadDraftingRules(api);
  const model = await writerModel(api);

  const system = `You write one outreach message for a COHORT — a group of prospects who share a reason to be approached. The same text goes to everyone in the group, personalised only by variables.

Use ONLY these variables, in curly braces, and only where they genuinely help: ${VARIABLE_NAMES.map((v) => `{${v}}`).join(' ')}. Never invent a variable. Never write a name or company literally — use the variable.

${rules}

Return ONLY the message text. No preamble, no quotes, no alternatives.`;

  const who = sample.length
    ? sample.map((p) => `- ${[p.position, p.company, p.country].filter(Boolean).join(', ')}`).join('\n')
    : '(nobody added yet — write for the cohort name alone)';
  const prompt = [
    `COHORT: ${coh.name}`,
    `WHO IS IN IT:\n${who}`,
    earlier ? `MESSAGES ALREADY IN THE SEQUENCE (do not repeat them):\n${earlier}` : '',
    step_index === 0
      ? 'Write the FIRST message — a cold opener to someone who has never heard from us.'
      : `Write message ${step_index + 1} — a follow-up to someone who has NOT replied to the earlier ones. Do not thank them for a reply, and do not imply they responded.`,
    language !== 'en' ? `Write it in ${language === 'he' ? 'Hebrew' : language}.` : '',
    instruction ? `EXTRA DIRECTION FROM THE OPERATOR: ${instruction}` : '',
  ].filter(Boolean).join('\n\n');

  let text;
  try {
    text = await api.gateway('llm', 'text', { system, prompt, model, max_tokens: 400, heavy: false });
  } catch (e) {
    return { error: `could not draft it (${String(e?.message || e)})` };
  }
  const draft = String(text || '').trim().replace(/^["']|["']$/g, '').trim();
  if (!draft) return { error: 'the model returned nothing' };

  await api.log('outreach_step_drafted', { cohort_id, step_index, language, chars: draft.length });
  return { draft, cohort_id, step_index, language, based_on: sample.length };
}

export async function readSequence(api, { cohort_id } = {}) {
  const seq = await sequenceOf(api, cohort_id);
  return { cohort_id: cohort_id || DEFAULT_COHORT, sequence: seq, ...validateSequence(seq) };
}

// Gap before the step at `index`. Step 0 goes as soon as it is approved; the
// spacing of later steps is the cohort's, authored alongside the copy.
function delayForStep(seq, index) {
  const s = seq.steps[index];
  return Math.max(0, Number(s?.delay_hours || 0)) * 3600000;
}

async function readRow(api, leadId) {
  return api.db.prepare('SELECT * FROM plugin_gtm_outreach_cohort_members WHERE lead_id = ?').bind(leadId).first().catch(() => null);
}

async function writeRow(api, leadId, patch) {
  const fields = { ...patch, updated_at: now() };
  const keys = Object.keys(fields);
  await api.db.prepare(
    `UPDATE plugin_gtm_outreach_cohort_members SET ${keys.map((k) => `${k}=?`).join(', ')} WHERE lead_id=?`,
  ).bind(...keys.map((k) => fields[k]), leadId).run().catch(() => {});
}

// ── enrol ───────────────────────────────────────────────────────────────────
// Put a prospect on the cohort. Idempotent: re-enrolling someone already on it
// returns the existing row rather than restarting their ladder. A prospect who
// has already replied is refused.
export async function enroll(api, { lead_id, cohort_id = null, override = false, start_at = null } = {}) {
  if (!lead_id) return { error: 'lead_id required' };
  const lead = await getLead(api, lead_id).catch(() => null);
  if (!lead) return { error: 'no such lead' };
  const target = cohort_id || DEFAULT_COHORT;

  const existing = await readRow(api, lead_id);
  if (existing) {
    const current = existing.cohort_id || DEFAULT_COHORT;
    if (current === target) return { added: false, reason: 'already in this cohort', lead_id, cohort_id: current };
    // ── THE ANTI-SPAM RULE ── they are already being worked in another cohort.
    // Refuse and hand the decision to a human rather than quietly messaging the
    // same person from two campaigns.
    if (!override) {
      return {
        conflict: true, lead_id, name: lead.name || null,
        current_cohort: { id: current, name: await cohortName(api, current) },
        requested_cohort: { id: target, name: await cohortName(api, target) },
        message: `${lead.name || 'This prospect'} is already in "${await cohortName(api, current) || current}". Adding them here would mean two campaigns messaging the same person.`,
      };
    }
    // Overridden: MOVE them. Never a second row.
    await writeRow(api, lead_id, { cohort_id: target });
    await api.log('outreach_cohort_override', { lead_id, name: lead.name || null, from: current, to: target });
    return { added: true, moved: true, lead_id, cohort_id: target, from_cohort: current };
  }

  const chatId = chatIdOf(lead);
  if (!chatId) return { error: 'lead has no usable phone number' };

  const facts = await threadFacts(api, { chat_id: chatId, lead, limit: 50 });
  if (facts.answered) {
    return { error: 'this prospect has already replied — they belong in Conversations, not the cohort' };
  }

  // STAGED, not scheduled. Adding somebody to a cohort is a filing decision;
  // it must never be the thing that causes a message. The sender only ever
  // selects status='active', so a staged row is invisible to it by
  // construction rather than by a check that could regress.
  const t = now();
  await api.db.prepare(
    `INSERT INTO plugin_gtm_outreach_cohort_members (lead_id, chat_id, cohort_id, status, step, next_send_at, last_sent_at, enrolled_at, updated_at)
     VALUES (?, ?, ?, 'staged', 0, NULL, ?, ?, ?)`,
  ).bind(lead_id, chatId, target, facts.last_out_at ?? null, t, t).run();

  await api.log('outreach_cohort_staged', { lead_id, name: lead.name || null, cohort_id: target });
  return { added: true, staged: true, lead_id, cohort_id: target };
}

// ── go live ─────────────────────────────────────────────────────────────────
// The ONLY thing that turns staged people into scheduled ones. Explicit, per
// selection, and it refuses anyone whose messages would render with a hole in
// them.
export async function goLive(api, { lead_ids = [], start_at = null } = {}) {
  const ids = [...new Set((lead_ids || []).filter(Boolean))];
  if (!ids.length) return { error: 'nobody selected' };
  const { cadence } = await loadCohortCadence(api);
  const seqCache = new Map();
  const cohortCache = new Map();

  const live = [];
  const blocked = [];
  for (const id of ids) {
    const row = await readRow(api, id);
    if (!row) { blocked.push({ lead_id: id, reason: 'not on any cohort' }); continue; }
    if (row.answered_at) { blocked.push({ lead_id: id, reason: 'they have replied — automation is off for them' }); continue; }
    if (row.status === 'active') { blocked.push({ lead_id: id, reason: 'already live' }); continue; }

    const lead = await getLead(api, row.lead_id).catch(() => null);
    if (!lead) { blocked.push({ lead_id: id, reason: 'lead missing' }); continue; }

    const qId = row.cohort_id || DEFAULT_COHORT;
    if (!seqCache.has(qId)) seqCache.set(qId, await sequenceOf(api, qId));
    if (!cohortCache.has(qId)) cohortCache.set(qId, await cohortRow(api, qId));
    const seq = seqCache.get(qId);
    const coh = cohortCache.get(qId);
    // Scheduling uses the COHORT's window, so "9am" means 9am wherever this
    // group actually lives.
    const cad = effectiveCadence(cadence, coh);

    // The whole sequence must render for THIS person before any of it is
    // scheduled — catching it now, not three steps in.
    const rendered = renderSequence(seq, lead);
    if (rendered.blocked) {
      blocked.push({ lead_id: id, name: lead.name || null, reason: rendered.blocked });
      continue;
    }

    const base = start_at || now();
    await writeRow(api, id, {
      status: 'active',
      step: 0,
      approved_at: now(),
      next_send_at: nextWindowOpening(base + delayForStep(seq, 0), cad),
      stop_reason: null,
      last_error: null,
    });
    live.push({ lead_id: id, name: lead.name || null, steps: rendered.length, first_text: rendered.steps[0]?.text || null });
  }

  await api.log('outreach_cohort_go_live', { requested: ids.length, live: live.length, blocked: blocked.length });
  return { live, blocked, requested: ids.length };
}

// ── bulk add (the Prospecting CTA) ──────────────────────────────────────────
// Adds many prospects to one cohort and reports each outcome separately. The
// conflicts come back as their own list so the operator can approve the
// override for exactly those people — never a blanket "force everything".
export async function enrollMany(api, { lead_ids = [], cohort_id = null, override = false } = {}) {
  const ids = [...new Set((lead_ids || []).filter(Boolean))];
  if (!ids.length) return { error: 'no prospects selected' };
  if (ids.length > 200) return { error: 'too many at once — select 200 or fewer' };
  const target = cohort_id || DEFAULT_COHORT;

  const added = [];
  const conflicts = [];
  const skipped = [];
  for (const id of ids) {
    let r;
    try { r = await enroll(api, { lead_id: id, cohort_id: target, override }); }
    catch (e) { r = { error: String(e?.message || e) }; }
    if (r?.conflict) conflicts.push(r);
    else if (r?.added) added.push(r);
    else skipped.push({ lead_id: id, reason: r?.error || r?.reason || 'not enrolled' });
  }

  await api.log('outreach_cohort_bulk_added', { cohort_id: target, requested: ids.length, added: added.length, conflicts: conflicts.length, skipped: skipped.length, override: !!override });
  return {
    cohort_id: target, cohort_name: await cohortName(api, target),
    requested: ids.length, added, conflicts, skipped,
  };
}

export async function remove(api, { lead_id, reason = 'manual' } = {}) {
  if (!lead_id) return { error: 'lead_id required' };
  await api.db.prepare('DELETE FROM plugin_gtm_outreach_cohort_members WHERE lead_id = ?').bind(lead_id).run().catch(() => {});
  await api.log('outreach_cohort_removed', { lead_id, reason });
  return { removed: true, lead_id };
}

// pause / resume / stop a single enrolment. Stopping is terminal-but-visible;
// removing is what clears the row entirely.
export async function control(api, { lead_id, action } = {}) {
  if (!lead_id || !action) return { error: 'lead_id and action required' };
  const row = await readRow(api, lead_id);
  if (!row) return { error: 'not enrolled' };
  if (row.answered_at && action === 'resume') {
    return { error: 'this prospect replied — automation cannot be resumed for them' };
  }
  const { cadence } = await loadCohortCadence(api);
  const patch = action === 'pause' ? { status: 'paused' }
    : action === 'resume' ? { status: 'active', next_send_at: nextWindowOpening(now(), cadence) }
    : action === 'stop' ? { status: 'stopped', stop_reason: 'manual', next_send_at: null }
    // Back to a draft: they keep their place in the ladder and their approval,
    // they simply have no send time any more. The tick only ever selects rows
    // WITH one, so this takes them out of the run without stopping them.
    : action === 'unschedule' ? { status: 'staged', next_send_at: null, stop_reason: null }
    : null;
  if (!patch) return { error: `unknown action "${action}"` };
  await writeRow(api, lead_id, patch);
  await api.log('outreach_cohort_control', { lead_id, action });
  return { lead_id, ...patch };
}

// ── moving ONE person's next send ───────────────────────────────────────────
// The sheet's Sending cell, edited in place. Stores EXACTLY the moment picked —
// it is not snapped into the cohort's window; the tick only runs inside the
// window anyway, so a time outside it simply means "first chance after that".
// `outside_window` is returned so the UI can say so out loud.
//
// Setting a time on someone staged is a go-live, and carries go-live's guard:
// the whole sequence must render for this person before any of it is armed.
export async function rescheduleMember(api, { lead_id, send_at } = {}) {
  const leadId = String(lead_id || '').trim();
  if (!leadId) return { error: 'lead_id required' };
  const at = Number(send_at);
  if (!Number.isFinite(at) || at <= 0) return { error: 'a send time is required' };

  const row = await readRow(api, leadId);
  if (!row) return { error: 'not in a cohort' };
  if (row.answered_at) return { error: 'they replied — automation is off them' };
  if (row.status === 'stopped' || row.status === 'done') {
    return { error: `this prospect is ${row.status} — resume them before scheduling` };
  }

  const lead = await getLead(api, leadId).catch(() => null);
  if (!lead) return { error: 'lead missing' };
  const qId = row.cohort_id || DEFAULT_COHORT;
  const rendered = renderSequence(await sequenceOf(api, qId), lead);
  if (rendered.blocked) return { error: rendered.blocked };

  const { cadence } = await loadCohortCadence(api);
  const coh = await cohortRow(api, qId);
  const cad = effectiveCadence(cadence, coh);
  const tz = coh?.timezone || cadence.timezone;

  // A time that has already passed is not an error — it means "as soon as the
  // sender next runs", which is a thing operators legitimately want.
  await writeRow(api, leadId, {
    status: 'active',
    next_send_at: at,
    stop_reason: null,
    // Rescheduling is not re-approving. Moving WHEN it goes does not change
    // WHAT goes, so the approval stands; the text is untouched.
  });
  await api.log('outreach_member_rescheduled', { lead_id: leadId, send_at: at, was: row.next_send_at || null, from_staged: row.status === 'staged' });
  return {
    lead_id: leadId,
    next_send_at: at,
    went_live: row.status === 'staged',
    outside_window: !withinWindow(at, cad),
    ...zonedLabel(at, tz),
  };
}

// ── approving one message for one person ────────────────────────────────────
// Approval is stored as the STEP INDEX approved, never as a boolean. Sending
// advances `step`, so the stored index stops matching by itself and the next
// message is un-approved by construction.
//
// Approving does not schedule and does not send. The two gates are separate on
// purpose: one is about the person, the other about the words.
export async function approveMessages(api, { lead_ids = [], approve = true } = {}) {
  const ids = [...new Set((lead_ids || []).map((s) => String(s || '').trim()).filter(Boolean))];
  if (!ids.length) return { error: 'select at least one prospect' };

  const approved = [];
  const refused = [];
  const t = now();

  // Withdrawing needs none of the checks below — it can only ever make the
  // system quieter, so it is safe to do first and in bulk.
  if (!approve) {
    for (const leadId of ids) {
      const r = await api.db.prepare(
        'UPDATE plugin_gtm_outreach_cohort_members SET approved_step = NULL, approved_step_at = NULL, updated_at = ? WHERE lead_id = ?',
      ).bind(t, leadId).run().catch(() => null);
      if (r) approved.push({ lead_id: leadId, approved: false });
    }
    await api.log('outreach_message_unapproved', { count: approved.length, lead_ids: ids });
    return { approved, refused };
  }

  const rows = new Map();
  const leadsById = new Map();
  for (const leadId of ids) {
    const row = await api.db.prepare('SELECT * FROM plugin_gtm_outreach_cohort_members WHERE lead_id = ?').bind(leadId).first().catch(() => null);
    if (!row) { refused.push({ lead_id: leadId, reason: 'not in a cohort' }); continue; }
    const lead = await getLead(api, leadId).catch(() => null);
    if (!lead) { refused.push({ lead_id: leadId, reason: 'lead missing' }); continue; }
    rows.set(leadId, row);
    leadsById.set(leadId, lead);
  }

  // ── read the CONVERSATION, not the stored flag ──
  // `answered_at` is only written when the tick next runs, so a prospect who
  // replied five minutes ago still has it NULL. Trusting it would let the
  // operator approve a message for somebody already mid-conversation — the one
  // thing this module must never do.
  const convo = await conversationStatesFor(api, [...rows.values()].map((row) => ({
    id: row.lead_id,
    chat_id: row.chat_id,
    normalized_phone: leadsById.get(row.lead_id)?.normalized_phone || null,
    phone: leadsById.get(row.lead_id)?.phone || null,
  }))).catch(() => new Map());

  for (const leadId of [...rows.keys()]) {
    const row = rows.get(leadId);
    const lead = leadsById.get(leadId);
    if (row.answered_at || convo.get(leadId)?.answered) {
      refused.push({ lead_id: leadId, name: lead.name || null, reason: 'they replied — automation is off them' });
      continue;
    }

    // Approve exactly the message the sheet showed. For a staged person that is
    // the opener; for a live one it is whatever step they are on.
    // NOT `staged ? 0` — an unscheduled member keeps their place in the ladder.
    const step = row.step;

    // Re-render before approving rather than trusting the row the browser was
    // looking at: the cohort's copy or the prospect's fields may have changed
    // since it loaded.
    const rendered = renderSequence(await sequenceOf(api, row.cohort_id), lead);
    if (rendered.blocked) { refused.push({ lead_id: leadId, name: lead.name || null, reason: rendered.blocked }); continue; }
    if (!rendered.steps[step]) { refused.push({ lead_id: leadId, name: lead.name || null, reason: 'no message at this step' }); continue; }
    if (row.override_text && row.override_step === step) {
      const o = renderBody(row.override_text, lead);
      if (o.missing.length || o.unknown.length) {
        refused.push({ lead_id: leadId, name: lead.name || null, reason: `edited message has unfilled ${[...o.missing, ...o.unknown].join(', ')}` });
        continue;
      }
    }

    await api.db.prepare(
      'UPDATE plugin_gtm_outreach_cohort_members SET approved_step = ?, approved_step_at = ?, updated_at = ? WHERE lead_id = ?',
    ).bind(step, t, t, leadId).run();
    approved.push({ lead_id: leadId, name: lead.name || null, step, approved: true });
  }

  await api.log(
    approve ? 'outreach_message_approved' : 'outreach_message_unapproved',
    { count: approved.length, refused: refused.length, lead_ids: approved.map((a) => a.lead_id) },
  );
  return { approved, refused };
}

// ── editing one message for one person ──────────────────────────────────────
// The edit belongs to this prospect at this step, NOT to the cohort. Saving an
// edit CLEARS any approval — approval means "I have read this text", and the
// text just changed.
export async function saveMessageOverride(api, { lead_id, text, clear = false } = {}) {
  const leadId = String(lead_id || '').trim();
  if (!leadId) return { error: 'lead_id required' };
  const row = await api.db.prepare('SELECT * FROM plugin_gtm_outreach_cohort_members WHERE lead_id = ?').bind(leadId).first().catch(() => null);
  if (!row) return { error: 'not in a cohort' };
  // NOT `staged ? 0` — an unscheduled member keeps their place in the ladder.
  const step = row.step;
  const t = now();

  if (clear || !String(text || '').trim()) {
    await api.db.prepare(
      `UPDATE plugin_gtm_outreach_cohort_members
          SET override_text = NULL, override_step = NULL,
              approved_step = NULL, approved_step_at = NULL, updated_at = ?
        WHERE lead_id = ?`,
    ).bind(t, leadId).run();
    await api.log('outreach_message_edit_cleared', { lead_id: leadId, step });
    return { lead_id: leadId, step, cleared: true };
  }

  const body = String(text).trim();
  const { cadence } = await loadCohortCadence(api);
  if (body.length > cadence.max_message_chars) {
    return { error: `message is too long (${cadence.max_message_chars} characters max)` };
  }
  const lead = await getLead(api, leadId).catch(() => null);
  if (!lead) return { error: 'lead missing' };
  // Refuse a broken edit at the point of saving, where the operator is looking
  // at it, rather than accepting it and failing silently at send time.
  const r = renderBody(body, lead);
  if (r.unknown.length) return { error: `unknown variable${r.unknown.length > 1 ? 's' : ''}: ${r.unknown.map((u) => `{${u}}`).join(', ')}` };
  if (r.missing.length) return { error: `this prospect has no ${r.missing.map((m) => m.replace(/_/g, ' ')).join(', ')}` };

  await api.db.prepare(
    `UPDATE plugin_gtm_outreach_cohort_members
        SET override_text = ?, override_step = ?,
            approved_step = NULL, approved_step_at = NULL, updated_at = ?
      WHERE lead_id = ?`,
  ).bind(body, step, t, leadId).run();
  await api.log('outreach_message_edited', { lead_id: leadId, step, chars: body.length });
  return { lead_id: leadId, step, text: r.text, approved_cleared: true };
}

// ── read the cohort ─────────────────────────────────────────────────────────
// One row per enrolled prospect with what actually matters: what we last said,
// what goes next and when, and whether they have answered.
export async function listCohortMembers(api, { status = null, cohort_id = null } = {}) {
  const where = [];
  const binds = [];
  if (status && status !== 'all') { where.push('status = ?'); binds.push(status); }
  if (cohort_id && cohort_id !== 'all') { where.push('COALESCE(cohort_id, ?) = ?'); binds.push(DEFAULT_COHORT, cohort_id); }
  const rows = ((await api.db.prepare(
    `SELECT * FROM plugin_gtm_outreach_cohort_members ${where.length ? 'WHERE ' + where.join(' AND ') : ''}
      ORDER BY (next_send_at IS NULL), next_send_at ASC`,
  ).bind(...binds).all().catch(() => ({ results: [] }))).results) || [];
  const { cohorts } = await listCohorts(api);
  const nameOf = new Map(cohorts.map((qq) => [qq.id, qq.name]));
  if (!rows.length) {
    return { members: [], cohorts, counts: { active: 0, answered: 0, paused: 0, done: 0, stopped: 0 }, live: await isLive(api) };
  }

  // Lead details in one chunked read rather than one query per row.
  const leadIds = rows.map((r) => r.lead_id);
  const leads = new Map();
  for (let i = 0; i < leadIds.length; i += CHUNK) {
    const c = leadIds.slice(i, i + CHUNK);
    // country + outreach_lang are NOT optional here: they decide which language
    // variant a prospect gets.
    const r = (await api.db.prepare(
      `SELECT id, name, company, position, photo, icp_fit, normalized_phone, phone, country, outreach_lang
         FROM plugin_gtm_leads WHERE id IN (${c.map(() => '?').join(',')})`,
    ).bind(...c).all().catch(() => ({ results: [] }))).results || [];
    for (const l of r) leads.set(l.id, l);
  }

  // Where each prospect's actual WhatsApp conversation stands, for every member
  // in one chunked pass. Same derivation the Conversations tab uses.
  const convo = await conversationStatesFor(
    api,
    rows.map((r) => ({
      id: r.lead_id,
      chat_id: r.chat_id,
      normalized_phone: leads.get(r.lead_id)?.normalized_phone || null,
      phone: leads.get(r.lead_id)?.phone || null,
    })),
  ).catch(() => new Map());

  const { cadence } = await loadCohortCadence(api);
  const cohortById = new Map(cohorts.map((c) => [c.id, c]));

  const seqCache = new Map();
  const members = [];
  for (const row of rows) {
    const lead = leads.get(row.lead_id) || null;
    const qId = row.cohort_id || DEFAULT_COHORT;
    if (!seqCache.has(qId)) seqCache.set(qId, await sequenceOf(api, qId));
    // Rendered for THIS person, so the row shows the message they would
    // actually receive — variables filled, in their language — not a template.
    const rendered = lead ? renderSequence(seqCache.get(qId), lead) : { steps: [], length: 0, blocked: 'lead missing' };
    const ladder = rendered.steps.map((s) => s.text);
    const shownStep = row.step;
    // A per-person edit replaces the cohort's copy for THAT step only, and is
    // rendered through the same substitution so it cannot ship a raw {token}.
    const override = (row.override_text && row.override_step === shownStep && lead)
      ? renderBody(row.override_text, lead)
      : null;
    // Both a live and a staged member are 'about to get' their current step;
    // only a paused/stopped/finished one has nothing pending.
    const baseText = (row.status === 'active' || row.status === 'staged')
      ? (ladder[row.step] ?? null)
      : null;
    const nextText = baseText === null ? null : (override ? override.text : baseText);

    // The zone the send is actually measured in — the cohort's own if it has
    // one, else the account default.
    const tz = cohortById.get(qId)?.timezone || cadence.timezone;
    const when = row.status === 'active' && row.next_send_at ? zonedLabel(row.next_send_at, tz) : null;

    // Approval is per (person, step): the stored step must equal the step about
    // to go out. After a send moves them forward the match breaks by itself.
    const approved = row.approved_step != null && row.approved_step === shownStep;

    members.push({
      lead_id: row.lead_id,
      chat_id: row.chat_id,
      cohort_id: row.cohort_id || DEFAULT_COHORT,
      cohort_name: nameOf.get(row.cohort_id || DEFAULT_COHORT) || null,
      name: lead?.name || null,
      company: lead?.company || null,
      position: lead?.position || null,
      photo: lead?.photo || null,
      icp_fit: lead?.icp_fit || null,
      status: row.status,
      // Staged = filed into the cohort but NOT scheduled. Only go-live moves
      // someone out of this, and only the operator can do that.
      staged: row.status === 'staged',
      approved_at: row.approved_at || null,
      // Why this person could not go live, if anything. Surfaced up front so
      // the gap is visible before pressing go live, not after. An edit that
      // broke the message counts as blocked too.
      blocked: rendered.blocked
        || (override && (override.missing.length || override.unknown.length)
          ? `edited message has unfilled ${[...override.missing, ...override.unknown].join(', ')}`
          : null),
      answered: !!row.answered_at,
      answered_at: row.answered_at || null,
      step: row.step,
      // How many messages this person has ACTUALLY RECEIVED. `step` is the
      // index of the next one to send, which is the same number — but naming it
      // separately stops the sheet showing 1/3 to someone who has had nothing.
      sent_count: row.step,
      ladder_length: ladder.length,
      last_sent_text: row.last_sent_text || null,
      last_sent_at: row.last_sent_at || null,
      next_text: nextText,
      next_send_at: row.status === 'active' ? row.next_send_at : null,

      // ── the next message, and everything the sheet says about it ──
      // DRAFT = written and waiting, with no send time (nobody has gone live).
      // SCHEDULED = it has a moment it will leave at.
      next_state: row.status === 'staged' ? 'draft'
        : (row.status === 'active' && row.next_send_at) ? 'scheduled'
        : null,
      next_step: nextText === null ? null : shownStep,
      next_send_label: when?.label || null,
      next_send_zone: when?.zone || null,
      next_send_ymd: when?.ymd || null,
      timezone: tz,
      // Scheduled for the cohort's TODAY — the rows the operator has to look at
      // now, which is why they are pinned to the top of their cohort below.
      due_today: !!(when && when.ymd === zonedYmd(now(), tz)),

      // Per-message approval.
      approved: approved,
      approved_step: row.approved_step ?? null,
      // Distinct from `approved_at` above, which is the GO-LIVE stamp: this one
      // is when THIS message was signed off.
      approved_step_at: row.approved_step_at || null,
      // Whether an approval is required at all is a knowledge-doc setting, and
      // the sheet must show the rule that is actually in force.
      approval_required: !!cadence.require_approval,

      // The operator's inline edit of this one message, if any.
      edited: !!override,
      override_text: override ? row.override_text : null,
      // An edit that introduced an unfillable variable must be visible as a
      // problem here, not discovered at send time.
      override_blocked: override && (override.missing.length || override.unknown.length)
        ? `edited message has unfilled ${[...override.missing, ...override.unknown].join(', ')}`
        : null,

      // Where their real conversation stands: untouched | touched | active | dead.
      conversation: convo.get(row.lead_id)?.status || 'untouched',
      conversation_last_at: convo.get(row.lead_id)?.last_at || null,
      dead_by: convo.get(row.lead_id)?.dead_by || null,
      msgs_in: convo.get(row.lead_id)?.msgs_in || 0,
      msgs_out: convo.get(row.lead_id)?.msgs_out || 0,
      // Nothing left to say — the ladder is spent, not the prospect.
      exhausted: row.status === 'active' && row.step >= ladder.length,
      stop_reason: row.stop_reason || null,
      last_error: row.last_error || null,
    });
  }

  // Anything going out TODAY sits at the top of its cohort, because those are
  // the messages the operator still has time to read, approve or edit.
  //
  // Cohort first, THEN rank: a comparator that returned 0 for members of
  // different cohorts would not be transitive, and Array.sort is free to
  // produce nonsense from one.
  const rank = (m) => (m.due_today ? 0 : m.next_send_at ? 1 : m.next_state === 'draft' ? 2 : 3);
  const cohortOrder = new Map(cohorts.map((c, i) => [c.id, i]));
  members.sort((a, b) => {
    const c = (cohortOrder.get(a.cohort_id) ?? 999) - (cohortOrder.get(b.cohort_id) ?? 999);
    if (c) return c;
    const r = rank(a) - rank(b);
    if (r) return r;
    // Within a rank, soonest first; unscheduled rows fall back to a stable name.
    if (a.next_send_at && b.next_send_at) return a.next_send_at - b.next_send_at;
    return String(a.name || '').localeCompare(String(b.name || ''));
  });

  const counts = { staged: 0, active: 0, answered: 0, paused: 0, done: 0, stopped: 0 };
  for (const q of members) if (counts[q.status] !== undefined) counts[q.status]++;
  return { members, cohorts, counts, live: await isLive(api) };
}

// ── the tick ────────────────────────────────────────────────────────────────
// Runs on cron. Walks the due enrolments, re-verifies each one against the
// live conversation, and sends at most what the cadence allows.
export async function runCohortTick(api, { force = false, dry_run = null, limit = null } = {}) {
  const { cadence } = await loadCohortCadence(api);
  const live = await isLive(api);
  // dry_run defaults to "whatever the flag says"; an explicit value wins so a
  // caller can preview without touching the flag.
  const dry = dry_run === null ? !live : !!dry_run;
  const t = now();

  if (!force && !withinWindow(t, cadence)) {
    return { ran: false, reason: 'outside the sending window', dry_run: dry, next_open: nextWindowOpening(t, cadence) };
  }

  // Whole-account daily ceiling — the number that stops a bad enrolment
  // becoming a bulk send. Counts real sends only, so dry runs never eat it.
  const dayAgo = t - 86400000;
  const sentToday = Number((await api.db.prepare(
    'SELECT COUNT(*) AS n FROM plugin_gtm_outreach_cohort_members WHERE last_sent_at IS NOT NULL AND last_sent_at > ?',
  ).bind(dayAgo).first().catch(() => null))?.n || 0);
  const budget = Math.max(0, cadence.max_sends_per_day - sentToday);
  if (!budget && !dry) {
    return { ran: false, reason: `daily cap reached (${cadence.max_sends_per_day})`, dry_run: dry };
  }

  // A member is only due if THEIR cohort is running.
  // APPROVED ROWS SORT FIRST. This query is LIMITed, so ordering by time alone
  // let messages nobody had approved fill the window every tick and permanently
  // mask the approved ones behind them.
  //
  // Ordering rather than EXCLUDING the unapproved, deliberately: an unapproved
  // row still has to be looked at, because the reply check below is what takes
  // someone who answered out of the automation.
  // (SQLite sorts 1 before 0 before NULL under DESC, which is the order wanted.)
  const order = cadence.require_approval
    ? '(m.approved_step = m.step) DESC, m.next_send_at ASC'
    : 'm.next_send_at ASC';
  const due = ((await api.db.prepare(
    `SELECT m.* FROM plugin_gtm_outreach_cohort_members m
       LEFT JOIN plugin_gtm_outreach_cohorts c ON c.id = m.cohort_id
      WHERE m.status = 'active' AND m.next_send_at IS NOT NULL AND m.next_send_at <= ?
        AND COALESCE(c.status, 'active') = 'active'
      ORDER BY ${order} LIMIT ?`,
  ).bind(t, Math.min(limit || 25, 50)).all().catch(() => ({ results: [] }))).results) || [];

  // Counted separately so a tick that sends nothing can say WHY — an invisible
  // backlog reads as "the sender is broken".
  const awaiting = cadence.require_approval ? Number((await api.db.prepare(
    `SELECT COUNT(*) AS n FROM plugin_gtm_outreach_cohort_members m
       LEFT JOIN plugin_gtm_outreach_cohorts c ON c.id = m.cohort_id
      WHERE m.status = 'active' AND m.next_send_at IS NOT NULL AND m.next_send_at <= ?
        AND COALESCE(c.status, 'active') = 'active'
        AND (m.approved_step IS NULL OR m.approved_step <> m.step)`,
  ).bind(t).first().catch(() => null))?.n || 0) : 0;

  const results = [];
  let sent = 0;
  for (const row of due) {
    if (!dry && sent >= budget) { results.push({ lead_id: row.lead_id, action: 'deferred', reason: 'daily cap' }); continue; }
    const lead = await getLead(api, row.lead_id).catch(() => null);
    if (!lead) {
      await writeRow(api, row.lead_id, { status: 'stopped', stop_reason: 'lead missing', next_send_at: null });
      results.push({ lead_id: row.lead_id, action: 'stopped', reason: 'lead missing' });
      continue;
    }

    // ── THE GUARD ── re-read the conversation NOW. Whatever was true when this
    // step was scheduled is irrelevant; what matters is whether they have
    // spoken since.
    const facts = await threadFacts(api, { chat_id: row.chat_id || chatIdOf(lead), lead, limit: 50 });
    if (facts.answered) {
      await writeRow(api, row.lead_id, {
        status: 'answered', answered_at: facts.last_in_at || t, stop_reason: 'answered', next_send_at: null,
      });
      await api.log('outreach_cohort_answered', { lead_id: row.lead_id, name: lead.name || null });
      results.push({ lead_id: row.lead_id, name: lead.name || null, action: 'answered — removed from automation' });
      continue;
    }

    const seq = await sequenceOf(api, row.cohort_id);
    const cad = effectiveCadence(cadence, await cohortRow(api, row.cohort_id));
    const rendered = renderSequence(seq, lead);
    // Re-validated at send time, not just at go-live: the cohort's copy or the
    // prospect's fields may have changed since approval, and a message with an
    // unfilled variable must never leave.
    if (rendered.blocked) {
      await writeRow(api, row.lead_id, { status: 'stopped', stop_reason: 'blocked', last_error: rendered.blocked, next_send_at: null });
      results.push({ lead_id: row.lead_id, name: lead.name || null, action: 'blocked', error: rendered.blocked });
      continue;
    }
    const step = rendered.steps[row.step];
    // 'always' steps ignore the reply rule — but the answered check above has
    // already removed anyone who replied, so this only matters for a cohort
    // whose earlier steps were skipped.
    if (step && !WIRED_CHANNELS.includes(step.channel)) {
      await writeRow(api, row.lead_id, {
        status: 'stopped', stop_reason: 'channel not wired',
        last_error: `step ${row.step + 1} is set to ${step.channel}, which cannot send yet`, next_send_at: null,
      });
      results.push({ lead_id: row.lead_id, name: lead.name || null, action: 'blocked', error: `${step.channel} is not wired to a sender` });
      continue;
    }
    let text = step?.text;
    if (!text) {
      await writeRow(api, row.lead_id, { status: 'done', stop_reason: 'exhausted', next_send_at: null });
      results.push({ lead_id: row.lead_id, name: lead.name || null, action: 'sequence finished' });
      continue;
    }

    // The operator's edit of THIS message for THIS person wins over the
    // cohort's copy — re-rendered here, so an edit that has since become
    // unfillable stops rather than sending with a hole in it.
    if (row.override_text && row.override_step === row.step) {
      const o = renderBody(row.override_text, lead);
      if (o.missing.length || o.unknown.length) {
        await writeRow(api, row.lead_id, {
          status: 'stopped', stop_reason: 'blocked',
          last_error: `edited message has unfilled ${[...o.missing, ...o.unknown].join(', ')}`, next_send_at: null,
        });
        results.push({ lead_id: row.lead_id, name: lead.name || null, action: 'blocked', error: 'edited message cannot be filled in' });
        continue;
      }
      text = o.text;
    }

    // ── THE APPROVAL GATE ── the operator has to have signed off THIS message,
    // not merely this person. Deliberately does NOT clear next_send_at: the row
    // stays due and keeps showing at the top of its cohort until it is approved
    // or removed, so an unapproved message is a visible backlog rather than
    // something that quietly disappeared from the run.
    if (cadence.require_approval && row.approved_step !== row.step) {
      results.push({
        lead_id: row.lead_id, name: lead.name || null, action: 'awaiting approval',
        step: row.step, text,
      });
      continue;
    }

    if (dry) {
      results.push({
        lead_id: row.lead_id, name: lead.name || null, action: 'would send',
        step: row.step, chat_id: row.chat_id, text,
      });
      continue;
    }

    try {
      await api.gateway('whatsapp', 'send', { chatId: row.chat_id, text });
      sent++;
      const nextStep = row.step + 1;
      const more = nextStep < rendered.length;
      await writeRow(api, row.lead_id, {
        step: nextStep,
        last_sent_at: now(),
        last_sent_text: text,
        last_error: null,
        status: more ? 'active' : 'done',
        stop_reason: more ? null : 'exhausted',
        // The gap to the next message is the cohort's own, authored beside the copy.
        next_send_at: more ? nextWindowOpening(now() + delayForStep(seq, nextStep), cad) : null,
      });
      await api.log('outreach_cohort_sent', { lead_id: row.lead_id, name: lead.name || null, step: row.step, chars: text.length });
      results.push({ lead_id: row.lead_id, name: lead.name || null, action: 'sent', step: row.step });
    } catch (e) {
      const err = String(e?.message || e).slice(0, 300);
      // A failed send stops that prospect rather than retrying blindly — a
      // silent retry loop against a broken gateway is how duplicates happen.
      await writeRow(api, row.lead_id, { status: 'stopped', stop_reason: 'failed', last_error: err, next_send_at: null });
      await api.log('outreach_cohort_failed', { lead_id: row.lead_id, error: err });
      results.push({ lead_id: row.lead_id, name: lead.name || null, action: 'failed', error: err });
    }

    // Human spacing between sends, so a tick never machine-guns the gateway.
    if (!dry && sent < budget) {
      await new Promise((r) => setTimeout(r, Math.min(cadence.min_gap_minutes * 60000, 15000)));
    }
  }

  await api.log('outreach_cohort_tick', { due: due.length, sent, awaiting_approval: awaiting, dry_run: dry, live });
  return { ran: true, dry_run: dry, live, due: due.length, sent, awaiting_approval: awaiting, results };
}

// ── the tick, as five decisions instead of one function ─────────────────────
// The `outreach-cohort-tick` workflow needs the SAME behaviour as ordered steps
// an operator can read, re-run and audit one at a time: who is due → who has
// since answered → what would each of them receive → which of those did the
// operator sign off → send.
//
// What is deliberately NOT split is the claim-then-send loop at the end. The
// conversation must be re-read in the moment BEFORE each send and the step must
// advance in the same breath as it; batching those apart would let a reply that
// lands mid-run still collect its follow-up.

// STEP 1 — who is due, and how much room is left in the day.
export async function listDueMembers(api, { force = false, dry_run = null, limit = null } = {}) {
  const { cadence } = await loadCohortCadence(api);
  const live = await isLive(api);
  const dry = (dry_run === null || dry_run === undefined) ? !live : !!dry_run;
  const t = now();

  if (!force && !withinWindow(t, cadence)) {
    return {
      ran: false, reason: 'outside the sending window', due: [], budget: 0,
      dry_run: dry, live, awaiting_approval: 0, next_open: nextWindowOpening(t, cadence),
    };
  }

  // Whole-account daily ceiling. Counts real sends only, so dry runs never eat it.
  const sentToday = Number((await api.db.prepare(
    'SELECT COUNT(*) AS n FROM plugin_gtm_outreach_cohort_members WHERE last_sent_at IS NOT NULL AND last_sent_at > ?',
  ).bind(t - 86400000).first().catch(() => null))?.n || 0);
  const budget = Math.max(0, cadence.max_sends_per_day - sentToday);
  if (!budget && !dry) {
    return { ran: false, reason: `daily cap reached (${cadence.max_sends_per_day})`, due: [], budget: 0, dry_run: dry, live, awaiting_approval: 0 };
  }

  // APPROVED ROWS SORT FIRST — ordered rather than excluded because an
  // unapproved row still has to be LOOKED at: the reply check downstream is
  // what takes someone who answered out of the automation.
  const order = cadence.require_approval
    ? '(m.approved_step = m.step) DESC, m.next_send_at ASC'
    : 'm.next_send_at ASC';
  const due = ((await api.db.prepare(
    `SELECT m.* FROM plugin_gtm_outreach_cohort_members m
       LEFT JOIN plugin_gtm_outreach_cohorts c ON c.id = m.cohort_id
      WHERE m.status = 'active' AND m.next_send_at IS NOT NULL AND m.next_send_at <= ?
        AND COALESCE(c.status, 'active') = 'active'
      ORDER BY ${order} LIMIT ?`,
  ).bind(t, Math.min(limit || 25, 50)).all().catch(() => ({ results: [] }))).results) || [];

  // Counted separately so a tick that sends nothing can say WHY.
  const awaiting = cadence.require_approval ? Number((await api.db.prepare(
    `SELECT COUNT(*) AS n FROM plugin_gtm_outreach_cohort_members m
       LEFT JOIN plugin_gtm_outreach_cohorts c ON c.id = m.cohort_id
      WHERE m.status = 'active' AND m.next_send_at IS NOT NULL AND m.next_send_at <= ?
        AND COALESCE(c.status, 'active') = 'active'
        AND (m.approved_step IS NULL OR m.approved_step <> m.step)`,
  ).bind(t).first().catch(() => null))?.n || 0) : 0;

  return { ran: true, due, budget, dry_run: dry, live, awaiting_approval: awaiting };
}

// STEP 2 — anyone who has spoken since leaves the automation, permanently.
// Runs on EVERY due row, approved or not: filtering the unapproved out first
// would leave a prospect who replied sitting 'active' forever.
export async function retireAnsweredMembers(api, { due = [] } = {}) {
  const t = now();
  const kept = [];
  const retired = [];
  const unverified = [];
  for (const row of due) {
    const lead = await getLead(api, row.lead_id).catch(() => null);
    let facts = null;
    try {
      facts = await threadFacts(api, { chat_id: row.chat_id || chatIdOf(lead), lead, limit: 50 });
    } catch (e) {
      // Fail CLOSED: a conversation we could not read is one we cannot promise
      // is unanswered, so the row is dropped from this pass. Its send time is
      // untouched, so it stays due and is picked up again next tick.
      unverified.push({ lead_id: row.lead_id, name: lead?.name || null, error: String(e?.message || e).slice(0, 300) });
      continue;
    }
    if (!facts.answered) { kept.push(row); continue; }
    await writeRow(api, row.lead_id, {
      status: 'answered', answered_at: facts.last_in_at || t, stop_reason: 'answered', next_send_at: null,
    });
    await api.log('outreach_cohort_answered', { lead_id: row.lead_id, name: lead?.name || null });
    retired.push({ lead_id: row.lead_id, name: lead?.name || null, answered_at: facts.last_in_at || t });
  }
  return { due: kept, retired, unverified };
}

// STEP 3 — what each of them would actually receive. Fail-closed: a row whose
// message cannot be filled in is STOPPED here rather than sent with a hole in
// it.
export async function renderMemberMessages(api, { due = [] } = {}) {
  const seqCache = new Map();
  const sendable = [];
  const blocked = [];
  for (const row of due) {
    const lead = await getLead(api, row.lead_id).catch(() => null);
    if (!lead) {
      await writeRow(api, row.lead_id, { status: 'stopped', stop_reason: 'lead missing', next_send_at: null });
      blocked.push({ lead_id: row.lead_id, name: null, action: 'stopped', reason: 'lead missing' });
      continue;
    }
    const qId = row.cohort_id || DEFAULT_COHORT;
    if (!seqCache.has(qId)) seqCache.set(qId, await sequenceOf(api, qId));
    const seq = seqCache.get(qId);
    const rendered = renderSequence(seq, lead);
    if (rendered.blocked) {
      await writeRow(api, row.lead_id, { status: 'stopped', stop_reason: 'blocked', last_error: rendered.blocked, next_send_at: null });
      blocked.push({ lead_id: row.lead_id, name: lead.name || null, action: 'blocked', reason: rendered.blocked });
      continue;
    }
    const step = rendered.steps[row.step];
    if (step && !WIRED_CHANNELS.includes(step.channel)) {
      const reason = `step ${row.step + 1} is set to ${step.channel}, which cannot send yet`;
      await writeRow(api, row.lead_id, { status: 'stopped', stop_reason: 'channel not wired', last_error: reason, next_send_at: null });
      blocked.push({ lead_id: row.lead_id, name: lead.name || null, action: 'blocked', reason });
      continue;
    }
    let text = step?.text;
    if (!text) {
      await writeRow(api, row.lead_id, { status: 'done', stop_reason: 'exhausted', next_send_at: null });
      blocked.push({ lead_id: row.lead_id, name: lead.name || null, action: 'sequence finished', reason: 'the ladder is spent' });
      continue;
    }
    // The operator's edit of THIS message for THIS person wins over the
    // cohort's copy — re-rendered here, so an edit that has since become
    // unfillable stops rather than sending with a hole in it.
    if (row.override_text && row.override_step === row.step) {
      const o = renderBody(row.override_text, lead);
      if (o.missing.length || o.unknown.length) {
        const reason = `edited message has unfilled ${[...o.missing, ...o.unknown].join(', ')}`;
        await writeRow(api, row.lead_id, { status: 'stopped', stop_reason: 'blocked', last_error: reason, next_send_at: null });
        blocked.push({ lead_id: row.lead_id, name: lead.name || null, action: 'blocked', reason });
        continue;
      }
      text = o.text;
    }
    const nextStep = row.step + 1;
    sendable.push({
      lead_id: row.lead_id, name: lead.name || null, chat_id: row.chat_id,
      cohort_id: qId, step: row.step, approved_step: row.approved_step ?? null, text,
      // Everything the send step needs to arm the FOLLOWING message, resolved
      // here so it never has to re-render a sequence mid-send.
      more: nextStep < rendered.length,
      next_delay_ms: nextStep < rendered.length ? delayForStep(seq, nextStep) : null,
    });
  }
  return { sendable, blocked };
}

// STEP 4 — the approval gate. Approval is per (person, step): sending advances
// `step`, so a stored index stops matching by itself and the next message is
// un-approved by construction.
export async function gateMemberApprovals(api, { sendable = [] } = {}) {
  const { cadence } = await loadCohortCadence(api);
  if (!cadence.require_approval) return { sendable, awaiting: [], approval_required: false };
  const approved = [];
  const awaiting = [];
  for (const m of sendable) {
    if (m.approved_step === m.step) { approved.push(m); continue; }
    // Deliberately NO write: the row keeps its send time, so an unapproved
    // message stays visibly due at the top of its cohort rather than quietly
    // vanishing from the run.
    awaiting.push({ lead_id: m.lead_id, name: m.name, step: m.step, text: m.text });
  }
  return { sendable: approved, awaiting, approval_required: true };
}

// STEP 5 — send. THE LOOP THAT MUST NOT BE SPLIT: for each message the
// conversation is re-read in the moment before it leaves, the step advances in
// the same write as the send, and any failure STOPS that prospect rather than
// re-arming them. dry_run reports what would have gone and writes nothing.
export async function sendDueMessages(api, { sendable = [], budget = 0, dry_run = true } = {}) {
  const { cadence } = await loadCohortCadence(api);
  const dry = !!dry_run;
  const cohortCache = new Map();
  const results = [];
  let sent = 0;

  for (const m of sendable) {
    if (!dry && sent >= budget) { results.push({ lead_id: m.lead_id, name: m.name, action: 'deferred', reason: 'daily cap' }); continue; }
    if (dry) {
      results.push({ lead_id: m.lead_id, name: m.name, action: 'would send', step: m.step, chat_id: m.chat_id, text: m.text });
      continue;
    }

    // ── THE GUARD ── whatever was true when this step was rendered is
    // irrelevant; what matters is whether they have spoken since.
    const lead = await getLead(api, m.lead_id).catch(() => null);
    let facts = null;
    try {
      facts = await threadFacts(api, { chat_id: m.chat_id || chatIdOf(lead), lead, limit: 50 });
    } catch (e) {
      results.push({ lead_id: m.lead_id, name: m.name, action: 'held', reason: `could not verify the conversation (${String(e?.message || e).slice(0, 200)})` });
      continue;
    }
    if (facts.answered) {
      await writeRow(api, m.lead_id, {
        status: 'answered', answered_at: facts.last_in_at || now(), stop_reason: 'answered', next_send_at: null,
      });
      await api.log('outreach_cohort_answered', { lead_id: m.lead_id, name: m.name });
      results.push({ lead_id: m.lead_id, name: m.name, action: 'answered — removed from automation' });
      continue;
    }

    if (!cohortCache.has(m.cohort_id)) cohortCache.set(m.cohort_id, await cohortRow(api, m.cohort_id));
    const cad = effectiveCadence(cadence, cohortCache.get(m.cohort_id));
    try {
      await api.gateway('whatsapp', 'send', { chatId: m.chat_id, text: m.text });
      sent++;
      await writeRow(api, m.lead_id, {
        step: m.step + 1,
        last_sent_at: now(),
        last_sent_text: m.text,
        last_error: null,
        status: m.more ? 'active' : 'done',
        stop_reason: m.more ? null : 'exhausted',
        next_send_at: m.more ? nextWindowOpening(now() + (m.next_delay_ms || 0), cad) : null,
      });
      await api.log('outreach_cohort_sent', { lead_id: m.lead_id, name: m.name, step: m.step, chars: m.text.length });
      results.push({ lead_id: m.lead_id, name: m.name, action: 'sent', step: m.step });
    } catch (e) {
      const err = String(e?.message || e).slice(0, 300);
      await writeRow(api, m.lead_id, { status: 'stopped', stop_reason: 'failed', last_error: err, next_send_at: null });
      await api.log('outreach_cohort_failed', { lead_id: m.lead_id, error: err });
      results.push({ lead_id: m.lead_id, name: m.name, action: 'failed', error: err });
    }

    // Human spacing between sends, so a run never machine-guns the gateway.
    if (sent < budget) await new Promise((r) => setTimeout(r, Math.min(cadence.min_gap_minutes * 60000, 15000)));
  }

  await api.log('outreach_cohort_tick', { sendable: sendable.length, sent, dry_run: dry });
  return { sent, results, dry_run: dry };
}

// The host CRM on this install writes contacts; it has no deal pipeline, so
// promoting a lead or moving a deal stage reports one honest sentence and the
// rest of the outreach flow continues.
async function noDeals(mode) {
  return { ok: false, error: `CRM ${mode.replace('_', ' ')} is not available on this install. The contact is still written; deal stages live wherever you track them today.` };
}

// GTM plugin lib — outreach replies → pipeline. Ported from
// workers/api/src/lib/outreach-promote.js: the shared logic behind the two
// tools the replies-to-pipeline workflow orders.
//
// A reply is the strongest buying signal we get, so anyone who answered our
// LinkedIn outreach (plugin_gtm_li_prospects.replied_at) or our GTM WhatsApp
// outreach (an inbound message after our first send) should land in the sales
// pipeline — created if new, advanced if they're already there. The matching +
// create/update rules are the reasoning, so they live HERE (a tool may reason);
// the workflow itself just runs collect → promote in order, holding no logic.
//
// The rules (which stage a reply lands at, whether to ever move a further-along
// deal backward, the stage order) live in the editable
// `plugin-gtm-outreach-promotion` knowledge doc, seeded with a default on
// first read.
//
// Plugin boundary: clients/contacts are HOST tables — read-only here (declared
// host_reads, pure SELECTs). Every write goes through the host `crm` gateway:
//   promote      — turn a GTM lead into a client + mirrored contact
//   write_contact — upsert a contact
//   update_deal  — move a deal on the board
// Note: the SQL replace() the host used for phone matching reads as a write
// verb to the plugin SQL scanner, so digit matching happens in JS over pure
// SELECT rows instead.
//
// Lib contract: no imports; every exported function takes `api` first. The
// helpers the host version imported from gtm.js / gtm-outreach.js (getLead,
// contactStatuses) are duplicated here, per the lib rules.

const PROMO_SLUG = 'plugin-gtm-outreach-promotion';

export const PROMOTION_DEFAULTS = {
  replied_stage: 'lead',       // where a reply lands a person on the board
  advance_only: true,          // never move a further-along deal backward
  // board order low → high; a reply advances toward `replied_stage` but never
  // past where the deal already is. 'target' is the raw-promotion stage.
  stage_rank: ['target', 'lead', 'talking', 'discovery', 'offer-sent', 'reviewing', 'won'],
  tag: 'replied',              // tag stamped on the client + contact
};

function promoSeedBody(cfg) {
  return `Outreach replies → pipeline — how an answered outreach becomes a deal.

When someone replies to our LinkedIn outreach or our GTM WhatsApp outreach, the
replies-to-pipeline workflow pulls them in and puts them on the sales
board. A brand-new person is created as a \`prospect\` client at \`replied_stage\`;
someone already on the board is advanced to \`replied_stage\` — but only forward:
with \`advance_only\`, a deal already at (say) \`offer-sent\` is left where it is, we
never drag it back to \`lead\` just because a message came in.

\`stage_rank\` is the board order used to decide "forward". \`tag\` is stamped on the
client and contact so replied-driven entries are filterable. Matching to an
existing record is by: the GTM lead's linked client, then a contact with the same
phone or LinkedIn URL, then a client whose name matches — so re-running never
duplicates anyone.

\`\`\`json
${JSON.stringify(cfg, null, 2)}
\`\`\`
`;
}

function sanitizePromotion(src) {
  const out = { ...PROMOTION_DEFAULTS };
  if (!src || typeof src !== 'object') return out;
  if (typeof src.replied_stage === 'string' && src.replied_stage.trim()) out.replied_stage = src.replied_stage.trim();
  if (typeof src.advance_only === 'boolean') out.advance_only = src.advance_only;
  if (Array.isArray(src.stage_rank) && src.stage_rank.every((s) => typeof s === 'string') && src.stage_rank.length) out.stage_rank = src.stage_rank;
  if (typeof src.tag === 'string') out.tag = src.tag.trim();
  return out;
}

export async function loadPromotion(api) {
  try {
    const doc = await api.knowledge(PROMO_SLUG);
    if (!doc) {
      await api.saveKnowledge(PROMO_SLUG, {
        title: 'Outreach · replies → pipeline rules',
        body: promoSeedBody(PROMOTION_DEFAULTS),
      }).catch(() => {});
      return { ...PROMOTION_DEFAULTS, source: 'defaults' };
    }
    const m = String(doc.body || '').match(/```json\s*([\s\S]*?)```/);
    return { ...sanitizePromotion(m ? JSON.parse(m[1]) : null), source: m ? 'doc' : 'defaults' };
  } catch {
    return { ...PROMOTION_DEFAULTS, source: 'defaults' };
  }
}

export async function savePromotion(api, patch = {}) {
  const cur = await loadPromotion(api);
  const next = sanitizePromotion({ ...cur, ...patch });
  await api.saveKnowledge(PROMO_SLUG, {
    title: 'Outreach · replies → pipeline rules',
    body: promoSeedBody(next),
  });
  await api.log('outreach_promotion_updated', next);
  return { ...next, source: 'doc' };
}

// ── duplicated helpers (host imports the lib contract forbids) ──────────────

// wa timestamps are ms in this store, but old rows may be seconds — normalize
const waMs = (t) => (t == null ? null : (t < 1e12 ? t * 1000 : t));
// phone → canonical +digits form (strips spaces, dashes, RTL marks, parens)
const canonPhone = (p) => { const d = String(p || '').replace(/\D/g, ''); return d ? `+${d}` : null; };
const cusOf = (phone) => { const c = canonPhone(phone); return c ? `${c.slice(1)}@c.us` : null; };
// what the host's SQL replace(...) chain did to a stored phone before the
// endsWith LIKE — spaces, dashes and parens removed, nothing else
const cleanStoredPhone = (p) => String(p || '').replace(/[ \-()]/g, '');

async function getLead(api, id) {
  return api.db.prepare('SELECT * FROM plugin_gtm_leads WHERE id = ?').bind(id).first();
}

// ── contact status: the "who did I contact / who replied" layer ─────────────
// Duplicated from the host gtm-outreach contactStatuses (lib files may not
// import each other). Derived per lead from what ACTUALLY happened across BOTH
// channels, no new state to maintain:
//   contacted  — either the engine sent (plugin_gtm_sends), OR you messaged the
//                lead by hand in WhatsApp (wa_messages from_me=1 on the chat)
//   replied    — an INBOUND wa message (from_me=0) on that lead's chat AFTER
//                our first outbound touch
// Leads reach a WhatsApp chat two ways: a plain "<digits>@c.us" DM, or a
// "<lid>@lid" identity chat — resolved to the lead's phone through wa_lid_map.
// Everything is batched (IN() chunks); no per-lead query, no correlated
// subquery (a correlated join here blows D1's per-query CPU budget).
async function contactStatuses(api, leadIds = []) {
  const out = new Map();
  if (!leadIds.length) return out;
  for (const id of leadIds) out.set(id, { contact_status: 'not_contacted', first_contacted_at: null, last_contacted_at: null, sends: 0, replied_at: null });

  // 1. engine sends (plugin_gtm_sends) — first/last/count per lead
  const eng = new Map(); // lead_id → {first, last, n}
  for (let i = 0; i < leadIds.length; i += 80) {
    const chunk = leadIds.slice(i, i + 80);
    const r = await api.db.prepare(
      `SELECT lead_id, min(created_at) AS first_at, max(created_at) AS last_at, count(*) AS n
       FROM plugin_gtm_sends WHERE status='sent' AND lead_id IN (${chunk.map(() => '?').join(',')}) GROUP BY lead_id`,
    ).bind(...chunk).all();
    for (const row of r.results || []) eng.set(row.lead_id, { first: row.first_at, last: row.last_at, n: row.n });
  }

  // 2. lead phones → candidate chat_ids (c.us + any mapped lids)
  const cusToLead = new Map(); // "<digits>@c.us" → lead_id
  for (let i = 0; i < leadIds.length; i += 80) {
    const chunk = leadIds.slice(i, i + 80);
    const r = await api.db.prepare(
      `SELECT id, normalized_phone FROM plugin_gtm_leads WHERE id IN (${chunk.map(() => '?').join(',')})`,
    ).bind(...chunk).all();
    for (const row of r.results || []) {
      const cus = cusOf(row.normalized_phone);
      if (cus) cusToLead.set(cus, row.id);
    }
  }
  const cusList = [...cusToLead.keys()];
  const chatToLead = new Map(cusToLead); // chat_id (c.us or lid) → lead_id
  // resolve lids for these phones via wa_lid_map (pn is "<digits>@c.us")
  for (let i = 0; i < cusList.length; i += 80) {
    const chunk = cusList.slice(i, i + 80);
    const r = await api.db.prepare(
      `SELECT lid, pn FROM wa_lid_map WHERE pn IN (${chunk.map(() => '?').join(',')})`,
    ).bind(...chunk).all();
    for (const row of r.results || []) {
      const lead = cusToLead.get(row.pn);
      if (lead && row.lid) chatToLead.set(row.lid, lead);
    }
  }

  // 3. one pass over wa_messages for all candidate chats — outbound + inbound
  const chatIds = [...chatToLead.keys()];
  const waByLead = new Map(); // lead_id → {out_first, out_last, out_n, in_last}
  for (let i = 0; i < chatIds.length; i += 80) {
    const chunk = chatIds.slice(i, i + 80);
    const r = await api.db.prepare(
      // Keep every outbound, but count an INBOUND only if it has real text — empty
      // from_me=0 rows (delivery/read receipts, echoes, often at the same
      // timestamp as our outbound) must never register as a reply.
      `SELECT chat_id, from_me, min(timestamp) AS first_ts, max(timestamp) AS last_ts, count(*) AS n
       FROM wa_messages
       WHERE chat_id IN (${chunk.map(() => '?').join(',')})
         AND (from_me = 1 OR (body IS NOT NULL AND length(trim(body)) > 0))
       GROUP BY chat_id, from_me`,
    ).bind(...chunk).all();
    for (const row of r.results || []) {
      const lead = chatToLead.get(row.chat_id);
      if (!lead) continue;
      const agg = waByLead.get(lead) || { out_first: null, out_last: null, out_n: 0, in_last: null };
      if (row.from_me === 1 || row.from_me === true) {
        agg.out_n += row.n;
        const f = waMs(row.first_ts); const l = waMs(row.last_ts);
        if (f != null && (agg.out_first == null || f < agg.out_first)) agg.out_first = f;
        if (l != null && (agg.out_last == null || l > agg.out_last)) agg.out_last = l;
      } else {
        // track LATEST inbound — a reply is any inbound after our first touch,
        // even on a chat that had prior history before outreach began
        const l = waMs(row.last_ts);
        if (l != null && (agg.in_last == null || l > agg.in_last)) agg.in_last = l;
      }
      waByLead.set(lead, agg);
    }
  }

  // 4. merge both channels per lead
  for (const id of leadIds) {
    const e = eng.get(id);
    const w = waByLead.get(id);
    const engFirst = e ? e.first : null;
    const engLast = e ? e.last : null;
    const waOutFirst = w && w.out_n ? w.out_first : null;
    const waOutLast = w && w.out_n ? w.out_last : null;
    const firsts = [engFirst, waOutFirst].filter((x) => x != null);
    const lasts = [engLast, waOutLast].filter((x) => x != null);
    if (!firsts.length) continue; // truly not contacted
    const firstAt = Math.min(...firsts);
    const lastAt = Math.max(...lasts);
    const sends = (e?.n || 0) + (w?.out_n || 0);
    // replied: any inbound landing after our first outbound touch
    let repliedAt = null;
    if (w && w.in_last != null && w.in_last > firstAt) repliedAt = w.in_last;
    out.set(id, {
      contact_status: repliedAt ? 'replied' : 'contacted',
      first_contacted_at: firstAt,
      last_contacted_at: lastAt,
      sends,
      replied_at: repliedAt,
    });
  }
  return out;
}

// ── STEP 1 tool body: collect everyone who replied, normalized ──────────────
export async function collectReplies(api) {
  const replies = [];

  // LinkedIn — replied_at is set when the operator marks a reply (li read APIs
  // are dead, so replies are operator-marked via li_outreach_mark_reply).
  try {
    const li = (await api.db.prepare(
      `SELECT id, name, company, role, public_id, replied_at FROM plugin_gtm_li_prospects WHERE replied_at IS NOT NULL`,
    ).all()).results || [];
    for (const p of li) {
      replies.push({
        source: 'li_outreach', ref_id: p.id, name: p.name, company: p.company || null,
        title: p.role || null, phone: null,
        linkedin: p.public_id ? `https://www.linkedin.com/in/${p.public_id}` : null,
        replied_at: p.replied_at || null, lead_id: null,
      });
    }
  } catch { /* plugin_gtm_li_prospects may be absent */ }

  // GTM WhatsApp — a lead whose contact status derives to 'replied' (inbound
  // after our first outbound). Reuse the same detector the Outreach tab uses.
  try {
    const ids = ((await api.db.prepare(
      `SELECT id FROM plugin_gtm_leads WHERE normalized_phone IS NOT NULL`,
    ).all()).results || []).map((r) => r.id);
    const statuses = await contactStatuses(api, ids);
    for (const [leadId, st] of statuses) {
      if (st.contact_status !== 'replied') continue;
      const lead = await getLead(api, leadId);
      if (!lead) continue;
      replies.push({
        source: 'gtm_whatsapp', ref_id: leadId, name: lead.name || null, company: lead.company || null,
        title: lead.position || null, phone: lead.normalized_phone || lead.phone || null,
        linkedin: lead.linkedin || null, replied_at: st.replied_at || null,
        lead_id: leadId, client_id: lead.client_id || null,
      });
    }
  } catch { /* gtm tables may be absent */ }

  return { ok: true, replies, counts: { total: replies.length, li_outreach: replies.filter((r) => r.source === 'li_outreach').length, gtm_whatsapp: replies.filter((r) => r.source === 'gtm_whatsapp').length } };
}

// find an existing client for a reply: GTM link → contact phone/linkedin → name
// (clients/contacts are host reads — pure SELECTs, matching in JS)
async function findExistingClient(api, reply) {
  if (reply.client_id) {
    const c = await api.db.prepare('SELECT id, name, stage, status FROM clients WHERE id = ?').bind(reply.client_id).first();
    if (c) return c;
  }
  const phone = canonPhone(reply.phone);
  if (phone) {
    const rows = (await api.db.prepare(
      `SELECT ct.phone AS ct_phone, cl.id, cl.name, cl.stage, cl.status
       FROM contacts ct JOIN clients cl ON cl.id = ct.client_id
       WHERE ct.client_id IS NOT NULL AND ct.phone IS NOT NULL`,
    ).all().catch(() => ({ results: [] }))).results || [];
    const hit = rows.find((r) => cleanStoredPhone(r.ct_phone).endsWith(phone.slice(1)));
    if (hit) return { id: hit.id, name: hit.name, stage: hit.stage, status: hit.status };
  }
  if (reply.linkedin) {
    const slug = String(reply.linkedin).replace(/\/+$/, '').split('/').pop();
    if (slug) {
      const row = await api.db.prepare(
        `SELECT cl.id, cl.name, cl.stage, cl.status FROM contacts ct JOIN clients cl ON cl.id = ct.client_id
         WHERE ct.client_id IS NOT NULL AND ct.linkedin_url LIKE ? LIMIT 1`,
      ).bind(`%${slug}%`).first().catch(() => null);
      if (row) return row;
    }
  }
  if (reply.name) {
    const like = reply.company ? `${reply.name} (${reply.company})` : reply.name;
    const row = await api.db.prepare('SELECT id, name, stage, status FROM clients WHERE name = ? LIMIT 1').bind(like).first().catch(() => null);
    if (row) return row;
  }
  return null;
}

// Find THIS person's existing contact under a client (phone → linkedin → name),
// so a re-run updates it instead of inserting a duplicate. The promote workflow
// runs hourly; without this, an already-promoted lead grew one new contact row
// every hour.
async function findClientContact(api, clientId, reply) {
  const phone = canonPhone(reply.phone);
  if (phone) {
    const rows = (await api.db.prepare(
      'SELECT id, phone FROM contacts WHERE client_id = ? AND phone IS NOT NULL',
    ).bind(clientId).all().catch(() => ({ results: [] }))).results || [];
    const hit = rows.find((r) => cleanStoredPhone(r.phone).endsWith(phone.slice(1)));
    if (hit) return hit.id;
  }
  if (reply.linkedin) {
    const slug = String(reply.linkedin).replace(/\/+$/, '').split('/').pop();
    if (slug) {
      const r = await api.db.prepare('SELECT id FROM contacts WHERE client_id = ? AND linkedin_url LIKE ? LIMIT 1').bind(clientId, `%${slug}%`).first().catch(() => null);
      if (r) return r.id;
    }
  }
  if (reply.name) {
    const r = await api.db.prepare('SELECT id FROM contacts WHERE client_id = ? AND full_name = ? LIMIT 1').bind(clientId, reply.name).first().catch(() => null);
    if (r) return r.id;
  }
  return null;
}

// Find the person's contact ANYWHERE (no client scoping) — used by the
// no-lead new-person path below so the hourly workflow updates one contact
// instead of inserting a duplicate every run.
async function findAnyContact(api, reply) {
  const phone = canonPhone(reply.phone);
  if (phone) {
    const rows = (await api.db.prepare(
      'SELECT id, phone FROM contacts WHERE phone IS NOT NULL',
    ).all().catch(() => ({ results: [] }))).results || [];
    const hit = rows.find((r) => cleanStoredPhone(r.phone).endsWith(phone.slice(1)));
    if (hit) return hit.id;
  }
  if (reply.linkedin) {
    const slug = String(reply.linkedin).replace(/\/+$/, '').split('/').pop();
    if (slug) {
      const r = await api.db.prepare('SELECT id FROM contacts WHERE linkedin_url LIKE ? LIMIT 1').bind(`%${slug}%`).first().catch(() => null);
      if (r) return r.id;
    }
  }
  if (reply.name) {
    const r = await api.db.prepare('SELECT id FROM contacts WHERE full_name = ? LIMIT 1').bind(reply.name).first().catch(() => null);
    if (r) return r.id;
  }
  return null;
}

// ── STEP 2 tool body: create/advance each reply on the board ────────────────
export async function promoteRepliesToPipeline(api, { replies } = {}) {
  const rules = await loadPromotion(api);
  const rank = (s) => { const i = rules.stage_rank.indexOf(s); return i < 0 ? -1 : i; };
  const targetRank = rank(rules.replied_stage);
  const list = Array.isArray(replies) ? replies : [];

  const out = { ok: true, total: list.length, created: 0, advanced: 0, unchanged: 0, skipped: 0, details: [] };
  for (const reply of list) {
    if (!reply || !reply.name) { out.skipped++; out.details.push({ ref_id: reply?.ref_id, skipped: 'no name' }); continue; }
    try {
      const existing = await findExistingClient(api, reply);

      if (existing) {
        // advance forward only (per advance_only); keep a further-along deal put.
        // A stage that isn't on the rank list (null, 'active', 'nurture', 'lost',
        // a real client already won) is UNKNOWN, not "earlier" — never drag those
        // to replied_stage. Only a known, genuinely-earlier stage advances.
        let moved = false;
        const curRank = rank(existing.stage);
        const knownEarlier = curRank >= 0 && curRank < targetRank;
        if (!rules.advance_only || knownEarlier) {
          if (existing.stage !== rules.replied_stage) {
            await noDeals('update_deal', { id: existing.id, patch: { stage: rules.replied_stage }, actor: 'outreach-promote' });
            moved = true;
          }
        }
        // make sure a contact carries the reply provenance — UPDATE the existing
        // contact (found by phone/linkedin/name) rather than inserting a new one
        // every hourly run.
        const contactId = await findClientContact(api, existing.id, reply);
        await api.gateway('crm', 'write_contact', {
          id: contactId || undefined,
          full_name: reply.name, phone: reply.phone || undefined, company: reply.company || undefined,
          title: reply.title || undefined, linkedin_url: reply.linkedin || undefined,
          status: 'lead', source: 'cold_outreach', client_id: existing.id, tags: [rules.tag, reply.source],
          updated_by: 'outreach-promote',
        }).catch(() => {});
        if (reply.lead_id) await api.db.prepare('UPDATE plugin_gtm_leads SET client_id=?, updated_at=? WHERE id=? AND client_id IS NULL').bind(existing.id, Date.now(), reply.lead_id).run().catch(() => {});
        if (moved) out.advanced++; else out.unchanged++;
        out.details.push({ ref_id: reply.ref_id, source: reply.source, name: reply.name, client_id: existing.id, action: moved ? 'advanced' : 'unchanged', stage: rules.replied_stage });
        await api.log('outreach_promoted', { source: reply.source, name: reply.name, client_id: existing.id, action: moved ? 'advanced' : 'matched' });
        continue;
      }

      // NEW, with a GTM lead behind it — the crm gateway's promote mode creates
      // the client + mirrored contact + links the lead, same as the host did.
      if (reply.lead_id) {
        const r = await noDeals('promote', { id: reply.lead_id, actor: 'outreach-promote' });
        if (!r?.ok) { out.skipped++; out.details.push({ ref_id: reply.ref_id, source: reply.source, name: reply.name, skipped: r?.error || 'promote failed' }); continue; }
        const clientId = r.client_id;
        await noDeals('update_deal', { id: clientId, patch: { stage: rules.replied_stage }, actor: 'outreach-promote' }).catch(() => {});
        out.created++;
        out.details.push({ ref_id: reply.ref_id, source: reply.source, name: reply.name, client_id: clientId, action: 'created', stage: rules.replied_stage });
        await api.log('outreach_promoted', { source: reply.source, name: reply.name, client_id: clientId, action: 'created' });
        continue;
      }

      // NEW, no GTM lead behind it (a LinkedIn reply). The host created a
      // client directly here, but the crm gateway has no client-create mode —
      // so the best the plugin can do is upsert the person as a tagged contact
      // carrying the reply provenance (deduped by phone/linkedin/name so the
      // hourly workflow never duplicates). No deal opens on the board until
      // the crm gateway grows a write_client mode.
      const contactId = await findAnyContact(api, reply);
      await api.gateway('crm', 'write_contact', {
        id: contactId || undefined,
        full_name: reply.name, phone: reply.phone || undefined, company: reply.company || undefined,
        title: reply.title || undefined, linkedin_url: reply.linkedin || undefined,
        status: 'lead', source: 'cold_outreach', tags: [rules.tag, reply.source],
        notes: `Replied to ${reply.source === 'li_outreach' ? 'LinkedIn' : 'WhatsApp'} outreach.${reply.title ? ' ' + reply.title + (reply.company ? ' at ' + reply.company : '') + '.' : ''}${reply.linkedin ? ' LinkedIn: ' + reply.linkedin : ''}`,
        created_by: 'outreach-promote', updated_by: 'outreach-promote',
      });
      if (contactId) {
        out.unchanged++;
        out.details.push({ ref_id: reply.ref_id, source: reply.source, name: reply.name, client_id: null, action: 'unchanged', stage: rules.replied_stage, note: 'contact refreshed — crm gateway has no client-create mode, no deal opened' });
      } else {
        out.created++;
        out.details.push({ ref_id: reply.ref_id, source: reply.source, name: reply.name, client_id: null, action: 'created', stage: rules.replied_stage, note: 'contact only — crm gateway has no client-create mode, no deal opened' });
        await api.log('outreach_promoted', { source: reply.source, name: reply.name, client_id: null, action: 'created' });
      }
    } catch (e) {
      out.skipped++;
      out.details.push({ ref_id: reply.ref_id, source: reply.source, name: reply.name, skipped: String(e?.message || e) });
    }
  }
  return out;
}

// GTM plugin lib — outreach thread stats. Ported from
// workers/api/src/lib/outreach-threads.js: the "did they reply, is it a real
// conversation, is there a reply I haven't caught, how did they feel" layer
// behind the Digest KPI drawer. One row per conversation (WhatsApp chat_id or
// LinkedIn conversation_urn) in plugin_gtm_outreach_threads, refreshed from the
// messages we already have (wa_messages is a declared host READ). Sentiment is
// scored on the LATEST inbound message through the `llm` gateway (writer_small
// tier) and cached — re-scored only when a newer inbound arrives, against the
// editable `plugin-gtm-outreach-sentiment` knowledge doc. Everything logs; the
// model is reached only via the gateway.
//
// Lib contract: no imports; every exported function takes `api` first.

const waMs = (t) => (t == null ? null : (Number(t) < 1e12 ? Number(t) * 1000 : Number(t)));

// ── sentiment rubric — editable knowledge doc (same pattern as the
// outreach-signature rubric in outreach-classify.mjs) so the operator can
// sharpen "what counts as negative" without a deploy.
const SENT_SLUG = 'plugin-gtm-outreach-sentiment';

const SENTIMENT_DEFAULT = `How to score a prospect's reply to our cold outreach:
- positive — warm, interested, thankful, asks a question back, wants to talk.
- neutral — genuinely open/undecided: polite acknowledgement with no lean either way, a logistics question, "let me think about it", "circle back in a few months" with no rejection attached.
- negative — ANY decline or rejection, even when phrased politely or briefly. This includes: "not interested", "not for me", "no thanks", "not right now" (as a brush-off, not a real future intent), "please stop messaging me", "remove me", ignoring the pitch to complain, or a reply that is clearly trying to end the conversation rather than continue it.

The single most common mistake is calling a POLITE rejection "neutral" just because the wording is soft. Politeness is a tone, not a signal of openness — judge the actual decision being communicated, not how nicely it's phrased. "Thanks but not interested" and "not interested, thanks" are BOTH negative, not neutral.

Judge tone in Hebrew or English. Some Hebrew phrasings that are NEGATIVE (not neutral) even though they read as polite: "לא מעוניין/ת", "לא רלוונטי כרגע" (when used as a brush-off), "תוריד/י אותי מהרשימה", "תפסיק/י לשלוח לי", "לא בשבילי".`;

function sentimentSeedBody(rubric) {
  return `Outreach sentiment — the rubric used to score how a prospect feels in their reply, for the Digest KPI drawer.

Scored on the LATEST inbound message per thread, cached until a newer inbound arrives. Edit this note to tune what counts as negative vs neutral — e.g. add phrasings from your market that read as a polite decline. Changes apply to newly-scored replies with no deploy.

---
${rubric}
`;
}

// writer_small tier from the host `llm-models` doc (a declared host knowledge
// read). Plugins see no env vars, so the doc value falls straight back to the
// coded default (the host's own default) instead of ANTHROPIC_SMALL_MODEL.
const WRITER_SMALL_DEFAULT = 'claude-haiku-4-5-20251001';
function cleanModelId(v) {
  const s = String(v ?? '').trim();
  return s && s.length <= 120 && !/\s{2,}|\n/.test(s) ? s : null;
}
async function writerSmallModel(api) {
  try {
    const doc = await api.knowledge('llm-models');
    const m = String(doc?.body || '').match(/```json\s*([\s\S]*?)```/);
    const src = m ? JSON.parse(m[1]) : {};
    return cleanModelId(src.writer_small) || WRITER_SMALL_DEFAULT;
  } catch {
    return WRITER_SMALL_DEFAULT;
  }
}

export async function loadSentimentRubric(api) {
  try {
    const doc = await api.knowledge(SENT_SLUG);
    if (!doc) {
      await api.saveKnowledge(SENT_SLUG, {
        title: 'Outreach · sentiment rubric (Digest)',
        body: sentimentSeedBody(SENTIMENT_DEFAULT),
      }).catch(() => {});
      return { rubric: SENTIMENT_DEFAULT, source: 'defaults' };
    }
    const body = String(doc.body || '');
    const idx = body.indexOf('\n---\n');
    return { rubric: (idx >= 0 ? body.slice(idx + 5) : body).trim() || SENTIMENT_DEFAULT, source: 'doc' };
  } catch {
    return { rubric: SENTIMENT_DEFAULT, source: 'defaults' };
  }
}

export async function saveSentimentRubric(api, rubric) {
  const clean = String(rubric || '').trim() || SENTIMENT_DEFAULT;
  await api.saveKnowledge(SENT_SLUG, {
    title: 'Outreach · sentiment rubric (Digest)',
    body: sentimentSeedBody(clean),
  });
  await api.log('outreach_sentiment_rubric_updated', { chars: clean.length });
  return { rubric: clean, source: 'doc' };
}

// ── sentiment: score how the prospect FEELS in their reply ──────────────────
async function scoreSentiment(api, items) { // items: [{ key, text }]
  const map = new Map();
  if (!items.length) return map;
  const model = await writerSmallModel(api);
  const { rubric } = await loadSentimentRubric(api);
  const system = `You score how a prospect FEELS in their reply to our cold outreach, for a sales dashboard. For each numbered reply, classify the sentiment as positive, neutral, or negative.

${rubric}

Return STRICT JSON: {"scores":[{"i":<number>,"s":"positive|neutral|negative","why":"<=5 words"}]}`;
  for (let i = 0; i < items.length; i += 25) {
    const chunk = items.slice(i, i + 25);
    const prompt = chunk.map((it, n) => `[${n}] ${String(it.text || '').replace(/\s+/g, ' ').slice(0, 240)}`).join('\n');
    let raw;
    try { raw = await api.gateway('llm', 'text', { system, prompt, model, max_tokens: Math.min(2000, 300 + chunk.length * 40), heavy: false }); }
    catch { continue; }
    const s = String(raw || '');
    const re = /"i"\s*:\s*(\d+)[\s\S]{0,40}?"s"\s*:\s*"(positive|neutral|negative)"(?:[\s\S]{0,24}?"why"\s*:\s*"([^"]{0,80})")?/g;
    let m;
    while ((m = re.exec(s)) !== null) {
      const it = chunk[Number(m[1])];
      if (it) map.set(it.key, { sentiment: m[2], reason: (m[3] || '').slice(0, 80) });
    }
  }
  return map;
}

async function upsertThread(api, row) {
  const t = Date.now();
  await api.db.prepare(
    `INSERT INTO plugin_gtm_outreach_threads (key, channel, name, replied, uncaught, msgs_in, msgs_out, last_inbound_text, last_inbound_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
     ON CONFLICT(key) DO UPDATE SET
       name=excluded.name, replied=excluded.replied, uncaught=excluded.uncaught,
       msgs_in=excluded.msgs_in, msgs_out=excluded.msgs_out,
       last_inbound_text=excluded.last_inbound_text, last_inbound_at=excluded.last_inbound_at,
       updated_at=excluded.updated_at`,
  ).bind(row.key, row.channel, row.name || null, row.replied, row.uncaught, row.msgs_in || 0, row.msgs_out || 0,
    row.last_inbound_text || null, row.last_inbound_at || 0, t).run().catch(() => {});
}

async function scoreAndStore(api, needScore) {
  if (!needScore.length) return 0;
  const scores = await scoreSentiment(api, needScore);
  let n = 0;
  for (const it of needScore) {
    const sc = scores.get(it.key);
    if (!sc) continue;
    await api.db.prepare(
      'UPDATE plugin_gtm_outreach_threads SET sentiment=?, sentiment_reason=?, sentiment_at=? WHERE key=?',
    ).bind(sc.sentiment, sc.reason, it.at || 0, it.key).run().catch(() => {});
    n++;
  }
  if (n) await api.log('outreach_sentiment_scored', { n });
  return n;
}

// ── LinkedIn: refresh from the daemon's per-conversation threads summary ─────
export async function refreshLiThreads(api, threads = []) {
  if (!Array.isArray(threads) || !threads.length) return 0;
  const needScore = [];
  for (const th of threads) {
    const key = th.conversation_urn;
    if (!key) continue;
    const replied = (th.msgs_in || 0) > 0 ? 1 : 0;
    // uncaught = they have unread messages for us, OR they replied and the last
    // message in the thread is theirs (we haven't answered since).
    const uncaught = ((th.unread_count || 0) > 0 || (replied && !th.last_from_me)) ? 1 : 0;
    const ex = await api.db.prepare('SELECT sentiment_at FROM plugin_gtm_outreach_threads WHERE key=?').bind(key).first().catch(() => null);
    await upsertThread(api, {
      key, channel: 'linkedin', name: th.name, replied, uncaught,
      msgs_in: th.msgs_in, msgs_out: th.msgs_out,
      last_inbound_text: th.last_inbound_text, last_inbound_at: th.last_inbound_at || 0,
    });
    if (replied && th.last_inbound_text && (!ex || ex.sentiment_at !== (th.last_inbound_at || 0))) {
      needScore.push({ key, text: th.last_inbound_text, at: th.last_inbound_at || 0 });
    }
  }
  await scoreAndStore(api, needScore);
  return threads.length;
}

// ── WhatsApp: refresh from wa_messages for the given outreach chats ──────────
export async function refreshWaThreads(api, chats = []) { // chats: [{ key(chat_id), name }]
  const needScore = [];
  // Only messages with REAL text count. WhatsApp stores empty-body from_me=0
  // rows (delivery/read receipts, echoes) — often at the exact timestamp of our
  // own outbound — which must NOT be mistaken for a reply.
  const HAS_TEXT = "body IS NOT NULL AND length(trim(body)) > 0";
  for (const chat of chats) {
    const key = chat.key;
    if (!key) continue;
    const agg = await api.db.prepare(
      `SELECT SUM(CASE WHEN from_me=1 THEN 1 ELSE 0 END) AS out_n,
              SUM(CASE WHEN from_me=0 THEN 1 ELSE 0 END) AS in_n
       FROM wa_messages WHERE chat_id=? AND ${HAS_TEXT}`,
    ).bind(key).first().catch(() => null);
    // latest REAL inbound vs latest REAL outbound — uncaught only if they spoke last
    const lastIn = await api.db.prepare(`SELECT body, timestamp FROM wa_messages WHERE chat_id=? AND from_me=0 AND ${HAS_TEXT} ORDER BY timestamp DESC LIMIT 1`).bind(key).first().catch(() => null);
    const lastOut = await api.db.prepare(`SELECT timestamp FROM wa_messages WHERE chat_id=? AND from_me=1 AND ${HAS_TEXT} ORDER BY timestamp DESC LIMIT 1`).bind(key).first().catch(() => null);
    const replied = (agg?.in_n || 0) > 0 ? 1 : 0;
    const lastInAt = lastIn ? waMs(lastIn.timestamp) : 0;
    const lastOutAt = lastOut ? waMs(lastOut.timestamp) : 0;
    const uncaught = (replied && lastInAt > lastOutAt) ? 1 : 0;
    const ex = await api.db.prepare('SELECT sentiment_at FROM plugin_gtm_outreach_threads WHERE key=?').bind(key).first().catch(() => null);
    await upsertThread(api, {
      key, channel: 'whatsapp', name: chat.name, replied, uncaught,
      msgs_in: agg?.in_n || 0, msgs_out: agg?.out_n || 0,
      last_inbound_text: lastIn?.body || null, last_inbound_at: lastInAt,
    });
    if (replied && lastIn?.body && (!ex || ex.sentiment_at !== lastInAt)) needScore.push({ key, text: lastIn.body, at: lastInAt });
  }
  await scoreAndStore(api, needScore);
  return chats.length;
}

// ── read: stats for a set of conversation keys (for the drawer) ─────────────
export async function getThreadStats(api, keys = []) {
  const out = new Map();
  const uniq = [...new Set(keys.filter(Boolean))];
  for (let i = 0; i < uniq.length; i += 90) {
    const c = uniq.slice(i, i + 90);
    const r = (await api.db.prepare(
      `SELECT key, channel, replied, uncaught, msgs_in, msgs_out, sentiment, sentiment_reason, last_inbound_text, last_inbound_at
       FROM plugin_gtm_outreach_threads WHERE key IN (${c.map(() => '?').join(',')})`,
    ).bind(...c).all().catch(() => ({ results: [] }))).results || [];
    for (const row of r) out.set(row.key, row);
  }
  return out;
}

// GTM plugin — lib/outreach-wa.mjs. The prospect conversation surface, ported
// from workers/api/src/lib/outreach-wa.js (contract v2.1 pack lib).
//
// The Outreach module's default tab is a WhatsApp inbox filtered to PROSPECTS:
// people who came through Prospecting/GTM and who we have a WhatsApp DM with.
// Three reads and one compose live here; the tools/ wrappers stay thin.
//
//   listProspectThreads — the conversation list (latest first, uncaught pinned)
//   readProspectThread  — one chat's full history + which lead it belongs to
//   draftReply          — the suggested draft under the composer
//
// The lead <-> chat join is DERIVED, not stored: plugin_gtm_leads
// .normalized_phone maps to the WhatsApp DM id `<digits>@c.us` (toChatId,
// duplicated below per the lib-imports-nothing contract). No new table.
//
// Everything the operator might want to tune — how many threads, how much
// history, how the draft is written — lives in the
// `plugin-gtm-outreach-reply-drafting` knowledge doc, seeded on first read.
// The model is reached ONLY through the `llm` gateway.
//
// Port notes (behavioral deltas from the host original):
// - Host tables wa_messages / wa_chats / wa_lid_map are SELECT-only here
//   (requires.host_reads). The original's best-effort `syncFromGateway` call in
//   conversationStatesFor wrote host tables and had no gateway mode, so it is
//   DROPPED: freshness now relies on the host's own webhook/cron sync.
// - loadModelConfig is replaced by a read of the host `llm-models` doc (declare
//   in requires.knowledge); env-var fallbacks are unreachable from a plugin, so
//   a missing/unparseable doc falls back to the coded writer default.
// - Helpers from whatsapp.js / gtm.js / gtm-outreach.js / outreach-threads.js /
//   outreach-cadence.js are DUPLICATED here (lib files import nothing).

const DRAFT_SLUG = 'plugin-gtm-outreach-reply-drafting';

// Bound every fan-out: D1 chokes on an IN() list that grows with the data, so
// every lookup below chunks at this width (the getThreadStats precedent).
const CHUNK = 80;

// WhatsApp timestamps arrive as seconds from some gateway builds and ms from
// others; normalise so ordering never silently inverts.
const waMs = (t) => (t == null ? null : (Number(t) < 1e12 ? Number(t) * 1000 : Number(t)));
const digitsOf = (s) => String(s || '').replace(/\D/g, '');

// Duplicated from host lib/whatsapp.js toChatId (pure).
function toChatId(input) {
  const s = String(input || '').trim();
  if (!s) throw new Error('chatId required');
  if (s.endsWith('@c.us') || s.endsWith('@g.us') || s.endsWith('@lid')) return s;
  const digits = s.replace(/\D/g, '');
  if (!digits) throw new Error(`could not parse chatId from ${input}`);
  return `${digits}@c.us`;
}

// The DM id for a phone. Group chats are never prospects — this is 1:1 only.
const chatIdForPhone = (phone) => { try { return toChatId(phone); } catch { return null; } };

// Duplicated from host lib/util.js safeJSON (pure).
function safeJSON(s) {
  if (!s) return null;
  try { return JSON.parse(s); } catch { return s; }
}

// Duplicated from host lib/whatsapp.js recentMessages — a SELECT on the host
// wa_messages table (declared host read).
async function recentMessages(api, { chat_id = null, limit = 200 } = {}) {
  const sql = chat_id
    ? 'SELECT * FROM wa_messages WHERE chat_id = ? ORDER BY timestamp DESC LIMIT ?'
    : 'SELECT * FROM wa_messages ORDER BY timestamp DESC LIMIT ?';
  const stmt = chat_id ? api.db.prepare(sql).bind(chat_id, limit) : api.db.prepare(sql).bind(limit);
  const r = await stmt.all();
  return (r.results || []).map((m) => ({ ...m, raw_json: safeJSON(m.raw_json) }));
}

// Duplicated from host lib/outreach-threads.js getThreadStats — the thread KPI
// cache, renamed to the plugin namespace.
async function getThreadStats(api, keys = []) {
  const out = new Map();
  const uniq = [...new Set(keys.filter(Boolean))];
  for (let i = 0; i < uniq.length; i += 90) {
    const c = uniq.slice(i, i + 90);
    const r = (await api.db.prepare(
      `SELECT key, channel, replied, uncaught, msgs_in, msgs_out, sentiment, sentiment_reason, last_inbound_text, last_inbound_at
       FROM plugin_gtm_outreach_threads WHERE key IN (${c.map(() => '?').join(',')})`,
    ).bind(...c).all().catch(() => ({ results: [] }))).results || [];
    for (const row of r) out.set(row.key, row);
  }
  return out;
}

// Duplicated from host lib/gtm-outreach.js readAngles.
async function readAngles(api, leadId) {
  const r = await api.db.prepare('SELECT payload, updated_at FROM plugin_gtm_outreach_angles WHERE lead_id = ?').bind(leadId).first();
  if (!r) return null;
