// GTM plugin — approve_message. Ported verbatim from the host outreach tools
// (workers/api/src/tools/outreach.js); env → api, shared code in the pack's
// parallel lib (same function names, api first).

import { approveMessages } from './outreach-cohorts.mjs';

export const def = {
  name: 'approve_message',
  description: 'Approve (or withdraw approval of) the NEXT message for one or more cohort members. Approval is per message, not per person: it applies to the exact step each prospect is on and lapses by itself the moment that message is sent, so the following one needs approving again. Approving neither schedules nor sends. Refuses anyone who has replied, whose copy cannot be filled in, or whose edited message has a hole in it — a 200 does not mean everyone was approved, read the refused list.',
  input_schema: {
    type: 'object',
    properties: {
      lead_ids: { type: 'array', items: { type: 'string' } },
      approve: { type: 'boolean', description: 'false to withdraw a previous approval. Defaults to true.' },
    },
    required: ['lead_ids'],
  },
};

export async function run(api, input) {
  return approveMessages(api, {
    lead_ids: input?.lead_ids || [], approve: input?.approve !== false,
  });
}

// GTM plugin — audit_identities. Ported verbatim from
// workers/api/src/tools/prospecting.js; def and result shape unchanged.

import { auditLinkedinIdentity } from './gtm.mjs';

export const def = {
  name: 'audit_identities',
  description: "Audit every prospect whose assigned LinkedIn profile does not match their name (the namesake / wrong-person bug) and report match / unverifiable / mismatch. REPORT ONLY — fixing a mismatch is the clean-identity workflow, run once per reported lead. Use after big imports, or whenever a LinkedIn assignment looks wrong.",
  input_schema: { type: 'object', properties: {}, required: [] },
};

export async function run(api) {
  return auditLinkedinIdentity(api, { fix: false });
}

// GTM plugin — cancel_scheduled_send. Ported verbatim from the host outreach
// tools (workers/api/src/tools/outreach.js); env → api, shared code in the
// pack's parallel lib (same function names, api first).

import { cancelOrDismiss } from './gtm-schedule.mjs';

export const def = {
  name: 'cancel_scheduled_send',
  description: 'Cancel a scheduled send before it fires, or dismiss a terminal failed/partial one (the reply says which of the two happened). A claimed, in-flight send cannot be un-fired — that is the fail-closed guarantee, and it is an operator decision to review rather than a retry queue.',
  input_schema: {
    type: 'object',
    properties: { schedule_id: { type: 'string', description: 'the ss_ schedule id' } },
    required: ['schedule_id'],
  },
};

export async function run(api, input) {
  return cancelOrDismiss(api, input?.schedule_id);
}

// GTM plugin — collect_replies. Ported verbatim from the host outreach tools
// (workers/api/src/tools/outreach.js); env → api, shared code in the pack's
// parallel lib (same function names, api first).

import { collectReplies } from './outreach-promote.mjs';

export const def = {
  name: 'collect_replies',
  description: 'Collect everyone who REPLIED to our outreach — LinkedIn (prospects marked replied) and WhatsApp (an inbound message after our first send) — normalized to {source, name, company, title, phone, linkedin, lead_id, replied_at}. Read-only. Step 1 of the outreach-replies-to-pipeline workflow; also useful alone to answer "who has answered".',
  input_schema: { type: 'object', properties: {}, required: [] },
};

export async function run(api) {
  return collectReplies(api);
}

// GTM plugin — company_context. The host route POST /api/gtm/leads/:id/
// company-context ran the company-context WORKFLOW; a pack has no workflows, so
// this tool runs the same pass via the pack lib (companyContextForLead: theorg
// org chart + LinkedIn headcount + LinkedIn open roles, cached on the lead).
// Result mirrors what the surface reads: { company, org_people, org_status,
// org_note, staff_count, open_roles, errors[] } — partial by design, a failed
// leg is listed in errors while whatever landed is kept.

import { companyContextForLead } from './gtm.mjs';

export const def = {
  name: 'company_context',
  description: "Fetch everything about the COMPANY behind one lead in a single pass: theorg's org chart, LinkedIn's headcount and open roles. Cached on the lead — a row checked recently is skipped unless refresh:true. Partial by design: the legs fail independently and a failure is reported in errors[] while the facts already on file are kept. Feeds the ICP match.",
  input_schema: {
    type: 'object',
    properties: {
      id: { type: 'string' },
      refresh: { type: 'boolean', description: 'ignore the cache and re-fetch every leg' },
    },
    required: ['id'],
  },
};

export async function run(api, input) {
  if (!input?.id) return { error: 'id required' };
  return companyContextForLead(api, input.id, { refresh: !!input.refresh });
}

// GTM plugin — compose_reply. Ported verbatim from the host outreach tools
// (workers/api/src/tools/outreach.js); env → api, shared code in the pack's
// parallel lib (same function names, api first).

import { composeReply } from './outreach-wa.mjs';

export const def = {
  name: 'compose_reply',
  description: "Write ONE reply to a prospect who has answered, grounded in the conversation, the saved angle and the drafting rules — a single model call. A no-op passthrough when the context already carries a draft (pick_next_bubble found an approved bubble), so an approved message is never overwritten. Returns a suggestion only; sending is a separate operator action via send_whatsapp.",
  input_schema: {
    type: 'object',
    properties: {
      prospect: { type: 'object', description: 'the prospect card from read_prospect_thread' },
      messages: { type: 'array', items: { type: 'object' }, description: 'the conversation, oldest first' },
      angles: { type: 'array', items: { type: 'object' }, description: 'saved angles from read_lead_angles' },
      rules: { type: 'string', description: 'the drafting rules text from read_drafting_rules' },
      limits: { type: 'object', description: 'the drafting limits from read_drafting_rules' },
      answered: { type: 'boolean' },
      draft: { type: 'string', description: 'an already-picked draft — present means passthrough' },
      source: { type: 'string', description: "where an already-picked draft came from ('angle' | 'template')" },
      needs_compose: { type: 'boolean', description: 'set by pick_next_bubble when a fresh reply is wanted' },
      force_llm: { type: 'boolean', description: 'compose even when a draft is already present' },
    },
