            <Truecaller size={12} /> truecaller
          </a>
        )}
        <button onClick={toPipeline} disabled={busy || !!lead.client_id} className={btn + ' h-7'}>
          {lead.client_id ? 'in pipeline ✓' : busy ? '…' : '→ pipeline'}
