// Boundary to ONE service: SerpApi (google search results as JSON). The key
// lives in this pack's own table; the operator pastes it to Nyo. Fetch and
// translate only.
async function key(api) {
  const r = await api.DB.prepare("SELECT value FROM plugin_gtm_connections WHERE name = 'serp_api_key'").first().catch(() => null);
  return r?.value || null;
}
export const gateway = {
  slug: 'serp',
  service: 'SerpApi (serpapi.com)',
  description: 'Search-result lookups for prospecting. Needs a SerpApi key.',
  capability: 'search',
  modes: {
    status: async (api) => ({ connected: !!(await key(api)), label: 'SerpApi' }),
    search: async (api, input) => {
      const k = await key(api);
      if (!k) return { ok: false, error: 'SerpApi is not connected. Create a key at serpapi.com and paste it to Nyo.' };
      const q = String(input?.query || input?.q || '').trim();
      if (!q) return { ok: false, error: 'query required' };
      const num = Math.min(Math.max(Number(input?.limit || input?.num) || 10, 1), 20);
      const url = `https://serpapi.com/search.json?engine=google&q=${encodeURIComponent(q)}&num=${num}&api_key=${encodeURIComponent(k)}`;
      try {
        const r = await fetch(url, { signal: AbortSignal.timeout(25000) });
        const text = await r.text();
        let d = null; try { d = JSON.parse(text); } catch { /* not json */ }
        if (!r.ok) return { ok: false, error: String(d?.error || `HTTP ${r.status}`).slice(0, 200) };
        const results = (d?.organic_results || []).slice(0, num).map((x) => ({
          title: x?.title || '', url: x?.link || '', snippet: x?.snippet || null, position: x?.position ?? null,
        })).filter((x) => x.url);
        return { ok: true, query: q, results };
      } catch (e) { return { ok: false, error: String(e?.message || e).slice(0, 200) }; }
    },
  },
};

// Boundary to ONE service: People Data Labs person enrichment. Key in the
// pack's own table, pasted to Nyo. Fetch and translate only.
async function key(api) {
  const r = await api.DB.prepare("SELECT value FROM plugin_gtm_connections WHERE name = 'pdl_api_key'").first().catch(() => null);
  return r?.value || null;
}
export const gateway = {
  slug: 'pdl',
  service: 'People Data Labs (api.peopledatalabs.com)',
  description: 'Person enrichment for prospecting. Needs a People Data Labs key.',
  modes: {
    status: async (api) => ({ connected: !!(await key(api)), label: 'People Data Labs' }),
    person: async (api, input) => {
      const k = await key(api);
      if (!k) return { ok: false, error: 'People Data Labs is not connected. Create a key at peopledatalabs.com and paste it to Nyo.' };
      const params = new URLSearchParams();
      for (const f of ['email', 'profile', 'phone', 'name', 'company', 'first_name', 'last_name']) {
        if (input?.[f]) params.set(f, String(input[f]));
      }
      if (![...params.keys()].length) return { ok: false, error: 'give at least one of email, profile, phone, or name plus company' };
      try {
        const r = await fetch(`https://api.peopledatalabs.com/v5/person/enrich?${params}`, {
          signal: AbortSignal.timeout(25000), headers: { 'X-Api-Key': k },
        });
        const text = await r.text();
        let d = null; try { d = JSON.parse(text); } catch { /* not json */ }
        if (r.status === 404) return { ok: true, found: false, person: null };
        if (!r.ok) return { ok: false, error: String(d?.error?.message || d?.error || `HTTP ${r.status}`).slice(0, 200) };
        return { ok: true, found: true, person: d?.data ?? d, likelihood: d?.likelihood ?? null };
      } catch (e) { return { ok: false, error: String(e?.message || e).slice(0, 200) }; }
    },
  },
};

// Boundary to ONE service: Twilio Lookup (is this number real, what carrier).
// Account SID and auth token live in the pack's own table.
async function creds(api) {
  const r = await api.DB.prepare("SELECT name, value FROM plugin_gtm_connections WHERE name IN ('twilio_sid','twilio_token')").all().catch(() => null);
  const map = Object.fromEntries((r?.results || []).map((x) => [x.name, x.value]));
  return map.twilio_sid && map.twilio_token ? { sid: map.twilio_sid, token: map.twilio_token } : null;
}
export const gateway = {
  slug: 'twilio',
  service: 'Twilio Lookup (lookups.twilio.com)',
  description: 'Phone number validation. Needs a Twilio account SID and auth token.',
  modes: {
    status: async (api) => ({ connected: !!(await creds(api)), label: 'Twilio Lookup' }),
    lookup: async (api, input) => {
      const c = await creds(api);
      if (!c) return { ok: false, error: 'Twilio is not connected. Paste the account SID and auth token to Nyo.' };
      const phone = String(input?.phone || input?.number || '').trim();
      if (!phone) return { ok: false, error: 'phone required' };
      try {
        const r = await fetch(`https://lookups.twilio.com/v2/PhoneNumbers/${encodeURIComponent(phone)}`, {
          signal: AbortSignal.timeout(20000),
          headers: { Authorization: 'Basic ' + btoa(`${c.sid}:${c.token}`) },
        });
        const text = await r.text();
        let d = null; try { d = JSON.parse(text); } catch { /* not json */ }
        if (!r.ok) return { ok: false, error: String(d?.message || `HTTP ${r.status}`).slice(0, 200) };
        return { ok: true, phone: d?.phone_number || phone, valid: !!d?.valid, country: d?.country_code || null, type: d?.line_type_intelligence?.type || null };
      } catch (e) { return { ok: false, error: String(e?.message || e).slice(0, 200) }; }
    },
  },
};

